ipcMain.handle('system:get-codex-processes', async () => {
  try {
    const psOutput = await execAsync('ps -eo pid,ppid,pcpu,pmem,lstart,command', 3000);
    if (!psOutput) return [];

    const pidToTabId = new Map();
    for (const [tabId, ptyProcess] of terminals) {
      pidToTabId.set(ptyProcess.pid, tabId);
    }
    const ownershipSnapshot = await getDashboardOwnershipSnapshot();

    const rows = [];
    for (const line of psOutput.split('\n').filter(Boolean)) {
      const match = line.trim().match(/^\s*(\d+)\s+(\d+)\s+([\d.]+)\s+([\d.]+)\s+\w+\s+\w+\s+\d+\s+(\d+:\d+:\d+)\s+\d+\s+(.+)/);
      if (!match) continue;
      const command = match[6].trim();
      if (!command.includes('--no-alt-screen')) continue;
      if (!commandLooksLikeAiProcess(command, 'codex')) continue;

      rows.push({
        pid: Number(match[1]),
        ppid: Number(match[2]),
        cpu: match[3],
        mem: match[4],
        startTime: match[5].substring(0, 5),
        command,
      });
    }

    const codexPidSet = new Set(rows.map(row => row.pid));
    const processes = await Promise.all(rows.map(async (row) => {
      // Codex TUI normally appears as shell → node wrapper → vendor codex.
      // Show only the root wrapper so one chat is one Dashboard card.
      if (codexPidSet.has(row.ppid)) return null;

      const cwd = await getPidCwd(row.pid);
      if (!cwd) return null;

      const tabId = pidToTabId.get(row.ppid) || null;
      const owner = resolveDashboardProcessOwner(row.ppid, ownershipSnapshot, tabId);

      return {
        pid: row.pid,
        ppid: row.ppid,
        cwd,
        startTime: row.startTime,
        command: row.command,
        tabId,
        cpu: row.cpu,
        mem: row.mem,
        ...owner,
      };
    }));

    return processes.filter(Boolean);
  } catch {
    return [];
  }
});

async function buildDashboardElectronDevProcessesFromRows(rows) {
  const byPid = new Map(rows.map(row => [row.pid, row]));
  const selected = rows.filter(row => isElectronDevAppCommand(row.command) && row.pid !== process.pid);
  const processes = await Promise.all(selected.map(async (row) => {
    const cwd = await getDashboardPidCwd(row.pid);
    const projectName = getProjectNameFromCwd(cwd);
    const parent = byPid.get(row.ppid);
    const launcherPid = parent && isElectronLauncherCommand(parent.command) ? parent.pid : null;
    return {
      pid: row.pid,
      ppid: row.ppid,
      launcherPid,
      cwd,
      name: projectName || 'Electron app',
      startTime: row.startTime,
      command: row.command,
      cpu: row.cpu,
      mem: row.mem,
      isOrphan: row.ppid === 1,
    };
  }));

  return processes.sort((a, b) => {
    if (a.isOrphan !== b.isOrphan) return a.isOrphan ? -1 : 1;
    return a.name.localeCompare(b.name);
  });
}

async function buildDashboardAiProcessesFromRows(rows, kind, ownershipSnapshot, pidToTabId) {
  let selected = rows.filter(row => {
    const command = row.command || '';
    if (command.includes('Electron') || command.includes('electron')) return false;
    if (kind === 'codex') {
      return command.includes('--no-alt-screen') && commandLooksLikeAiProcess(command, 'codex');
    }
    return command.toLowerCase().includes(kind) && commandLooksLikeAiProcess(command, kind);
  });

  if (kind === 'codex') {
    const codexPidSet = new Set(selected.map(row => row.pid));
    selected = selected.filter(row => !codexPidSet.has(row.ppid));
  }

  const processes = await Promise.all(selected.map(async (row) => {
    const cwd = await getDashboardPidCwd(row.pid);
    if (!cwd) return null;

    const tabId = pidToTabId.get(row.ppid) || null;
    const owner = resolveDashboardProcessOwner(row.ppid, ownershipSnapshot, tabId);

    return {
      pid: row.pid,
      ppid: row.ppid,
      cwd,
      startTime: row.startTime,
      command: row.command,
      tabId,
      cpu: row.cpu,
      mem: row.mem,
      ...owner,
    };
  }));

  return processes.filter(Boolean);
}

function commandLooksLikeMcpProcess(command) {
  const text = String(command || '');
  if (text.includes('Electron') || text.includes('electron')) return false;
  return /mcp|terminal-server\.mjs|knowledge-server\.mjs|gemini-mcp|yougile-mcp|playwright-mcp|chrome-devtools|extension-mcp/i.test(text);
}

function buildDashboardMcpProcessesFromRows(rows, ownershipSnapshot) {
  const aliveCliPids = new Set();
  for (const [, ptyProcess] of terminals) aliveCliPids.add(ptyProcess.pid);

  for (const row of rows) {
    const command = row.command || '';
    if (command.includes('Electron') || command.includes('electron')) continue;
    if ((commandLooksLikeAiProcess(command, 'claude') || commandLooksLikeAiProcess(command, 'gemini')) && aliveCliPids.has(row.ppid)) {
      aliveCliPids.add(row.pid);
    }
  }

  const processes = [];
  for (const row of rows) {
    if (!commandLooksLikeMcpProcess(row.command)) continue;

    let name = 'mcp';
    const m1 = row.command.match(/([\w.-]+(?:-mcp|mcp-server|server\.mjs|extension-mcp\/index\.js))/i);
    if (m1) name = m1[1].replace(/^.*\//, '');
    else {
      const parts = row.command.split(/\s+/);
      name = (parts[1] || parts[0] || 'mcp').split('/').pop() || 'mcp';
    }

    const owner = resolveDashboardProcessOwner(row.ppid, ownershipSnapshot, null);
    const isAlive = aliveCliPids.has(row.ppid) || !!owner.protectedByApp;
    processes.push({
      pid: row.pid,
      ppid: row.ppid,
      cpu: row.cpu,
      mem: row.mem,
      startTime: row.startTime,
      command: row.command,
      name,
      isAlive,
      ownerInstance: owner.ownerInstance,
      ownerLabel: owner.ownerLabel,
      ownerPid: owner.ownerPid,
      protectedByApp: owner.protectedByApp,
      killable: owner.killable,
    });
  }
  return processes;
}

ipcMain.handle('system:get-dashboard-processes', async () => {
  try {
    const rows = await getDashboardProcessRows();
    const ownershipSnapshot = buildDashboardOwnershipSnapshotFromRows(rows);
    dashboardOwnershipSnapshotCache = ownershipSnapshot;

    const pidToTabId = new Map();
    for (const [tabId, ptyProcess] of terminals) {
      pidToTabId.set(ptyProcess.pid, tabId);
    }

    const [electronDev, claude, gemini, codex] = await Promise.all([
      buildDashboardElectronDevProcessesFromRows(rows),
      buildDashboardAiProcessesFromRows(rows, 'claude', ownershipSnapshot, pidToTabId),
      buildDashboardAiProcessesFromRows(rows, 'gemini', ownershipSnapshot, pidToTabId),
      buildDashboardAiProcessesFromRows(rows, 'codex', ownershipSnapshot, pidToTabId),
    ]);

    return {
      claude,
      gemini,
      codex,
      mcp: buildDashboardMcpProcessesFromRows(rows, ownershipSnapshot),
      electronDev,
    };
  } catch (err) {
    console.log('[DashboardProcesses] aggregate failed: ' + (err?.message || String(err)));
    return { claude: [], gemini: [], codex: [], mcp: [], electronDev: [] };
  }
});

ipcMain.handle('system:get-mcp-processes', async () => {
  try {
    // MCP servers run as `node /path/to/mcp-server.js` spawned by Claude/Gemini CLIs.
    // Filter by command containing "mcp" or known MCP paths to avoid catching unrelated node processes.
    const psOutput = await execAsync(
      'ps -eo pid,ppid,pcpu,pmem,lstart,command | grep -E "mcp|terminal-server\\.mjs|knowledge-server\\.mjs|gemini-mcp|yougile-mcp|playwright-mcp|chrome-devtools|extension-mcp" | grep -v grep | grep -v Electron',
      3000
    );
    if (!psOutput) return [];

    // Build alive PIDs set: our PTY shells + their CLI children (claude, gemini)
    const aliveCliPids = new Set();
    for (const [, ptyProcess] of terminals) aliveCliPids.add(ptyProcess.pid);
    // Also collect direct claude/gemini PIDs whose ppid is in our shells
    try {
      const cliPs = await execAsync('ps -eo pid,ppid,command | grep -E "claude|gemini" | grep -v grep', 2000);
      for (const line of (cliPs || '').split('\n').filter(Boolean)) {
        const m = line.trim().match(/^\s*(\d+)\s+(\d+)\s+(.+)/);
        if (!m) continue;
        const pid = Number(m[1]); const ppid = Number(m[2]); const cmd = m[3];
        if (cmd.includes('Electron') || cmd.includes('electron')) continue;
        if (aliveCliPids.has(ppid)) aliveCliPids.add(pid);
      }
    } catch {}

    const ownershipSnapshot = await getDashboardOwnershipSnapshot();
    const lines = psOutput.split('\n').filter(Boolean);
    const processes = [];
    for (const line of lines) {
      const match = line.trim().match(/^\s*(\d+)\s+(\d+)\s+([\d.]+)\s+([\d.]+)\s+\w+\s+\w+\s+\d+\s+(\d+:\d+:\d+)\s+\d+\s+(.+)/);
      if (!match) continue;
      const pid = Number(match[1]);
      const ppid = Number(match[2]);
      const cpu = match[3];
      const mem = match[4];
      const startTime = match[5].substring(0, 5);
      const command = match[6].trim();
      if (command.includes('Electron') || command.includes('electron')) continue;

      // Extract short name: last path component or args[0]
      let name = 'mcp';
      const m1 = command.match(/([\w.-]+(?:-mcp|mcp-server|server\.mjs|extension-mcp\/index\.js))/i);
      if (m1) name = m1[1].replace(/^.*\//, '');
      else { const parts = command.split(/\s+/); name = (parts[1] || parts[0] || 'mcp').split('/').pop() || 'mcp'; }

      // Alive = ppid is one of our PTY shells / CLI children OR it belongs
      // to another live custom-terminal instance (dev/prod protected).
      const owner = resolveDashboardProcessOwner(ppid, ownershipSnapshot, null);
      const isAlive = aliveCliPids.has(ppid) || !!owner.protectedByApp;
      processes.push({
        pid,
        ppid,
        cpu,
        mem,
        startTime,
        command,
        name,
        isAlive,
        ownerInstance: owner.ownerInstance,
        ownerLabel: owner.ownerLabel,
        ownerPid: owner.ownerPid,
        protectedByApp: owner.protectedByApp,
        killable: owner.killable,
      });
    }
    return processes;
  } catch {
    return [];
  }
});

ipcMain.handle('system:kill-process', async (event, pid) => {
  const targetPid = Number(pid);
  if (!Number.isInteger(targetPid) || targetPid <= 1) {
    return { success: false, error: 'invalid pid' };
  }

  try {
    const ownershipSnapshot = await getDashboardOwnershipSnapshot();
    const targetOwnerPid = findDashboardOwnerPid(targetPid, ownershipSnapshot);
    const targetParentPid = ownershipSnapshot.parentByPid.get(targetPid);
    const parentOwner = resolveDashboardProcessOwner(targetParentPid, ownershipSnapshot, null);
    if ((targetOwnerPid && targetOwnerPid !== process.pid) ||
        (parentOwner.protectedByApp && parentOwner.ownerPid !== process.pid)) {
      return { success: false, error: 'protected custom-terminal process' };
    }
  } catch {
    return { success: false, error: 'ownership check failed' };
  }

  try {
    await execAsync('kill ' + targetPid, 2000);
    return { success: true };
  } catch {
    // Try SIGKILL if graceful kill failed
    try {
      await execAsync('kill -9 ' + targetPid, 2000);
      return { success: true };
    } catch {
      return { success: false };
    }
  }
});

// BFS the OS process tree starting from rootPid and return all descendants
// (rootPid itself is NOT included). Async — uses `ps -eo pid,ppid` once,
// builds the parent→children map in JS, walks it without further syscalls.
// Used by terminal:deterministic-stop to find every process spawned from
// the PTY shell — including detached children like the Electron window
// that has its own session and does not receive PTY Ctrl+C.
async function findDescendantPids(rootPid) {
  if (!rootPid || !Number.isInteger(rootPid)) return [];
  let psOut;
  try {
    psOut = await execAsync('ps -axo pid=,ppid=', 2000);
  } catch (e) {
    console.log('[findDescendantPids] ps failed: ' + e.message);
    return [];
  }
  const children = new Map(); // ppid -> [pid, ...]
  for (const line of (psOut || '').split('\n')) {
    const m = line.trim().match(/^(\d+)\s+(\d+)$/);
    if (!m) continue;
    const pid = Number(m[1]);
    const ppid = Number(m[2]);
    if (!children.has(ppid)) children.set(ppid, []);
    children.get(ppid).push(pid);
  }
  const result = [];
  const queue = [rootPid];
  const seen = new Set([rootPid]);
  while (queue.length > 0) {
    const cur = queue.shift();
    const kids = children.get(cur) || [];
    for (const k of kids) {
      if (seen.has(k)) continue;
      seen.add(k);
      result.push(k);
      queue.push(k);
    }
  }
  return result;
}

// ========== Project port detector + killer ==========
// Detect declared ports from common config files in a project, then `lsof | kill`.
// Designed for the "free ports before start" toggle: solves the "address in use"
// case where a previous run crashed/Electron force-quit left the port held.
//
// Detection sources (in priority order):
// 1. package.json script env ignore-list — `NOTED_TERMINAL_IGNORE_PORTS=6379,9000 npm run dev`
// 2. package.json script env override — `NOTED_TERMINAL_PORTS=3000,5173 npm run dev`
// 3. package.json — `notedTerminal.ports: [3000, 5173]` (manual override)
// 4. vite.config.{ts,js,mjs} — server.port
// 5. .env / .env.local — app ports only: PORT=, BACKEND_PORT=, FRONTEND_PORT=
//    Infra ports like REDIS_PORT/POSTGRES_PORT/MINIO_PORT are intentionally
//    excluded: killing them can take down Docker/OrbStack port forwards.
// 6. NestJS main.ts — `app.listen(process.env.PORT || NNNN)` fallback literal
//
// Recursive: scans `cwd` AND immediate subfolders (for monorepos like uav/agrofield_back).
// Cached for 30s per cwd so repeated start→stop→start cycles don't re-grep.
const projectPortsCache = new Map(); // cwd → { ports: number[], ts: number }
const PROJECT_PORTS_CACHE_TTL = 30_000;
const INFRA_PORT_ENV_RE = /(^|_)(REDIS|POSTGRES|POSTGRESQL|PG|DATABASE|DB|MYSQL|MARIADB|MONGO|MONGODB|MINIO|S3|AWS|RABBITMQ|AMQP|KAFKA|ZOOKEEPER|ELASTICSEARCH|ELASTIC|OPENSEARCH|QDRANT|MEILISEARCH|CLICKHOUSE|PROMETHEUS|GRAFANA|LOKI|SMTP|MAIL|MEMCACHED)(_|$)/;
const PORT_ENV_KEY_RE = /([A-Z][A-Z0-9_]*_PORT|[A-Z][A-Z0-9_]*PORT|PORT)/;

function isInfraPortEnvKey(key) {
  const normalized = String(key || '').trim().toUpperCase();
  if (!normalized || normalized === 'PORT') return false;
  return INFRA_PORT_ENV_RE.test(normalized);
}

function addValidProjectPort(ports, value) {
  const p = Number(value);
  if (p >= 1024 && p <= 65535) ports.add(p);
}

function addPortList(ports, value) {
  String(value || '')
    .split(/[,\s]+/)
    .map(v => v.trim())
    .filter(Boolean)
    .forEach(v => addValidProjectPort(ports, v));
}

function extractScriptPortList(scripts, envName) {
  const ports = new Set();
  if (!scripts || typeof scripts !== 'object') return ports;

  const re = new RegExp("\\b" + envName + "=(?:\"([^\"]+)\"|'([^']+)'|([0-9,\\s]+))", 'g');
  for (const cmd of Object.values(scripts)) {
    if (typeof cmd !== 'string') continue;
    for (const m of cmd.matchAll(re)) {
      addPortList(ports, m[1] || m[2] || m[3]);
    }
  }

  return ports;
}

function extractPortsFromText(text, opts = {}) {
  const {
    configPorts = true,
    envPorts = true,
    listenPorts = true,
  } = opts;
  const ports = new Set();
  // vite.config: server: { port: 5181 } / port: 5181
  if (configPorts) {
    for (const m of text.matchAll(/\bport\s*:\s*(\d{2,5})\b/gi)) {
      addValidProjectPort(ports, m[1]);
    }
  }
  // .env / inline script env: PORT=3000, FRONTEND_PORT=5173, BACKEND_PORT=3001.
  // Do not include infra ports (REDIS_PORT, MINIO_PORT, etc.) in dev-server kill lists.
  if (envPorts) {
    const envPortRe = new RegExp('^' + PORT_ENV_KEY_RE.source + '\\s*=\\s*(\\d{2,5})\\b', 'gm');
    for (const m of text.matchAll(envPortRe)) {
      if (isInfraPortEnvKey(m[1])) continue;
      addValidProjectPort(ports, m[2]);
    }
  }
  // NestJS: app.listen(process.env.PORT || 3001) / app.listen(3001)
  if (listenPorts) {
    for (const m of text.matchAll(/\.listen\s*\(\s*(?:process\.env\.[A-Z_]+\s*\|\|\s*)?(\d{2,5})\b/g)) {
      addValidProjectPort(ports, m[1]);
    }
  }
  return Array.from(ports);
}

function scanProjectPorts(rootCwd, depth = 0) {
  const found = new Set();
  if (depth > 1) return found; // only direct subfolders, not deep recursion
  let entries = [];
  try { entries = fs.readdirSync(rootCwd, { withFileTypes: true }); } catch { return found; }

  // 1. package.json — explicit script ports, notedTerminal.ports override, inline env vars.
  if (depth === 0) {
    try {
      const pkgPath = path.join(rootCwd, 'package.json');
      if (fs.existsSync(pkgPath)) {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
        const scripts = pkg?.scripts;
        const ignoredScriptPorts = extractScriptPortList(scripts, 'NOTED_TERMINAL_IGNORE_PORTS');
        const explicitScriptPorts = extractScriptPortList(scripts, 'NOTED_TERMINAL_PORTS');
        if (explicitScriptPorts.size > 0) {
          for (const p of ignoredScriptPorts) explicitScriptPorts.delete(p);
          return explicitScriptPorts;
        }

        if (Array.isArray(pkg?.notedTerminal?.ports)) {
          for (const p of pkg.notedTerminal.ports) {
            addValidProjectPort(found, p);
          }
          for (const p of ignoredScriptPorts) found.delete(p);
          return found;
        }
        // Inline env vars in scripts (e.g. `NOTED_WEB_PORT=7979 electron-vite dev`)
        // — common pattern when the same project serves multiple ports and only
        // one is in vite.config. Without this, "kill dev-ports" misses the
        // detached server (Electron window held on a env-only port survives the
        // PTY Ctrl+C → user sees a second Dock icon spawn on restart).
        if (scripts && typeof scripts === 'object') {
          for (const cmd of Object.values(scripts)) {
            if (typeof cmd !== 'string') continue;
            const inlineEnvPortRe = new RegExp('\\b' + PORT_ENV_KEY_RE.source + '\\s*=\\s*(\\d{2,5})\\b', 'g');
            for (const m of cmd.matchAll(inlineEnvPortRe)) {
              if (isInfraPortEnvKey(m[1])) continue;
              addValidProjectPort(found, m[2]);
            }
          }
        }
      }
    } catch {}
  }

  // 2. Config files in this directory
  const configFiles = [
    'vite.config.ts', 'vite.config.js', 'vite.config.mjs',
    'electron.vite.config.ts', 'electron.vite.config.js', 'electron.vite.config.mjs',
  ];
  for (const f of configFiles) {
    try {
      const p = path.join(rootCwd, f);
      if (fs.existsSync(p)) {
        const txt = fs.readFileSync(p, 'utf8');
        for (const port of extractPortsFromText(txt, { envPorts: false, listenPorts: false })) found.add(port);
      }
    } catch {}
  }

  // 3. Env files: app ports only, not dependency/infra ports.
  const envFiles = ['.env', '.env.local', '.env.development'];
  for (const f of envFiles) {
    try {
      const p = path.join(rootCwd, f);
      if (fs.existsSync(p)) {
        const txt = fs.readFileSync(p, 'utf8');
        for (const port of extractPortsFromText(txt, { configPorts: false, listenPorts: false })) found.add(port);
      }
    } catch {}
  }

  // 4. NestJS main.ts pattern — `src/main.ts` if exists.
  // Only use listen() fallback when no explicit app port was found in package/config/env.
  if (found.size === 0) {
    try {
      const mainTs = path.join(rootCwd, 'src', 'main.ts');
      if (fs.existsSync(mainTs)) {
        const txt = fs.readFileSync(mainTs, 'utf8');
        for (const port of extractPortsFromText(txt, { envPorts: false, configPorts: false })) found.add(port);
      }
    } catch {}
  }

  // 5. Recurse into immediate subfolders that look like monorepo apps
  //    (skip node_modules, .git, dist, build, .next, etc.)
  if (depth === 0) {
    const skip = new Set(['node_modules', '.git', 'dist', 'build', '.next', '.vite', 'release', 'out', '.cache', 'coverage']);
    for (const ent of entries) {
      if (!ent.isDirectory() || skip.has(ent.name) || ent.name.startsWith('.')) continue;
      const sub = path.join(rootCwd, ent.name);
      for (const p of scanProjectPorts(sub, depth + 1)) found.add(p);
    }
  }

  if (depth === 0) {
    try {
      const pkgPath = path.join(rootCwd, 'package.json');
      if (fs.existsSync(pkgPath)) {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
        const ignoredScriptPorts = extractScriptPortList(pkg?.scripts, 'NOTED_TERMINAL_IGNORE_PORTS');
        for (const p of ignoredScriptPorts) found.delete(p);
      }
    } catch {}
  }

  return found;
}

// Diagnostic dump for hung-loader cases. Renderer can invoke this when busy-state
// is stuck and developer wants a snapshot of all per-tab state mainprocess holds.
// Returns plain JSON: tabId → { claudeTurnBusy, claudeSpinnerBusy, bridgeKnownSessions,
// bridgePidCache (reversed), watchdog status, claude PID alive }. Safe to call anytime.
ipcMain.handle('system:dump-claude-state', async () => {
  const pidByTab = new Map();
  for (const [pid, tid] of bridgePidCache) pidByTab.set(tid, pid);
  const allTabs = new Set([
    ...claudeTurnBusy.keys(),
    ...claudeSpinnerBusy.keys(),
    ...bridgeKnownSessions.keys(),
    ...pidByTab.keys(),
    ...claudeTurnWatchdog.keys(),
    ...claudeInterruptWatchers.keys(),
    ...claudeHookLastEvent.keys(),
  ]);
  const dump = { _hook: { connSeq: claudeHookConnSeq, eventSeq: claudeHookEventSeq, sockPath: CLAUDE_HOOK_SOCK, serverAlive: !!claudeHookServer }, _tabs: {} };
  const { execSync } = require('child_process');
  const now = Date.now();
  for (const tabId of allTabs) {
    const pid = pidByTab.get(tabId);
    let pidAlive = null;
    if (pid) {
      try { execSync('kill -0 ' + pid + ' 2>/dev/null'); pidAlive = true; }
      catch { pidAlive = false; }
    }
    const last = claudeHookLastEvent.get(tabId);
    dump._tabs[tabId] = {
      claudeTurnBusy: claudeTurnBusy.get(tabId),
      claudeSpinnerBusy: claudeSpinnerBusy.get(tabId),
      sessionId: bridgeKnownSessions.get(tabId) || null,
      claudePid: pid || null,
      pidAlive,
      turnWatchdog: claudeTurnWatchdog.has(tabId),
      interruptWatcher: claudeInterruptWatchers.has(tabId),
      lastHookEvent: last ? { event: last.event, ageMs: now - last.ts } : null,
    };
  }
  console.log('[Diag:Dump] ' + JSON.stringify(dump));
  return dump;
});

ipcMain.handle('system:detect-project-ports', async (event, cwd) => {
  if (!cwd) return { ports: [] };
  const cached = projectPortsCache.get(cwd);
  if (cached && (Date.now() - cached.ts) < PROJECT_PORTS_CACHE_TTL) {
    return { ports: cached.ports, cached: true };
  }
  const ports = Array.from(scanProjectPorts(cwd)).sort((a, b) => a - b);
  projectPortsCache.set(cwd, { ports, ts: Date.now() });
  console.log('[free-ports] Detected for ' + cwd + ': [' + ports.join(', ') + ']');
  return { ports, cached: false };
});

// Kill whatever holds the given ports. Returns per-port outcome.
// Used by the "free ports" toggle before npm-script start/restart/stop.
ipcMain.handle('system:free-project-ports', async (event, cwd) => {
  if (!cwd) return { success: false, error: 'no cwd', killed: [] };
  const cached = projectPortsCache.get(cwd);
  let ports;
  if (cached && (Date.now() - cached.ts) < PROJECT_PORTS_CACHE_TTL) {
    ports = cached.ports;
  } else {
    ports = Array.from(scanProjectPorts(cwd)).sort((a, b) => a - b);
    projectPortsCache.set(cwd, { ports, ts: Date.now() });
  }
  if (ports.length === 0) return { success: true, killed: [], skipped: true };
  const results = [];
  for (const port of ports) {
    try {
      const pidsOut = await execAsync('lsof -ti:' + port, 1500).catch(() => '');
      const pids = (pidsOut || '').trim().split(/\s+/).filter(Boolean);
      if (pids.length === 0) { results.push({ port, killed: 0 }); continue; }
      // SIGKILL right away — anything holding a port we're about to need is going down hard.
      // No grace period: free-ports semantics is "make the port available NOW", not "ask politely".
      await execAsync('kill -9 ' + pids.join(' '), 1500).catch(() => {});
      results.push({ port, killed: pids.length, pids: pids.map(Number) });
    } catch (e) {
      results.push({ port, error: String(e?.message || e) });
    }
  }
  const totalKilled = results.reduce((s, r) => s + (r.killed || 0), 0);
  console.log('[free-ports] cwd=' + cwd + ' results=' + JSON.stringify(results) + ' totalKilled=' + totalKilled);
  return { success: true, killed: results, totalKilled };
});

// Deterministic stop+optional-restart for a script/devServer tab.
//
// Replaces the legacy TabBar.tsx pattern of "Ctrl+C → setTimeout(300) → kill+!!".
// The 300ms guess broke for two reasons:
//   1. PTY Ctrl+C reaches the foreground process group (zsh + npm), but children
//      that detached from the controlling terminal (Electron BrowserWindow, vite
//      preview server fork) survive and keep holding ports — second Electron
//      icon appeared in the Dock on every restart.
//   2. setTimeout(300) is a guess. If npm took >300ms to die, `!!` ran while the
//      old process still held the port → "address already in use" loop.
//
// New algorithm — purely event-driven, no fixed waits:
//   1. BFS the PTY shell's process tree → every descendant PID
//   2. Send SIGTERM to all of them (independent of PTY group — kernel delivers
//      directly, no controlling-terminal requirement)
//   3. Poll kill(-0) on every PID + lsof on declared ports every 50ms
//   4. When BOTH conditions hold (all dead AND all ports free) → resolve
//   5. Watchdog: 2000ms total → SIGKILL anything still alive, repoll 500ms more
//   6. If {restart:true}: write `!!\r` to PTY (visible in scrollback, re-runs
//      the previous command). PTY shell is never killed — only its children.
//
// Emits IPC `terminal:stop-progress` so the UI can lock the ↻ button until done.
async function deterministicStopTerminal(tabId, restart = false, options = {}) {
  if (!tabId) return { success: false, error: 'no tabId' };
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no terminal' };

  const cwd = terminalProjects.get(tabId);
  const wantPortKill = !!useUIStore_freePortsToggle();
  let ports = [];
  if (wantPortKill && cwd) {
    const cached = projectPortsCache.get(cwd);
    if (cached && (Date.now() - cached.ts) < PROJECT_PORTS_CACHE_TTL) {
      ports = cached.ports;
    } else {
      ports = Array.from(scanProjectPorts(cwd)).sort((a, b) => a - b);
      projectPortsCache.set(cwd, { ports, ts: Date.now() });
    }
  }

  const emit = (phase, extra = {}) => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('terminal:stop-progress', { tabId, phase, ...extra });
    }
  };

  emit('starting');
  console.log('[DetermStop] tab=' + tabId + ' shellPid=' + term.pid + ' restart=' + restart + ' ports=[' + ports.join(',') + ']');

  const descendants = await findDescendantPids(term.pid);
  console.log('[DetermStop] tab=' + tabId + ' descendants=[' + descendants.join(',') + ']');

  if (descendants.length === 0 && ports.length === 0) {
    const state = terminalCommandState.get(tabId);
    if (state) {
      state.isRunning = false;
      clearTerminalCommandOrigin(tabId, state, 'deterministic-stop-empty');
      terminalCommandState.set(tabId, state);
    }
    emit('done', { killed: [], escalated: false, restarted: false });
    if (restart) {
      queueRestartRerunCommandMeta(tabId, options.commandMeta);
      try { term.write('!!\r'); } catch {}
    }
    return { success: true, killed: [], escalated: false, restarted: !!restart };
  }

  // Phase A: SIGINT to ALL descendants — equivalent to user typing Ctrl+C.
  // CRITICAL: the descendant tree might include Claude/Gemini CLIs (dev-server
  // wraps an agent runner, electron-vite spawns a subprocess that wraps claude,
  // user manually pipelined `npm run dev` into a claude harness, etc.). Claude
  // listens for SIGINT through Ink and flushes its in-flight JSONL turn before
  // exiting; raw SIGTERM bypasses Ink and leaves orphan parentUuid / phantom
  // references that break the next session resume.
  // See: fix-claude-2.1.x-phantom-parentuuid.md, fix-claude-busy-detection.md::3b,
  // переносимый-дизайн.md::Graceful exit через Ctrl+C, не SIGTERM первым.
  // npm/vite/electron-vite/electron also exit cleanly on SIGINT — it's the
  // historical "polite stop" signal that doesn't disadvantage anyone.
  for (const pid of descendants) {
    try { process.kill(pid, 'SIGINT'); } catch {}
  }
  emit('signaled', { pids: descendants, signal: 'SIGINT' });

  const stillHoldingPorts = async () => {
    if (ports.length === 0) return [];
    const held = [];
    for (const port of ports) {
      try {
        const out = await execAsync('lsof -ti:' + port, 800).catch(() => '');
        const pids = (out || '').trim().split(/\s+/).filter(Boolean);
        if (pids.length > 0) held.push({ port, pids: pids.map(Number) });
      } catch {}
    }
    return held;
  };

  const stillAlivePids = () => {
    const alive = [];
    for (const pid of descendants) {
      try { process.kill(pid, 0); alive.push(pid); } catch {}
    }
    return alive;
  };

  // Phase A: wait up to 700ms for SIGINT to land. This is the window where
  // Claude/Ink can finish writing the current JSONL record. If everything's
  // dead + ports free — done, no escalation needed (the common path for npm).
  const phaseAStart = Date.now();
  let escalated = false;
  let sigtermSent = false;
  while (true) {
    const alive = stillAlivePids();
    const heldPorts = await stillHoldingPorts();
    if (alive.length === 0 && heldPorts.length === 0) break;
    const elapsed = Date.now() - phaseAStart;

    // Phase B (700ms): SIGTERM still-alive. Not destructive — most processes
    // that ignore SIGINT (long-running daemons, some build wrappers) will
    // still cleanly handle SIGTERM. Claude that ignored SIGINT is already
    // post-flush by now (700ms is way past the 50-150ms flush window).
    if (!sigtermSent && elapsed >= 700) {
      sigtermSent = true;
      console.log('[DetermStop] tab=' + tabId + ' SIGINT ignored 700ms → SIGTERM alive=[' + alive.join(',') + ']');
      for (const pid of alive) {
        try { process.kill(pid, 'SIGTERM'); } catch {}
      }
      emit('signaled', { pids: alive, signal: 'SIGTERM' });
    }

    // Phase C (2000ms total): SIGKILL anything still alive + orphan port holders.
    if (elapsed >= 2000) {
      const orphanPidsByPort = new Set();
      for (const { pids } of heldPorts) for (const p of pids) orphanPidsByPort.add(p);
      const toKill = new Set([...alive, ...orphanPidsByPort]);
      console.log('[DetermStop] tab=' + tabId + ' SIGKILL escalate pids=[' + [...toKill].join(',') + ']');
      escalated = true;
      for (const pid of toKill) {
        try { process.kill(pid, 'SIGKILL'); } catch {}
      }
      emit('escalated', { pids: [...toKill] });
      // Final short wait for kernel to reap.
      const phaseBStart = Date.now();
      while (true) {
        const a2 = stillAlivePids();
        const h2 = await stillHoldingPorts();
        if (a2.length === 0 && h2.length === 0) break;
        if (Date.now() - phaseBStart >= 500) {
          console.log('[DetermStop] tab=' + tabId + ' WARN still alive after SIGKILL: alive=[' + a2.join(',') + '] held=' + JSON.stringify(h2));
          emit('done', { killed: descendants, escalated: true, restarted: false, residual: { alive: a2, heldPorts: h2 } });
          return { success: false, killed: descendants, escalated: true, residual: { alive: a2, heldPorts: h2 } };
        }
        await new Promise(r => setTimeout(r, 50));
      }
      break;
    }
    await new Promise(r => setTimeout(r, 50));
  }

  console.log('[DetermStop] tab=' + tabId + ' clean: all descendants dead, all ports free' + (escalated ? ' (after SIGKILL)' : ''));
  const stoppedState = terminalCommandState.get(tabId);
  if (stoppedState) {
    stoppedState.isRunning = false;
    clearTerminalCommandOrigin(tabId, stoppedState, 'deterministic-stop');
    terminalCommandState.set(tabId, stoppedState);
  }

  // Restart in the SAME shell — `!!` re-executes whatever was last typed.
  // Shell is untouched throughout: we never killed term.pid itself, only its
  // children. Bash/zsh history is intact, prompt is at fresh state.
  let restarted = false;
  if (restart) {
    queueRestartRerunCommandMeta(tabId, options.commandMeta);
    try { term.write('!!\r'); restarted = true; } catch (e) {
      console.log('[DetermStop] write !! failed: ' + e.message);
    }
  }
  emit('done', { killed: descendants, escalated, restarted });
  return { success: true, killed: descendants, escalated, restarted };
}

ipcMain.handle('terminal:deterministic-stop', async (_event, args) => {
  const { tabId, restart = false, commandMeta = null } = args || {};
  return deterministicStopTerminal(tabId, restart, { commandMeta });
});

// Small accessor for the "kill dev-ports" toggle (lives in renderer state).
// Mirrored to disk via app:setState — we read the SQLite-backed mirror here so
// terminal:deterministic-stop does not need to round-trip to the renderer.
function useUIStore_freePortsToggle() {
  try {
    const raw = projectManager?.db?.getAppState?.('freePortsBeforeStart');
    if (raw == null) return false;
    return raw === '1' || raw === 'true' || raw === true || raw === 1;
  } catch {
    return false;
  }
}

// Stop AI process (Claude/Gemini/Codex) in a tab WITHOUT closing the tab.
// Ctrl+C → SIGTERM → SIGKILL fallback. Shell stays alive.
function getAiProcessNameFromCommand(cmd) {
  const text = String(cmd || '');
  if (/(^|[\/\s])claude(\s|$)/.test(text)) return 'claude';
  if (/(^|[\/\s])gemini(\s|$)/.test(text)) return 'gemini';
  if (/(^|[\/\s])codex(\s|$)/.test(text) || text.includes('@openai/codex')) return 'codex';
  return null;
}

function finalizeStoppedAiCommandState(tabId, reason = 'manual-stop', options = {}) {
  if (!tabId) return;
  const processName = options?.processName || null;
  const exitCode = Number.isFinite(Number(options?.exitCode)) ? Number(options.exitCode) : 0;
  const forceEvent = options?.forceEvent === true;
  const state = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
  const wasRunning = state.isRunning === true;
  state.isRunning = false;
  state.lastExitCode = exitCode;
  terminalCommandState.set(tabId, state);
  if (processName) invalidateAiProcessLookupCache(tabId, processName);
  if (wasRunning || forceEvent) {
    console.log('[AICommandState] finished tab=' + String(tabId).slice(-12)
      + ' process=' + (processName || '-')
      + ' reason=' + reason
      + ' wasRunning=' + wasRunning
      + ' exitCode=' + exitCode);
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('terminal:command-finished', {
        tabId,
        exitCode,
        reason,
        commandType: processName || null,
      });
    }
  }
}

async function stopAiProcessInTab(tabId, options = {}) {
  const stopReason = options?.reason || 'manual-stop';
  const preserveCodexLaunchPayload = options?.preserveCodexLaunchPayload === true;
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'tab not found' };
  const requestedToolType = resolveAiToolTypeForTab(tabId, options?.toolType || null);
  if (requestedToolType) markAiStopping(tabId, requestedToolType, stopReason);
  const finishStop = (result, broadcastInactive = false) => {
    clearAiStopping(tabId, result?.success === false ? 'stop-failed' : stopReason, {
      broadcastInactive,
      toolType: result?.processName || requestedToolType,
    });
    return result;
  };

  // First try the direct Claude/Gemini/Codex child of our shell PID.
  // For Codex, keep a descendant fallback: the process tree can be
  // shell → node wrapper → vendor codex binary, depending on install path.
  let childPid = null;
  let processName = requestedToolType || null;
  const directChildrenForDiag = [];
  const aiCandidatesForDiag = [];
  try {
    const psOut = await execAsync('ps -eo pid,ppid,command', 2000);
    for (const line of (psOut || '').split('\n').filter(Boolean)) {
      const m = line.trim().match(/^(\d+)\s+(\d+)\s+(.+)$/);
      if (!m) continue;
      const [, pid, ppid, cmd] = m;
      if (cmd.includes('Electron') || cmd.includes('electron')) continue;
      if (Number(ppid) === term.pid) {
        directChildrenForDiag.push({
          pid: Number(pid),
          cmd: String(cmd || '').replace(/\s+/g, ' ').slice(0, 220),
        });
      }
      const aiName = getAiProcessNameFromCommand(cmd);
      if (!aiName) continue;
      aiCandidatesForDiag.push({
        pid: Number(pid),
        ppid: Number(ppid),
        name: aiName,
        direct: Number(ppid) === term.pid,
        cmd: String(cmd || '').replace(/\s+/g, ' ').slice(0, 220),
      });
      if (Number(ppid) === term.pid) {
        childPid = Number(pid);
        processName = aiName;
        markAiStopping(tabId, processName, stopReason);
        console.log('[StopAI] matched direct child tab=' + tabId + ' pid=' + childPid + ' name=' + processName + ' cmd=' + cmd);
        break;
      }
    }
  } catch (err) {
    console.log('[StopAI] ps lookup failed for tab ' + tabId + ': ' + err.message);
  }

  if (!childPid) {
    try {
      const codexCandidates = await findAiDescendantProcessesByTab(tabId, 'codex');
      if (codexCandidates.length > 0) {
        const candidate = [...codexCandidates].sort((a, b) => a.depth - b.depth || a.pid - b.pid)[0];
        childPid = Number(candidate.pid);
        processName = 'codex';
        markAiStopping(tabId, processName, stopReason);
        console.log('[StopAI] matched codex descendant fallback tab=' + tabId + ' pid=' + childPid + ' depth=' + candidate.depth + ' cmd=' + candidate.cmd);
      }
    } catch (err) {
      console.log('[StopAI] codex descendant fallback failed for tab ' + tabId + ': ' + (err?.message || err));
    }
  }

  if (!childPid) {
    const rowCommandType = (() => {
      try {
        return projectManager?.db?.db?.prepare('SELECT command_type FROM tabs WHERE tab_id = ? LIMIT 1').get(tabId)?.command_type || '';
      } catch {
        return '';
      }
    })();
    const isCodexRuntime = rowCommandType === 'codex'
      || codexLastRunCommandPayload.has(tabId)
      || codexKnownSessions.has(tabId)
      || codexTurnWatchers.has(tabId)
      || codexTuiReadyTabs.has(tabId);
    let descendantsForDiag = [];
    let descendantDiagError = null;
    try {
      const snapshot = await getProcessTreeSnapshot();
      const stack = [{ pid: term.pid, depth: 0 }];
      const seen = new Set();
      while (stack.length > 0) {
        const cur = stack.pop();
        if (!cur || seen.has(cur.pid)) continue;
        seen.add(cur.pid);
        const kids = snapshot.children.get(cur.pid) || [];
        for (const child of kids) {
          const depth = cur.depth + 1;
          descendantsForDiag.push({
            depth,
            pid: child.pid,
            ppid: child.ppid,
            ai: getAiProcessNameFromCommand(child.cmd) || null,
            cmd: String(child.cmd || '').replace(/\s+/g, ' ').slice(0, 220),
          });
          stack.push({ pid: child.pid, depth });
        }
      }
    } catch (err) {
      descendantDiagError = err?.message || String(err);
    }
    const commandState = terminalCommandState.get(tabId) || null;
    console.log('[StopAI:NoProcessDiag] tab=' + String(tabId).slice(-12)
      + ' shellPid=' + term.pid
      + ' requested=' + (requestedToolType || '-')
      + ' rowCommandType=' + (rowCommandType || '-')
      + ' commandRunning=' + (commandState?.isRunning === true)
      + ' bridge=' + ((bridgeKnownSessions.get(tabId) || '').slice(0, 8) || '-')
      + ' claudeCliActive=' + claudeCliActive.has(tabId)
      + ' claudePromptReady=' + claudePromptReady.has(tabId)
      + ' claudeTurnBusy=' + (claudeTurnBusy.get(tabId) === true)
      + ' claudeSpinnerBusy=' + (claudeSpinnerBusy.get(tabId) === true)
      + ' directChildren=' + JSON.stringify(directChildrenForDiag)
      + ' aiCandidates=' + JSON.stringify(aiCandidatesForDiag.slice(0, 12))
      + ' descendants=' + JSON.stringify(descendantsForDiag.slice(0, 20))
      + ' descendantsTotal=' + descendantsForDiag.length
      + ' descendantError=' + (descendantDiagError || '-'));
    console.log('[StopAI] no AI process found for tab ' + tabId + ' shellPid=' + term.pid);
    if (isCodexRuntime && !preserveCodexLaunchPayload) {
      clearCodexLaunchPayload(tabId, stopReason);
      clearCodexKnownSession(tabId, stopReason);
      clearCodexTuiReady(tabId, stopReason);
      closeCodexTurnWatcher(tabId, stopReason);
      emitCodexBusy(tabId, false, stopReason);
      finalizeStoppedAiCommandState(tabId, stopReason, { processName: 'codex', forceEvent: true });
      return finishStop({ success: true, processName: 'codex', noProcess: true }, true);
    }
    const isClaudeRuntime = requestedToolType === 'claude'
      || rowCommandType === 'claude'
      || bridgeKnownSessions.has(tabId)
      || claudeCliActive.has(tabId)
      || claudePromptReady.has(tabId)
      || claudeStartupIntents.has(tabId)
      || claudeTurnBusy.get(tabId) === true
      || claudeSpinnerBusy.get(tabId) === true
      || claudeLocalCommandWatchers.has(tabId);
    if (isClaudeRuntime) {
      const wasBusy = claudeSpinnerBusy.get(tabId) === true
        || claudeTurnBusy.get(tabId) === true
        || claudeLocalCommandWatchers.has(tabId);
      clearTimeout(claudeSpinnerIdleTimer.get(tabId));
      claudeSpinnerIdleTimer.delete(tabId);
      clearTimeout(claudeTurnWatchdog.get(tabId));
      claudeTurnWatchdog.delete(tabId);
      claudeSpinnerLastSeenAt.delete(tabId);
      stopClaudeLocalCommandWatcher(tabId, stopReason);
      claudeSpinnerBusy.set(tabId, false);
      claudeTurnBusy.set(tabId, false);
      claudeHookLastEvent.set(tabId, {
        event: 'ManualStopNoProcess',
        ts: Date.now(),
        sessionId: bridgeKnownSessions.get(tabId) || null,
      });
      recordActivity(tabId, false, 'claude');
      if (wasBusy && mainWindow && !mainWindow.isDestroyed()) {
        console.log('[StopAI] Tab ' + tabId + ': Claude no-process busy-state cleanup → false');
        mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: 'manual-stop' });
        mainWindow.webContents.send('claude:turn-state', {
          tabId,
          sessionId: bridgeKnownSessions.get(tabId) || null,
          event: 'ManualStopNoProcess',
          busy: false, success: false, lastAssistantMessage: null,
        });
      }
      stopInterruptWatcher(tabId);
      claudeCliActive.delete(tabId);
      clearBridgeTab(tabId);
      finalizeStoppedAiCommandState(tabId, stopReason, { processName: 'claude', forceEvent: true });
      return finishStop({ success: true, processName: 'claude', noProcess: true }, true);
    }
    return finishStop({ success: false, error: 'no AI process found' }, false);
  }

  const _diagStopIdentity = resolveActivityIdentity(tabId, processName);
  const _diagStopSid = _diagStopIdentity.sessionId || bridgeKnownSessions.get(tabId) || codexKnownSessions.get(tabId) || null;
  const _diagStopBusy = processName === 'codex'
    ? codexTurnWatchers.get(tabId)?.busy === true
    : claudeTurnBusy.get(tabId) === true || claudeSpinnerBusy.get(tabId) === true;

  // Hoist stopBusyState (declared further below) up so the Ctrl+C graceful
  // exit path can call it on success without referring to it before init.
  const stopBusyState = () => {
    finalizeStoppedAiCommandState(tabId, stopReason, { processName, forceEvent: true });
    if (processName === 'codex') {
      if (!preserveCodexLaunchPayload) clearCodexLaunchPayload(tabId, stopReason);
      clearCodexKnownSession(tabId, stopReason);
      clearCodexTuiReady(tabId, stopReason);
      closeCodexTurnWatcher(tabId, stopReason);
      emitCodexBusy(tabId, false, stopReason);
      return;
    }
    if (processName === 'gemini') {
      clearTimeout(geminiSpinnerIdleTimers.get(tabId));
      geminiSpinnerIdleTimers.delete(tabId);
      const wasBusy = geminiSpinnerBusy.get(tabId) === true;
      geminiSpinnerBusy.set(tabId, false);
      recordActivity(tabId, false, 'gemini');
      if (mainWindow && !mainWindow.isDestroyed()) {
        if (wasBusy) console.log('[StopAI] Tab ' + tabId + ': gemini busy-state cleanup → false (manual Stop)');
        mainWindow.webContents.send('gemini:busy-state', { tabId, busy: false, reason: 'manual-stop' });
      }
      return;
    }
    clearTimeout(claudeSpinnerIdleTimer.get(tabId));
    claudeSpinnerIdleTimer.delete(tabId);
    clearTimeout(claudeTurnWatchdog.get(tabId));
    claudeTurnWatchdog.delete(tabId);
    claudeSpinnerLastSeenAt.delete(tabId);
    const wasLocalBusy = claudeLocalCommandWatchers.has(tabId);
    stopClaudeLocalCommandWatcher(tabId, 'manual-stop');
    const wasBusy = claudeSpinnerBusy.get(tabId) === true || claudeTurnBusy.get(tabId) === true || wasLocalBusy;
    claudeSpinnerBusy.set(tabId, false);
    claudeTurnBusy.set(tabId, false);
    claudeHookLastEvent.set(tabId, {
      event: 'ManualStop',
      ts: Date.now(),
      sessionId: bridgeKnownSessions.get(tabId) || null,
    });
    recordActivity(tabId, false, 'claude');
    if (wasBusy && mainWindow && !mainWindow.isDestroyed()) {
      console.log('[StopAI] Tab ' + tabId + ': busy-state cleanup → false (manual Stop)');
      mainWindow.webContents.send('claude:busy-state', { tabId, busy: false, reason: 'manual-stop' });
      mainWindow.webContents.send('claude:turn-state', {
        tabId,
        sessionId: bridgeKnownSessions.get(tabId) || null,
        event: 'ManualStop',
        busy: false, success: false, lastAssistantMessage: null,
      });
    }
    stopInterruptWatcher(tabId);
    claudeCliActive.delete(tabId);
    clearBridgeTab(tabId);
  };

  // Graceful Ctrl+C first — Ink (Claude Code TUI) listens for \x03 through its
  // own keyboard handler and finishes the current SSE chunk + flushes the
  // assistant entry to JSONL before exiting. Direct SIGTERM bypasses Ink and
  // cancels the in-flight async stream mid-write → orphan parentUuid in the
  // next session resume. See fix-claude-busy-detection.md::Manual Stop +
  // [JsonlChainDiag:StopAI:SIGKILL] forensic note further below.
  //
  // Sequence: write \x03 → poll kill(0) up to 300ms → if dead, done. Otherwise
  // fall through to the existing SIGTERM→800ms→SIGKILL escalation.
  console.log('[StopAI] Tab ' + tabId + ': Ctrl+C → pid=' + childPid + ' (' + processName + ')');
  console.log('[JsonlChainDiag:StopAI] tabId=' + tabId + ' childPid=' + childPid + ' processName=' + processName + ' sessionId=' + (_diagStopSid ? _diagStopSid.substring(0, 8) : 'none') + ' busy=' + _diagStopBusy + ' — manual Stop button click via UI; sending \\x03 first');
  try {
    term.write('\x03');
  } catch (err) {
    console.log('[StopAI] Ctrl+C write failed: ' + err.message + ' — falling through to SIGTERM');
  }

  // Give Claude up to 300ms to react to Ctrl+C and exit gracefully.
  const ctrlCExited = await new Promise((resolve) => {
    const start = Date.now();
    const poll = () => {
      try {
        process.kill(childPid, 0);
        if (Date.now() - start >= 300) return resolve(false);
        setTimeout(poll, 40);
      } catch {
        resolve(true); // process gone
      }
    };
    setTimeout(poll, 40);
  });

  if (ctrlCExited) {
    console.log('[StopAI] Tab ' + tabId + ': ' + processName + ' exited gracefully via Ctrl+C');
    stopBusyState();
    return finishStop({ success: true, processName, escalated: false, graceful: 'ctrl-c' }, true);
  }

  console.log('[StopAI] Tab ' + tabId + ': SIGTERM → pid=' + childPid + ' (Ctrl+C ignored 300ms)');
  try {
    process.kill(childPid, 'SIGTERM');
  } catch (err) {
    console.log('[StopAI] SIGTERM failed: ' + err.message);
    return finishStop({ success: false, processName, error: err.message }, false);
  }

  // stopBusyState declared above (hoisted) so the Ctrl+C path can call it.
  // Verify exit within 800ms. If still alive, SIGKILL.
  return new Promise((resolve) => {
    const start = Date.now();
    const check = () => {
      try {
        process.kill(childPid, 0); // signal 0 = alive check
        if (Date.now() - start >= 800) {
          console.log('[StopAI] Tab ' + tabId + ': SIGTERM stalled, SIGKILL pid=' + childPid);
          console.log('[JsonlChainDiag:StopAI:SIGKILL] tabId=' + tabId + ' childPid=' + childPid + ' — SIGTERM ignored 800ms, escalating to SIGKILL — JSONL flush GUARANTEED lost for in-flight write');
          try { process.kill(childPid, 'SIGKILL'); } catch {}
          stopBusyState();
          resolve(finishStop({ success: true, processName, escalated: true }, true));
          return;
        }
        setTimeout(check, 80);
      } catch {
        // ESRCH = process gone
        console.log('[StopAI] Tab ' + tabId + ': ' + processName + ' exited cleanly in ' + (Date.now() - start) + 'ms');
        stopBusyState();
        resolve(finishStop({ success: true, processName, escalated: false }, true));
      }
    };
    setTimeout(check, 80);
  });
}

ipcMain.handle('terminal:stop-ai-process', async (_event, request) => {
  const payload = request && typeof request === 'object' ? request : { tabId: request };
  return stopAiProcessInTab(payload.tabId, {
    toolType: payload.toolType || null,
    reason: payload.reason || 'manual-stop',
  });
});

// Execute quick action command in terminal (fire-and-forget version)
// For backwards compatibility - use terminal:executeCommandAsync for sequential commands
ipcMain.on('terminal:executeCommand', (event, tabId, command) => {
  console.log('[main] ========== EXECUTE COMMAND ==========');
  console.log('[main] tabId:', tabId);
  console.log('[main] command:', command);

  const term = terminals.get(tabId);
  if (term) {
    console.log('[main] ✅ Terminal found, PID:', term.pid);
    startClaudeLocalCommandWatcher(tabId, command, 'execute-command');
    term.write(command);
    setTimeout(() => {
      term.write('\r');
      console.log('[main] ✅ Enter (\r) sent!');
    }, 150);
  } else {
    console.error('[main] ❌ Terminal NOT FOUND for tabId:', tabId);
  }
});

// Execute command and wait for Enter to be sent (async version)
// Use this when you need to wait before sending next command
ipcMain.handle('terminal:executeCommandAsync', async (event, tabId, command) => {
  const startTime = Date.now();
  console.log('[main] ========== EXECUTE COMMAND ASYNC ==========');
  console.log('[main] tabId:', tabId);
  console.log('[main] command:', command);
  console.log('[main] timestamp:', startTime);

  const term = terminals.get(tabId);
  if (!term) {
    console.error('[main] ❌ Terminal NOT FOUND for tabId:', tabId);
    return { success: false };
  }

  console.log('[main] ✅ Terminal found, PID:', term.pid);

  // Write command text
  startClaudeLocalCommandWatcher(tabId, command, 'execute-command-async');
  console.log('[main] 📝 Writing command text...');
  term.write(command);
  console.log('[main] 📝 Command text written at', Date.now() - startTime, 'ms');

  // Wait 150ms then send Enter
  await new Promise(resolve => setTimeout(resolve, 150));
  console.log('[main] ⏰ 150ms passed, sending Enter...');
  term.write('\r');
  console.log('[main] ✅ Enter (\r) sent at', Date.now() - startTime, 'ms');

  // Wait a bit more for command to start processing
  await new Promise(resolve => setTimeout(resolve, 100));
  console.log('[main] ⏰ 100ms after Enter, returning at', Date.now() - startTime, 'ms');

  return { success: true };
});

