// Store active Gemini watchers by tabId (so we can close them when tab closes)
const geminiWatchers = new Map();

// Store active Codex watchers by tabId. Codex writes append-only JSONL under
// ~/.codex/sessions/YYYY/MM/DD/rollout-...jsonl; the session id is authoritative
// in the first session_meta payload, not in PTY output.
const codexWatchers = new Map();
const codexTurnWatchers = new Map();
const codexPickerQueue = new Map();
const codexTuiReadyProcessProbeTabs = new Set();
const CODEX_WATCHER_TTL_MS = 10 * 60 * 1000;
const CODEX_WATCHER_SCAN_MS = 1000;
const CODEX_TURN_CATCHUP_BYTES = 8 * 1024 * 1024;
const CODEX_SYNC_MARKER = '\x1b[?2026l';
const CODEX_STARTUP_AUTO_ENTER_TTL_MS = 45 * 1000;
const CODEX_TRUST_PROMPT_AUTO_ENTER_TTL_MS = 15 * 1000;
const CODEX_POST_TRUST_AUTO_ENTER_TTL_MS = 12 * 1000;
const CODEX_STARTUP_AUTO_ENTER_BUFFER_LIMIT = 20 * 1024;
const CODEX_TUI_READY_QUIET_MS = 350;
const CODEX_EXTERNAL_PROMPT_READY_TIMEOUT_MS = 90 * 1000;
const CODEX_MCP_STARTUP_RESTART_MS = 15 * 1000;
const CODEX_MCP_STARTUP_MAX_RESTARTS = 1;
const CODEX_STARTUP_NO_STATE_TIMEOUT_MS = 60 * 1000;
const CODEX_STARTUP_LIFECYCLE_TTL_MS = 90 * 1000;
const CODEX_PROMPT_IN_FLIGHT_TTL_MS = 120 * 1000;
// Parser order matters: `xhigh` renders as "Extra high", so it must be matched
// before plain `high` or the effort picker selects the wrong row.
const CODEX_PICKER_EFFORT_CANDIDATES = ['minimal', 'low', 'medium', 'xhigh', 'high'];

function clearCodexTuiReady(tabId, reason = 'clear') {
  if (!tabId) return;
  clearCodexManualActionRequired(tabId, reason);
  const hadReady = codexTuiReadyTabs.delete(tabId);
  const quietTimer = codexTuiReadyQuietTimers.get(tabId);
  if (quietTimer) clearTimeout(quietTimer);
  codexTuiReadyQuietTimers.delete(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  codexTuiReadyLastNotReady.delete(tabId);
  codexTuiReadyMeta.delete(tabId);
  codexStartupNoStateTimeoutTabs.delete(tabId);
  clearCodexMcpStartupWatchdog(tabId, reason);
  clearCodexPromptInFlight(tabId, 'tui-ready-clear:' + reason);
  if (hadReady) {
    console.log('[CodexTuiReady] clear tab=' + String(tabId).slice(-12) + ' reason=' + reason);
  }
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:tui-not-ready', { tabId, reason });
  }
}

function resetCodexTuiReadyDetection(tabId, reason = 'reset') {
  if (!tabId) return;
  clearCodexManualActionRequired(tabId, reason);
  const quietTimer = codexTuiReadyQuietTimers.get(tabId);
  if (quietTimer) clearTimeout(quietTimer);
  codexTuiReadyQuietTimers.delete(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  codexTuiReadyLastNotReady.delete(tabId);
  codexTuiReadyMeta.delete(tabId);
  codexStartupNoStateTimeoutTabs.delete(tabId);
  if (codexTuiReadyTabs.delete(tabId)) {
    console.log('[CodexTuiReady] clear tab=' + String(tabId).slice(-12) + ' reason=' + reason);
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('codex:tui-not-ready', { tabId, reason });
    }
  }
}

function inspectCodexStartupBlockersText(cleanText) {
  const text = String(cleanText || '').replace(/\u00a0/g, ' ');
  const compact = text.replace(/\s+/g, ' ').trim();
  if (!compact) return [];
  const blockers = [];
  const has = (re) => re.test(compact);
  const authPrompt = inspectCodexAuthRequiredPrompt(text);
  if (authPrompt.visible) {
    blockers.push('auth-required');
  }
  const updatePrompt = inspectCodexUpdatePrompt(text);
  if (updatePrompt.interactiveVisible) {
    blockers.push('update-prompt');
  }
  if (has(/Do\s+you\s+trust\s+the\s+contents|Working\s+with\s+untrusted\s+contents|Yes\s*,?\s*continue|No\s*,?\s*quit/i)) {
    blockers.push('trust-directory');
  }
  if (has(/directory\s+to\s+(?:resume|fork)\s+this\s+session|Use\s+session\s+directory|Use\s+current\s+directory/i)) {
    blockers.push('cwd-chooser');
  }
  if (has(/Starting\s+MCP\s+servers|Booting\s+MCP\s+server|MCP\s+startup\s+interrupted|MCP\s+servers?\s*\(\s*\d+\s*\/\s*\d+\s*\)|servers?\s*\(\s*\d+\s*\/\s*\d+\s*\)/i)) {
    blockers.push('mcp-startup');
  }
  return Array.from(new Set(blockers));
}

function invalidateCodexTuiReadyForStartupBlocker(tabId, source, preview, blockers) {
  if (!tabId || !Array.isArray(blockers) || blockers.length === 0) return false;
  if (blockers.includes('auth-required')) {
    markCodexManualActionRequired(tabId, 'auth-required', {
      source: source || 'startup-blocker',
      blockers,
      sampleText: preview || '',
      reason: 'blocked:' + blockers.join('+'),
    }, preview || '', source || 'startup-blocker');
    return true;
  }
  if (isOnlyCodexMcpStartupBlocker(blockers)) {
    const ignoreReason = codexMcpStartupBlockerIgnoreReason(tabId);
    if (ignoreReason) {
      logIgnoredCodexMcpStartupBlocker(tabId, {
        blockers,
        sampleText: preview || '',
        hasCodexUiText: true,
        hasComposerFrame: codexTuiReadyTabs.has(tabId),
      }, source || 'startup-blocker', ignoreReason);
      return false;
    }
  }
  if (hasCodexPromptOrTurnInFlight(tabId)) {
    console.log('[CodexTuiReady] skip startup-blocker invalidation tab=' + String(tabId).slice(-12)
      + ' source=' + (source || '-')
      + ' reason=prompt-or-turn-in-flight'
      + ' blockers=' + blockers.join('+'));
    return false;
  }
  const hadReady = codexTuiReadyTabs.delete(tabId);
  codexTuiReadyMeta.delete(tabId);
  const previewTail = String(preview || '').replace(/\s+/g, ' ').trim().slice(-260);
  codexTuiReadyLastNotReady.set(tabId, {
    ts: Date.now(),
    phase: source || 'startup-blocker',
    source: source || '-',
    reason: 'blocked:' + blockers.join('+'),
    blockers: blockers.slice(),
    sampleMode: 'ready-preview',
    sampleBytes: previewTail.length,
    totalBytes: previewTail.length,
    startupArmed: codexStartupAutoEnter.has(tabId),
    previewTail,
  });
  if (hadReady) {
    console.warn('[CodexTuiReady] invalidated ready tab=' + String(tabId).slice(-12)
      + ' source=' + (source || '-')
      + ' blockers=' + blockers.join('+')
      + ' preview=' + JSON.stringify(previewTail));
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('codex:tui-not-ready', {
        tabId,
        reason: 'startup-blocker:' + blockers.join('+'),
      });
    }
    _webBroadcast(tabId, {
      type: 'snapshot',
      sessionId: getCodexRuntimeSessionId(tabId),
      busy: false,
      sessionStatus: 'starting',
      starting: true,
      inputReady: false,
      toolType: 'codex',
      commandType: 'codex',
      lastNotReady: codexTuiReadyLastNotReady.get(tabId) || null,
      reason: 'codex-ready-startup-blocker',
    });
  }
  return hadReady;
}

function inspectCodexInputReadyText(clean, raw, { requireSyncMarker = true, source = 'raw' } = {}) {
  const text = String(clean || '').replace(/\u00a0/g, ' ');
  const compact = text.replace(/\s+/g, ' ').trim();
  if (!compact) return { ready: false, reason: 'empty', source };

  const blockers = inspectCodexStartupBlockersText(text);

  const hasSynchronizedFrame = String(raw || '').includes(CODEX_SYNC_MARKER);
  if (requireSyncMarker && !hasSynchronizedFrame) {
    return { ready: false, reason: 'no-sync-marker', source, hasSynchronizedFrame };
  }

  const hasCodexUiText = /OpenAI Codex|Use \/skills|Full Access|Find and fix a bug|Explain this codebase|Ask Codex|Context \d+%|directory:\s*|permissions:\s*/i.test(text);
  const hasPromptGlyph = /(?:^|\n)\s*[›❯>]\s*/.test(text);
  const hasComposerFrame = (/[╭╰│]/.test(text) || hasPromptGlyph) && hasCodexUiText;

  if (blockers.length > 0) {
    return {
      ready: false,
      reason: 'blocked:' + blockers.join('+'),
      source,
      blockers,
      hasSynchronizedFrame,
      hasCodexUiText,
      hasPromptGlyph,
      hasComposerFrame,
    };
  }
  if (!hasCodexUiText) {
    return { ready: false, reason: 'no-codex-ui-text', source, hasSynchronizedFrame, hasPromptGlyph };
  }
  if (!hasComposerFrame) {
    return { ready: false, reason: 'no-composer-frame', source, hasSynchronizedFrame, hasCodexUiText, hasPromptGlyph };
  }
  return {
    ready: true,
    reason: 'ready',
    source,
    hasSynchronizedFrame,
    hasCodexUiText,
    hasPromptGlyph,
    hasComposerFrame,
  };
}

function getLatestCodexSynchronizedRawFrame(raw) {
  const text = String(raw || '');
  const lastMarker = text.lastIndexOf(CODEX_SYNC_MARKER);
  if (lastMarker < 0) {
    return {
      raw: text.slice(-8192),
      mode: 'tail-no-sync',
      totalBytes: text.length,
    };
  }

  const prevMarker = text.lastIndexOf(CODEX_SYNC_MARKER, Math.max(0, lastMarker - 1));
  const start = prevMarker >= 0
    ? prevMarker + CODEX_SYNC_MARKER.length
    : Math.max(0, lastMarker - 8192);
  const frameRaw = text.slice(start, lastMarker) + CODEX_SYNC_MARKER;
  return {
    raw: frameRaw,
    mode: prevMarker >= 0 ? 'latest-sync-frame' : 'latest-sync-tail',
    totalBytes: text.length,
    start,
    end: lastMarker,
  };
}

function inspectCodexInputReadyFrame(clean, raw) {
  const sample = getLatestCodexSynchronizedRawFrame(raw);
  const sampleClean = cleanCodexTuiFrame(sample.raw || raw || clean || '');
  const inspected = inspectCodexInputReadyText(sampleClean, sample.raw, { requireSyncMarker: true, source: 'raw' });
  inspected.sampleMode = sample.mode;
  inspected.sampleBytes = String(sample.raw || '').length;
  inspected.totalBytes = sample.totalBytes;
  inspected.sampleText = sampleClean;
  return inspected;
}

function inspectCodexMcpStartupText(cleanText) {
  const text = String(cleanText || '').replace(/\u00a0/g, ' ');
  const compact = text.replace(/\s+/g, ' ').trim();
  if (!compact) return { visible: false, canInterrupt: false, preview: '' };
  const hasStartupText = /Starting\s+MCP\s+servers|Booting\s+MCP\s+server|MCP\s+startup/i.test(compact);
  const hasProgressText = /MCP\s+servers?|servers\s*\(\s*\d+\s*\/\s*\d+\s*\)|\(\s*\d+\s*\/\s*\d+\s*\)\s*:/i.test(compact);
  const visible = hasStartupText || hasProgressText;
  return {
    visible,
    canInterrupt: visible && (/esc\s+to\s+interrupt/i.test(compact) || hasProgressText),
    preview: compact.slice(-260),
  };
}

function getCodexMcpStartupWatchdogState(tabId, inspected, clean) {
  const fromInspect = Array.isArray(inspected?.blockers) && inspected.blockers.includes('mcp-startup');
  const sample = typeof inspected?.sampleText === 'string' ? inspected.sampleText : '';
  const mcp = inspectCodexMcpStartupText(sample || clean || '');
  if (!fromInspect && !mcp.visible) return null;
  return {
    ...mcp,
    visible: true,
    reason: inspected?.reason || (fromInspect ? 'blocked:mcp-startup' : 'mcp-startup'),
    sampleMode: inspected?.sampleMode || '-',
  };
}

function getCodexMcpStartupStatus(tabId) {
  const state = codexMcpStartupWatchdogs.get(tabId);
  if (!state || !state.mcpStartupFirstSeenAt) return null;
  return {
    ts: state.mcpStartupLastSeenAt || state.mcpStartupFirstSeenAt,
    phase: 'mcp-startup',
    source: 'pty-raw',
    reason: 'blocked:mcp-startup',
    blockers: ['mcp-startup'],
    sampleMode: state.mcpStartupSampleMode || '-',
    startupArmed: codexStartupAutoEnter.has(tabId),
    previewTail: state.mcpStartupPreview || '',
    firstSeenAgeMs: Date.now() - state.mcpStartupFirstSeenAt,
    lastSeenAgeMs: Date.now() - (state.mcpStartupLastSeenAt || state.mcpStartupFirstSeenAt),
    restartSent: !!state.mcpStartupRestarting,
  };
}

function hasCodexPromptOrTurnInFlight(tabId) {
  if (!tabId) return false;
  const turnState = codexTurnWatchers.get(tabId);
  const audit = pendingCodexPasteAudit.get(tabId);
  const prompt = codexPromptInFlight.get(tabId);
  if (prompt) {
    const ageMs = Date.now() - (prompt.startedAt || 0);
    if (ageMs > CODEX_PROMPT_IN_FLIGHT_TTL_MS) {
      clearCodexPromptInFlight(tabId, 'ttl');
    } else {
      return true;
    }
  }
  return turnState?.busy === true || activityOpenIntervals.has(tabId) || audit?.awaitUserMessage === true;
}

function isOnlyCodexMcpStartupBlocker(blockers) {
  return Array.isArray(blockers) && blockers.length === 1 && blockers[0] === 'mcp-startup';
}

function beginCodexPromptInFlight(tabId, reason = 'submit', meta = {}) {
  if (!tabId) return null;
  const previous = codexPromptInFlight.get(tabId);
  if (previous?.timer) clearTimeout(previous.timer);
  const state = {
    reason,
    source: meta.source || null,
    handoffId: meta.handoffId || null,
    startedAt: Date.now(),
    submitted: false,
    timer: null,
  };
  state.timer = setTimeout(() => {
    clearCodexPromptInFlight(tabId, 'ttl');
  }, CODEX_PROMPT_IN_FLIGHT_TTL_MS);
  codexPromptInFlight.set(tabId, state);
  console.log('[CodexPromptInFlight] begin tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' source=' + (state.source || '-')
    + ' handoff=' + (state.handoffId || '-'));
  return state;
}

function markCodexPromptSubmitted(tabId, state, reason = 'submitted') {
  if (!tabId || !state || codexPromptInFlight.get(tabId) !== state) return;
  state.submitted = true;
  state.submittedAt = Date.now();
  state.submitReason = reason;
  console.log('[CodexPromptInFlight] submitted tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' source=' + (state.source || '-')
    + ' ageMs=' + (Date.now() - (state.startedAt || Date.now())));
}

function clearCodexPromptInFlight(tabId, reason = 'clear') {
  if (!tabId) return;
  const state = codexPromptInFlight.get(tabId);
  if (!state) return;
  if (state.timer) clearTimeout(state.timer);
  codexPromptInFlight.delete(tabId);
  console.log('[CodexPromptInFlight] clear tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' source=' + (state.source || '-')
    + ' submitted=' + !!state.submitted
    + ' ageMs=' + (Date.now() - (state.startedAt || Date.now())));
}

function isCodexStartupLifecycleFresh(tabId) {
  if (!tabId || codexTuiReadyTabs.has(tabId)) return false;
  const now = Date.now();
  const startupState = codexStartupAutoEnter.get(tabId);
  if (startupState?.armedAt && now - startupState.armedAt <= CODEX_STARTUP_LIFECYCLE_TTL_MS) {
    return true;
  }
  const payload = codexLastRunCommandPayload.get(tabId);
  const startedAt = Number(payload?.startedAt || 0);
  return !!payload && startedAt > 0 && now - startedAt <= CODEX_STARTUP_LIFECYCLE_TTL_MS;
}

function logIgnoredCodexMcpStartupBlocker(tabId, inspected, phase, reason) {
  if (!tabId) return;
  const preview = String(inspected?.sampleText || inspected?.preview || '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(-180);
  const key = ['ignore-mcp-startup', phase || '-', reason || '-', preview.slice(-80)].join('|');
  if (codexTuiReadyRejectKeys.get(tabId) === key) return;
  codexTuiReadyRejectKeys.set(tabId, key);
  console.log('[CodexTuiReady] ignore mcp-startup blocker tab=' + String(tabId).slice(-12)
    + ' phase=' + (phase || '-')
    + ' reason=' + (reason || '-')
    + ' hasComposer=' + !!inspected?.hasComposerFrame
    + ' hasUi=' + !!inspected?.hasCodexUiText
    + ' promptInFlight=' + codexPromptInFlight.has(tabId)
    + ' startupFresh=' + isCodexStartupLifecycleFresh(tabId)
    + ' preview=' + JSON.stringify(preview));
}

function codexMcpStartupBlockerIgnoreReason(tabId) {
  if (hasCodexPromptOrTurnInFlight(tabId)) return 'prompt-or-turn-in-flight';
  if (codexTuiReadyTabs.has(tabId)) return 'already-ready';
  if (!isCodexStartupLifecycleFresh(tabId)) return 'not-startup-lifecycle';
  return null;
}

function normalizeCodexMcpStartupInspection(tabId, inspected, phase) {
  if (!inspected || inspected.ready) return inspected;
  const blockers = Array.isArray(inspected.blockers) ? inspected.blockers : [];
  if (!isOnlyCodexMcpStartupBlocker(blockers)) return inspected;
  const ignoreReason = codexMcpStartupBlockerIgnoreReason(tabId);
  if (!ignoreReason) return inspected;
  logIgnoredCodexMcpStartupBlocker(tabId, inspected, phase, ignoreReason);
  const normalized = {
    ...inspected,
    blockers: [],
    ignoredBlockers: blockers.slice(),
    ignoredBlockerReason: ignoreReason,
  };
  if (inspected.hasCodexUiText && inspected.hasComposerFrame) {
    normalized.ready = true;
    normalized.reason = 'ready:mcp-startup-ignored';
  } else {
    normalized.reason = inspected.hasCodexUiText ? 'no-composer-frame' : 'no-codex-ui-text';
  }
  return normalized;
}

function getCodexStartupNoStateTimeout(tabId) {
  const payload = codexLastRunCommandPayload.get(tabId) || null;
  const startedAt = Number(payload?.startedAt || 0);
  if (!tabId || !payload || !startedAt) return null;
  if (codexTuiReadyTabs.has(tabId)) return null;
  if (hasCodexPromptOrTurnInFlight(tabId)) return null;
  const ageMs = Date.now() - startedAt;
  if (ageMs < CODEX_STARTUP_NO_STATE_TIMEOUT_MS) return null;
  const blockerState = codexTuiReadyLastNotReady.get(tabId) || getCodexMcpStartupStatus(tabId) || null;
  if (Array.isArray(blockerState?.blockers) && blockerState.blockers.length > 0) return null;
  const previewTail = blockerState?.previewTail || '';
  return {
    ts: Date.now(),
    phase: 'startup-timeout',
    source: 'main-startup-watchdog',
    reason: 'startup-timeout:no-ready-signal',
    blockers: [],
    sampleMode: blockerState?.sampleMode || '-',
    sampleBytes: blockerState?.sampleBytes || 0,
    totalBytes: blockerState?.totalBytes || 0,
    startupArmed: codexStartupAutoEnter.has(tabId),
    previewTail,
    firstSeenAgeMs: ageMs,
    lastSeenAgeMs: ageMs,
    timeoutMs: CODEX_STARTUP_NO_STATE_TIMEOUT_MS,
    command: payload.command || 'codex',
    sessionId: payload.sessionId || null,
  };
}

function maybeSurfaceCodexStartupNoStateTimeout(tabId, status) {
  if (!tabId || !status) return;
  codexTuiReadyLastNotReady.set(tabId, status);
  if (codexStartupNoStateTimeoutTabs.has(tabId)) return;
  codexStartupNoStateTimeoutTabs.add(tabId);
  console.warn('[CodexStartupTimeout] tab=' + String(tabId).slice(-12)
    + ' reason=' + status.reason
    + ' ageMs=' + status.firstSeenAgeMs
    + ' command=' + (status.command || '-')
    + ' session=' + (status.sessionId ? String(status.sessionId).slice(0, 8) : 'none'));
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId: getCodexRuntimeSessionId(tabId),
    busy: false,
    sessionStatus: 'starting',
    starting: true,
    inputReady: false,
    toolType: 'codex',
    commandType: 'codex',
    lastNotReady: status,
    startupError: status.reason,
    reason: 'codex-startup-timeout',
  });
}

function broadcastCodexStartingSnapshot(tabId, reason = 'starting') {
  if (!tabId) return;
  const sessionId = getCodexRuntimeSessionId(tabId);
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId,
    busy: false,
    sessionStatus: 'starting',
    starting: true,
    inputReady: false,
    toolType: 'codex',
    commandType: 'codex',
    lastNotReady: getCodexMcpStartupStatus(tabId),
    reason,
  });
}

function broadcastCodexReadySnapshot(tabId, reason = 'tui-ready') {
  if (!tabId || aiStoppingTabs.has(tabId)) return;
  const turn = codexTurnWatchers.get(tabId);
  const busy = turn?.busy === true;
  _webBroadcast(tabId, {
    type: 'snapshot',
    sessionId: getCodexRuntimeSessionId(tabId),
    busy,
    sessionStatus: busy ? 'busy' : 'active',
    starting: false,
    inputReady: !busy && codexTuiReadyTabs.has(tabId),
    toolType: 'codex',
    commandType: 'codex',
    reason,
  });
}

async function restartCodexAfterMcpStartupWatchdog(tabId, state, mcpInfo) {
  const current = codexMcpStartupWatchdogs.get(tabId);
  if (!current || current !== state || current.mcpStartupRestarting) return;
  if (codexTuiReadyTabs.has(tabId)) {
    clearCodexMcpStartupWatchdog(tabId, 'tui-ready-before-restart');
    return;
  }
  if (hasCodexPromptOrTurnInFlight(tabId)) {
    const turnState = codexTurnWatchers.get(tabId);
    const audit = pendingCodexPasteAudit.get(tabId);
    clearCodexMcpStartupWatchdog(tabId, 'prompt-or-turn-in-flight-before-restart');
    console.warn('[CodexMcpStartupWatchdog] skip restart tab=' + String(tabId).slice(-12)
      + ' reason=prompt-or-turn-in-flight'
      + ' session=' + (turnState?.sessionId ? String(turnState.sessionId).slice(0, 8) : 'none')
      + ' audit=' + (audit?.awaitUserMessage ? 'await-user-message' : '-')
      + ' preview=' + JSON.stringify(mcpInfo?.preview || state.mcpStartupPreview || ''));
    return;
  }
  const lastSeenAgeMs = Date.now() - (state.mcpStartupLastSeenAt || state.mcpStartupFirstSeenAt || Date.now());
  const storedPayload = codexLastRunCommandPayload.get(tabId);
  const payload = storedPayload ? { ...storedPayload } : null;
  if (!payload) {
    console.warn('[CodexMcpStartupWatchdog] cannot restart tab=' + String(tabId).slice(-12) + ' reason=no-last-run-payload');
    return;
  }
  if (!payload.launchId) {
    payload.launchId = 'legacy-' + Date.now() + '-' + (++codexLaunchSeq);
  }
  const detectedSessionId = codexKnownSessions.get(tabId) || null;
  if (payload.command === 'codex-f' && detectedSessionId && detectedSessionId !== payload.sessionId) {
    console.warn('[CodexMcpStartupWatchdog] normalize retry tab=' + String(tabId).slice(-12)
      + ' from=fork source=' + (payload.sessionId ? String(payload.sessionId).slice(0, 8) : 'none')
      + ' to=resume session=' + String(detectedSessionId).slice(0, 8));
    payload.command = 'codex-c';
    payload.sessionId = detectedSessionId;
  }
  const attempt = (payload.mcpStartupRestartAttempts || 0) + 1;
  if (attempt > CODEX_MCP_STARTUP_MAX_RESTARTS) {
    console.warn('[CodexMcpStartupWatchdog] restart limit reached tab=' + String(tabId).slice(-12)
      + ' attempts=' + (payload.mcpStartupRestartAttempts || 0)
      + ' command=' + (payload.command || 'codex')
      + ' session=' + (payload.sessionId ? String(payload.sessionId).slice(0, 8) : 'new'));
    return;
  }

  state.mcpStartupRestarting = true;
  payload.mcpStartupRestartAttempts = attempt;
  codexLastRunCommandPayload.set(tabId, payload);
  const ageMs = Date.now() - (state.mcpStartupFirstSeenAt || Date.now());
  console.warn('[CodexMcpStartupWatchdog] restart begin tab=' + String(tabId).slice(-12)
    + ' attempt=' + attempt + '/' + CODEX_MCP_STARTUP_MAX_RESTARTS
    + ' ageMs=' + ageMs
    + ' lastSeenAgeMs=' + lastSeenAgeMs
    + ' command=' + (payload.command || 'codex')
    + ' session=' + (payload.sessionId ? String(payload.sessionId).slice(0, 8) : 'new')
    + ' cwd=' + (payload.cwd || 'n/a')
    + ' preview=' + JSON.stringify(mcpInfo?.preview || state.mcpStartupPreview || ''));
  try {
    const stopResult = await stopAiProcessInTab(tabId, {
      reason: 'mcp-startup-watchdog',
      preserveCodexLaunchPayload: true,
    });
    console.warn('[CodexMcpStartupWatchdog] stop done tab=' + String(tabId).slice(-12)
      + ' attempt=' + attempt
      + ' success=' + !!stopResult?.success
      + ' error=' + (stopResult?.error || '-'));
  } catch (err) {
    console.warn('[CodexMcpStartupWatchdog] stop error tab=' + String(tabId).slice(-12)
      + ' attempt=' + attempt + ' ' + (err?.message || String(err)));
  }

  const latestPayload = codexLastRunCommandPayload.get(tabId);
  if (!latestPayload || latestPayload.launchId !== payload.launchId) {
    console.warn('[CodexMcpStartupWatchdog] restart aborted tab=' + String(tabId).slice(-12)
      + ' attempt=' + attempt
      + ' reason=launch-payload-cancelled'
      + ' expected=' + (payload.launchId || '-')
      + ' actual=' + (latestPayload?.launchId || 'none'));
    return;
  }

  const sender = mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : payload.sender;
  await runCodexCommandFromPayload(sender, {
    ...payload,
    mcpStartupRestartAttempts: attempt,
    restartReason: 'mcp-startup-watchdog',
  });
}

function clearCodexMcpStartupWatchdog(tabId, reason = 'clear') {
  if (!tabId) return;
  const state = codexMcpStartupWatchdogs.get(tabId);
  if (!state) return;
  if (state.mcpStartupTimer) clearTimeout(state.mcpStartupTimer);
  codexMcpStartupWatchdogs.delete(tabId);
  console.log('[CodexMcpStartupWatchdog] clear tab=' + String(tabId).slice(-12)
    + ' reason=' + reason
    + ' seen=' + !!state.mcpStartupFirstSeenAt
    + ' restarting=' + !!state.mcpStartupRestarting);
}

function finishCodexStartupLifecycle(tabId, reason = 'ready') {
  if (!tabId) return;
  const hadStartupPrompt = codexStartupAutoEnter.has(tabId);
  const hadLaunchPayload = codexLastRunCommandPayload.has(tabId);
  const hadWatchdog = codexMcpStartupWatchdogs.has(tabId);
  clearCodexManualActionRequired(tabId, reason);
  clearCodexStartupAutoEnter(tabId, reason);
  clearCodexMcpStartupWatchdog(tabId, reason);
  clearCodexLaunchPayload(tabId, reason);
  codexStartupNoStateTimeoutTabs.delete(tabId);
  codexTuiReadyLastNotReady.delete(tabId);
  if (hadStartupPrompt || hadLaunchPayload || hadWatchdog) {
    console.log('[CodexStartupLifecycle] finish tab=' + String(tabId).slice(-12)
      + ' reason=' + reason
      + ' startupPrompt=' + hadStartupPrompt
      + ' launchPayload=' + hadLaunchPayload
      + ' watchdog=' + hadWatchdog);
  }
}

function markCodexTuiReadyFromTurnEnd(tabId, reason = 'turn-end') {
  if (!tabId || aiStoppingTabs.has(tabId)) return false;
  const hadReady = codexTuiReadyTabs.has(tabId);
  codexTuiReadyTabs.add(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  codexTuiReadyMeta.set(tabId, {
    at: Date.now(),
    source: 'turn-lifecycle',
    reason,
    preview: '',
  });
  finishCodexStartupLifecycle(tabId, reason);
  if (!hadReady) {
    console.log('[CodexTuiReady] tab=' + String(tabId).slice(-12)
      + ' input ready via turn lifecycle reason=' + reason);
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('codex:tui-ready', { tabId, ts: Date.now(), reason });
    }
    ipcMain.emit('agent:tui-ready-internal', null, { tabId, toolType: 'codex' });
    broadcastCodexReadySnapshot(tabId, reason);
  }
  return true;
}

function maybeArmCodexMcpStartupWatchdog(tabId, inspected, clean, phase) {
  if (!tabId || codexTuiReadyTabs.has(tabId)) return;
  if (hasCodexPromptOrTurnInFlight(tabId)) {
    clearCodexMcpStartupWatchdog(tabId, 'prompt-or-turn-in-flight:' + (phase || 'probe'));
    return;
  }
  const mcpInfo = getCodexMcpStartupWatchdogState(tabId, inspected, clean);
  if (!mcpInfo?.visible) return;
  if (!isCodexStartupLifecycleFresh(tabId)) {
    logIgnoredCodexMcpStartupBlocker(tabId, {
      ...(inspected || {}),
      preview: mcpInfo.preview || '',
    }, phase || 'watchdog', 'not-startup-lifecycle');
    return;
  }
  const startupState = codexStartupAutoEnter.get(tabId) || null;
  const payload = codexLastRunCommandPayload.get(tabId) || null;
  let state = codexMcpStartupWatchdogs.get(tabId);
  if (!state) {
    if (!startupState && !payload) return;
    state = {
      command: startupState?.command || payload?.command || 'codex',
      sessionId: startupState?.sessionId || payload?.sessionId || null,
      cwd: startupState?.cwd || payload?.cwd || terminalProjects.get(tabId) || null,
      mcpStartupFirstSeenAt: 0,
      mcpStartupLastSeenAt: 0,
      mcpStartupLastLogBucket: -1,
      mcpStartupPreview: '',
      mcpStartupTimer: null,
      mcpStartupRestarting: false,
    };
    codexMcpStartupWatchdogs.set(tabId, state);
  }
  const now = Date.now();
  if (!state.mcpStartupFirstSeenAt) {
    state.mcpStartupFirstSeenAt = now;
    console.warn('[CodexMcpStartupWatchdog] seen tab=' + String(tabId).slice(-12)
      + ' phase=' + (phase || '-')
      + ' command=' + (state.command || 'unknown')
      + ' session=' + (state.sessionId ? String(state.sessionId).slice(0, 8) : 'none')
      + ' sample=' + (mcpInfo.sampleMode || '-')
      + ' thresholdMs=' + CODEX_MCP_STARTUP_RESTART_MS
      + ' preview=' + JSON.stringify(mcpInfo.preview || ''));
  }
  state.mcpStartupLastSeenAt = now;
  state.mcpStartupPreview = mcpInfo.preview || state.mcpStartupPreview || '';
  state.mcpStartupSampleMode = mcpInfo.sampleMode || state.mcpStartupSampleMode || '-';
  if (state.mcpStartupFirstSeenAt === now) {
    broadcastCodexStartingSnapshot(tabId, 'mcp-startup-seen');
  }
  const bucket = Math.floor((now - state.mcpStartupFirstSeenAt) / 5000);
  if (state.mcpStartupLastLogBucket !== bucket) {
    state.mcpStartupLastLogBucket = bucket;
    console.log('[CodexMcpStartupWatchdog] still waiting tab=' + String(tabId).slice(-12)
      + ' phase=' + (phase || '-')
      + ' ageMs=' + (now - state.mcpStartupFirstSeenAt)
      + ' restartSent=' + !!state.mcpStartupRestarting);
  }
  if (state.mcpStartupTimer || state.mcpStartupRestarting) return;
  const delayMs = Math.max(0, CODEX_MCP_STARTUP_RESTART_MS - (now - state.mcpStartupFirstSeenAt));
  state.mcpStartupTimer = setTimeout(() => {
    state.mcpStartupTimer = null;
    void restartCodexAfterMcpStartupWatchdog(tabId, state, mcpInfo).catch((err) => {
      console.warn('[CodexMcpStartupWatchdog] restart failed tab=' + String(tabId).slice(-12)
        + ' ' + (err?.message || String(err)));
    });
  }, delayMs);
}

function inspectCodexInputReadyVisibleText(visibleText, source = 'visible-buffer') {
  return inspectCodexInputReadyText(visibleText, '', { requireSyncMarker: false, source });
}

function isCodexInputReadyFrame(clean, raw) {
  return inspectCodexInputReadyFrame(clean, raw).ready;
}

function isCodexTuiReadyRelevantFrame(clean, raw) {
  const text = String(clean || '').replace(/\u00a0/g, ' ');
  return String(raw || '').includes(CODEX_SYNC_MARKER)
    || /OpenAI Codex|Sign in with ChatGPT|Sign in with Device Code|Provide your own API key|Press enter to continue|Use \/skills|Full Access|Find and fix a bug|Explain this codebase|Ask Codex|Context \d+%|directory:\s*|permissions:\s*|Update available|Starting\s+MCP\s+servers|Booting\s+MCP\s+server|MCP\s+startup\s+interrupted|esc\s+to\s+interrupt|Do you trust the contents|directory to resume this session|directory to fork this session/i.test(text);
}

function logCodexTuiReadyNotReady(tabId, inspected, raw, clean, phase) {
  if (!tabId || !inspected || inspected.ready) return;
  const compact = String(clean || '').replace(/\s+/g, ' ').trim();
  const previewTail = compact.slice(-260);
  codexTuiReadyLastNotReady.set(tabId, {
    ts: Date.now(),
    phase: phase || '-',
    source: inspected.source || '-',
    reason: inspected.reason || '-',
    blockers: Array.isArray(inspected.blockers) ? inspected.blockers.slice() : [],
    sampleMode: inspected.sampleMode || '-',
    sampleBytes: inspected.sampleBytes || 0,
    totalBytes: inspected.totalBytes || String(raw || '').length,
    startupArmed: codexStartupAutoEnter.has(tabId),
    previewTail,
  });
  const key = [
    phase || '-',
    inspected.source || '-',
    inspected.reason || '-',
    inspected.hasSynchronizedFrame ? 'sync' : 'nosync',
    inspected.hasCodexUiText ? 'ui' : 'noui',
    inspected.hasPromptGlyph ? 'prompt' : 'noprompt',
    previewTail.slice(-90),
  ].join('|');
  if (codexTuiReadyRejectKeys.get(tabId) === key) return;
  codexTuiReadyRejectKeys.set(tabId, key);
  console.log('[CodexTuiReady] not-ready tab=' + String(tabId).slice(-12)
    + ' phase=' + (phase || '-')
    + ' source=' + (inspected.source || '-')
    + ' reason=' + (inspected.reason || '-')
    + ' sample=' + (inspected.sampleMode || '-')
    + ' sampleBytes=' + (inspected.sampleBytes || 0)
    + ' totalBytes=' + (inspected.totalBytes || String(raw || '').length)
    + ' startupArmed=' + codexStartupAutoEnter.has(tabId)
    + ' rawBytes=' + String(raw || '').length
    + ' previewTail=' + JSON.stringify(previewTail));
  if (Array.isArray(inspected.blockers) && inspected.blockers.includes('auth-required')) {
    markCodexManualActionRequired(tabId, 'auth-required', inspected, clean, phase || 'not-ready');
  }
}

async function emitCodexTuiReadyAfterQuiet(tabId) {
  if (!tabId || codexTuiReadyTabs.has(tabId)) return;
  const raw = codexTuiReadyBuffers.get(tabId) || '';
  const clean = cleanCodexTuiFrame(raw);
  const rawInspect = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyFrame(clean, raw), 'quiet-raw');
  let readyInspect = rawInspect;
  let readyText = clean;
  if (mainWindow && !mainWindow.isDestroyed()) {
    const snapshot = await requestTerminalVisibleBufferSnapshot(
      mainWindow.webContents,
      tabId,
      'codex-tui-ready',
      700
    );
    if (snapshot?.success && Array.isArray(snapshot.lines)) {
      const snapshotSource = snapshot.source || 'visible-buffer';
      const visibleText = snapshot.lines.map((line) => line?.text || '').join('\n');
      tryHandleCodexStartupAutoEnter(tabId, '', {
        cleanSnapshot: visibleText,
        source: snapshotSource,
      });
      const visibleInspect = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyVisibleText(visibleText, snapshotSource), 'quiet-visible');
      if (!visibleInspect.ready) {
        const visibleBlockers = Array.isArray(visibleInspect.blockers) ? visibleInspect.blockers : [];
        if (visibleBlockers.length > 0) {
          logCodexTuiReadyNotReady(tabId, visibleInspect, raw, visibleText, 'quiet-visible');
          maybeArmCodexMcpStartupWatchdog(tabId, visibleInspect, visibleText, 'quiet-visible');
          maybeArmCodexMcpStartupWatchdog(tabId, rawInspect, clean, 'quiet-raw');
          return;
        }
        if (!rawInspect.ready) {
          logCodexTuiReadyNotReady(tabId, visibleInspect, raw, visibleText, 'quiet-visible');
          maybeArmCodexMcpStartupWatchdog(tabId, visibleInspect, visibleText, 'quiet-visible');
          maybeArmCodexMcpStartupWatchdog(tabId, rawInspect, clean, 'quiet-raw');
          return;
        }
        console.log('[CodexTuiReady] screen snapshot not ready but raw frame ready tab=' + String(tabId).slice(-12)
          + ' snapshotSource=' + snapshotSource
          + ' visibleReason=' + (visibleInspect.reason || '-')
          + ' visibleBlockers=' + (Array.isArray(visibleInspect.blockers) ? visibleInspect.blockers.join('+') : '-')
          + ' sample=' + (rawInspect.sampleMode || '-')
          + ' sampleBytes=' + (rawInspect.sampleBytes || 0)
          + ' totalBytes=' + (rawInspect.totalBytes || raw.length)
          + ' — accepting raw PTY ready; visible buffer is diagnostic only');
      } else {
        readyInspect = visibleInspect;
        readyText = visibleText;
      }
    } else if (!rawInspect.ready) {
      console.log('[CodexTuiReady] visible-buffer unavailable tab=' + String(tabId).slice(-12)
        + ' error=' + (snapshot?.error || 'bad-snapshot')
        + ' rawReason=' + (rawInspect.reason || '-'));
      logCodexTuiReadyNotReady(tabId, rawInspect, raw, clean, 'quiet-raw');
      maybeArmCodexMcpStartupWatchdog(tabId, rawInspect, clean, 'quiet-raw');
      return;
    } else {
      console.log('[CodexTuiReady] visible-buffer unavailable but raw frame ready tab=' + String(tabId).slice(-12)
        + ' error=' + (snapshot?.error || 'bad-snapshot')
        + ' sample=' + (rawInspect.sampleMode || '-')
        + ' sampleBytes=' + (rawInspect.sampleBytes || 0)
        + ' totalBytes=' + (rawInspect.totalBytes || raw.length)
        + ' — accepting raw ready for hidden/background tab');
    }
  } else if (!rawInspect.ready) {
    logCodexTuiReadyNotReady(tabId, rawInspect, raw, clean, 'quiet-raw');
    maybeArmCodexMcpStartupWatchdog(tabId, rawInspect, clean, 'quiet-raw');
    return;
  }
  if (codexTuiReadyProcessProbeTabs.has(tabId)) return;
  codexTuiReadyProcessProbeTabs.add(tabId);
  let matches = [];
  try {
    matches = await findAiDescendantProcessesByTab(tabId, 'codex');
  } finally {
    codexTuiReadyProcessProbeTabs.delete(tabId);
  }
  if (codexTuiReadyTabs.has(tabId)) return;
  if (matches.length === 0) {
    console.log('[CodexTuiReady] text-ready but no live codex process tab=' + String(tabId).slice(-12));
    return;
  }
  aiProcessLookupCache.set(aiProcessLookupCacheKey(tabId, 'codex'), { at: nodePerformance.now(), matches });

  codexTuiReadyTabs.add(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  finishCodexStartupLifecycle(tabId, 'tui-ready');
  const preview = readyText.replace(/\s+/g, ' ').trim().slice(0, 220);
  const readySource = readyInspect.source || 'raw';
  codexTuiReadyMeta.set(tabId, {
    at: Date.now(),
    source: readySource,
    reason: readyInspect.reason || '',
    preview,
  });
  console.log('[CodexTuiReady] tab=' + String(tabId).slice(-12)
    + ' input ready pids=' + matches.map(m => m.pid).join(',')
    + ' quietMs=' + CODEX_TUI_READY_QUIET_MS
    + ' source=' + readySource
    + ' preview=' + JSON.stringify(preview));
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:tui-ready', { tabId, ts: Date.now() });
  }
  ipcMain.emit('agent:tui-ready-internal', null, { tabId, toolType: 'codex' });
  broadcastCodexReadySnapshot(tabId, 'tui-ready');
}

async function tryEmitCodexTuiReady(tabId, data) {
  if (!tabId) return;
  const prev = codexTuiReadyBuffers.get(tabId) || '';
  let raw = prev + String(data || '');
  if (raw.length > CODEX_STARTUP_AUTO_ENTER_BUFFER_LIMIT) {
    raw = raw.slice(-CODEX_STARTUP_AUTO_ENTER_BUFFER_LIMIT);
  }
  codexTuiReadyBuffers.set(tabId, raw);
  const clean = cleanCodexTuiFrame(raw);
  const inspected = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyFrame(clean, raw), 'stream');
  if (codexTuiReadyTabs.has(tabId)) {
    if (!inspected.ready && Array.isArray(inspected.blockers) && inspected.blockers.length > 0) {
      if (hasCodexPromptOrTurnInFlight(tabId)) {
        return;
      }
      invalidateCodexTuiReadyForStartupBlocker(tabId, 'stream-after-ready', inspected.sampleText || clean, inspected.blockers);
      logCodexTuiReadyNotReady(tabId, inspected, raw, clean, 'stream-after-ready');
      maybeArmCodexMcpStartupWatchdog(tabId, inspected, clean, 'stream-after-ready');
    }
    return;
  }
  if (!inspected.ready && !isCodexTuiReadyRelevantFrame(clean, raw)) return;
  if (!inspected.ready) {
    logCodexTuiReadyNotReady(tabId, inspected, raw, clean, 'stream');
    maybeArmCodexMcpStartupWatchdog(tabId, inspected, clean, 'stream');
  }

  const existingTimer = codexTuiReadyQuietTimers.get(tabId);
  if (existingTimer) clearTimeout(existingTimer);
  const quietTimer = setTimeout(() => {
    codexTuiReadyQuietTimers.delete(tabId);
    void emitCodexTuiReadyAfterQuiet(tabId).catch((err) => {
      console.warn('[CodexTuiReady] quiet probe failed tab=' + String(tabId).slice(-12) + ' ' + (err?.message || String(err)));
    });
  }, CODEX_TUI_READY_QUIET_MS);
  codexTuiReadyQuietTimers.set(tabId, quietTimer);
}

function closeCodexWatcher(tabId, reason = 'close') {
  const state = codexWatchers.get(tabId);
  if (!state) return;
  try { state.watcher?.close?.(); } catch {}
  if (state.interval) clearInterval(state.interval);
  if (state.timeout) clearTimeout(state.timeout);
  codexWatchers.delete(tabId);
  console.log('[Codex Watcher] closed for tab:', tabId, 'reason:', reason);
}

function emitCodexBusy(tabId, busy, reason) {
  if (!tabId) return;
  console.log('[CodexTurn] busy tab=' + String(tabId).slice(-12) + ' busy=' + busy + ' reason=' + reason);
  if (busy) {
    clearCodexMcpStartupWatchdog(tabId, 'turn-busy:' + (reason || 'busy'));
  }
  recordActivity(tabId, busy, 'codex');
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:busy-state', { tabId, busy, reason });
  }
  const state = codexTurnWatchers.get(tabId);
  const inputReady = !busy && codexTuiReadyTabs.has(tabId);
  const sessionId = getCodexRuntimeSessionId(tabId);
  _webBroadcast(tabId, {
    type: 'busy',
    busy,
    reason,
    toolType: 'codex',
    commandType: 'codex',
    sessionId,
    sessionStatus: busy ? 'busy' : (inputReady ? 'active' : 'starting'),
    inputReady,
  });
  if (!busy) {
    _webBroadcast(tabId, {
      type: 'done',
      reason,
      toolType: 'codex',
      commandType: 'codex',
      sessionId,
    });
  }
}

// Live context-window fill % for the control-bar meter — Codex parity with the
// Claude/SDK context chip. The number is NOT our own running tally: it comes
// straight from the rollout `token_count.info`, the authoritative record Codex
// writes itself (same field that feeds usage/Timeline).
//
// Formula: info.last_token_usage.total_tokens / info.model_context_window.
// `last_token_usage` is the MOST RECENT single request — and because each turn
// re-sends the whole prior conversation, that request's total ≈ current context
// occupancy. Do NOT use info.total_token_usage here: that's cumulative
// session-lifetime billing (tens of millions of tokens across a long session →
// it divides to thousands-of-percent and clamps to 100% forever). The renderer
// reuses the exact same `contextPct` state + SQLite persistence as Claude, so
// once this fires the Codex chip seeds/persists for free. See
// fact-claude-control-bar.md::Context % bridge + fact-codex.md::Timeline.
function emitCodexContextPct(tabId, info) {
  if (!tabId || !info) return;
  const last = info.last_token_usage || {};
  const used = Number(last.total_tokens || 0);
  const windowSize = Number(info.model_context_window || 0);
  if (windowSize <= 0 || used <= 0) return;
  const pct = Math.min(100, Math.max(0, (used / windowSize) * 100));
  const state = codexTurnWatchers.get(tabId);
  const sessionId = state?.sessionId || codexKnownSessions.get(tabId) || null;
  console.log('[CodexContext] tab=' + String(tabId).slice(-12) + ' session=' + (sessionId || 'unknown') + ' used=' + used + ' window=' + windowSize + ' pct=' + pct.toFixed(1));
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:context-update', { tabId, sessionId, contextPct: pct });
  }
  // Mirror to mobile/native SSE subscribers via the same `bridge-update` envelope
  // Claude uses, so the phone header pill gets Codex context % too. Codex has no
  // StatusLine bridge, so without this the native client never receives a value.
  try {
    _webBroadcast(tabId, {
      type: 'bridge-update',
      sessionId: sessionId || undefined,
      contextPct: pct,
    });
  } catch {}
}

function closeCodexTurnWatcher(tabId, reason = 'close') {
  const state = codexTurnWatchers.get(tabId);
  if (!state) return;
  try { state.watcher?.close?.(); } catch {}
  if (state.interval) clearInterval(state.interval);
  codexTurnWatchers.delete(tabId);
  const audit = pendingCodexPasteAudit.get(tabId);
  if (audit?.awaitUserMessage) {
    console.warn('[CodexPasteAudit] tab=' + String(tabId).slice(-12)
      + ' source=' + (audit.source || '-')
      + ' watcher closed reason=' + reason
      + ' before matching user_message expectedLen=' + audit.expectedLen
      + ' expectedHash=' + audit.expectedHash);
    finishCodexPasteAudit(tabId, audit, {
      success: false,
      error: 'codex_turn_watcher_closed_before_user_message',
      reason,
      expectedLen: audit.expectedLen,
      expectedHash: audit.expectedHash,
    });
  }
  clearCodexPromptInFlight(tabId, 'watcher-closed:' + reason);
  if (state.busy) emitCodexBusy(tabId, false, reason);
  console.log('[CodexTurn] watcher closed tab=' + String(tabId).slice(-12) + ' session=' + (state.sessionId || 'unknown') + ' reason=' + reason);
}

ipcMain.handle('codex:get-turn-state', async (_event, tabId) => {
  const state = codexTurnWatchers.get(tabId);
  if (!state) {
    return { success: true, hasWatcher: false, busy: false };
  }
  return {
    success: true,
    hasWatcher: true,
    busy: state.busy === true,
    sessionId: state.sessionId || null,
    lastEventType: state.lastEventType || null,
    lastEventTs: state.lastEventTs || null,
    liveTurnEvents: state.liveTurnEvents || 0,
  };
});

ipcMain.handle('codex:get-runtime-session', async (_event, tabId) => {
  const turn = codexTurnWatchers.get(tabId);
  const payload = codexLastRunCommandPayload.get(tabId) || null;
  const dbSessionId = codexSessionIdFromDb(tabId);
  const sessionId = getCodexRuntimeSessionId(tabId);
  return {
    success: true,
    sessionId,
    turnSessionId: turn?.sessionId || null,
    knownSessionId: codexKnownSessions.get(tabId) || null,
    launchSessionId: payload?.sessionId || null,
    dbSessionId,
    hasLaunchPayload: !!payload,
  };
});

ipcMain.handle('codex:get-tui-ready', async (_event, tabId) => {
  return getCodexTuiReadyState(tabId);
});

ipcMain.handle('codex:get-draft-state', async (_event, tabId, options = {}) => {
  return requestTerminalCodexDraftState(
    mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    tabId,
    typeof options?.reason === 'string' ? options.reason : 'codex-get-draft-state',
    Number(options?.timeoutMs) || 700,
    {
      waitFor: typeof options?.waitFor === 'boolean' ? options.waitFor : undefined,
      waitTimeoutMs: Number(options?.waitTimeoutMs) || undefined,
    }
  );
});

ipcMain.handle('claude:get-draft-state', async (_event, tabId, options = {}) => {
  return requestTerminalClaudeDraftState(
    mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null,
    tabId,
    typeof options?.reason === 'string' ? options.reason : 'claude-get-draft-state',
    Number(options?.timeoutMs) || 700
  );
});

async function getCodexTuiReadyState(tabId) {
  let textReady = !!codexTuiReadyTabs.has(tabId);
  let manualAction = codexManualActionRequired.get(tabId) || null;
  let mcpStartup = getCodexMcpStartupStatus(tabId);
  let readyMeta = codexTuiReadyMeta.get(tabId) || null;
  if (textReady && readyMeta?.preview) {
    const blockers = inspectCodexStartupBlockersText(readyMeta.preview);
    if (blockers.length > 0) {
      const mcpIgnoreReason = isOnlyCodexMcpStartupBlocker(blockers)
        ? codexMcpStartupBlockerIgnoreReason(tabId)
        : null;
      if (mcpIgnoreReason) {
        logIgnoredCodexMcpStartupBlocker(tabId, {
          blockers,
          sampleText: readyMeta.preview,
          hasCodexUiText: true,
          hasComposerFrame: true,
        }, 'get-state-ready-preview', mcpIgnoreReason);
      } else if (!hasCodexPromptOrTurnInFlight(tabId)) {
        invalidateCodexTuiReadyForStartupBlocker(tabId, 'get-state-ready-preview', readyMeta.preview, blockers);
        textReady = false;
      }
    }
  }
  if (!textReady) {
    const visibleProbe = await probeCodexReadyFromVisibleBuffer(tabId, 'get-state').catch((err) => ({
      success: false,
      ready: false,
      error: err?.message || String(err),
    }));
    const visibleBlockers = Array.isArray(visibleProbe?.blockers) ? visibleProbe.blockers : [];
    if (visibleProbe?.ready) {
      await markCodexTuiReadyFromVisibleProbe(tabId, 'get-state');
    } else if (visibleBlockers.length === 0) {
      const rawProbe = probeCodexStartupFromRawBuffer(tabId, 'get-state');
      if (rawProbe?.ready) {
        await markCodexTuiReadyFromRawProbe(tabId, 'get-state');
      }
    }
    textReady = !!codexTuiReadyTabs.has(tabId);
  }
  manualAction = codexManualActionRequired.get(tabId) || null;
  const startupTimeout = !textReady && !manualAction ? getCodexStartupNoStateTimeout(tabId) : null;
  if (startupTimeout) {
    maybeSurfaceCodexStartupNoStateTimeout(tabId, startupTimeout);
  }
  mcpStartup = getCodexMcpStartupStatus(tabId);
  readyMeta = codexTuiReadyMeta.get(tabId) || null;
  manualAction = codexManualActionRequired.get(tabId) || null;
  const lastNotReady = codexTuiReadyLastNotReady.get(tabId) || (!textReady ? mcpStartup : null) || null;
  let processReady = false;
  if (textReady) {
    try {
      processReady = (await findAiDescendantProcessesByTabCached(tabId, 'codex')).length > 0;
    } catch {
      processReady = false;
    }
  }
  return {
    success: true,
    inputReady: textReady && processReady,
    textReady,
    processReady,
    lastNotReady,
    mcpStartup,
    readyMeta: readyMeta ? {
      ...readyMeta,
      ageMs: readyMeta.at ? Date.now() - readyMeta.at : null,
    } : null,
    startupFailed: !!startupTimeout,
    startupError: startupTimeout?.reason || null,
    manualActionRequired: !!manualAction,
    manualActionType: manualAction?.type || null,
  };
}

async function markCodexTuiReadyAfterVerifiedComposer(tabId, reason = 'verified-composer') {
  if (!tabId) return false;
  let matches = [];
  try {
    matches = await findAiDescendantProcessesByTab(tabId, 'codex');
  } catch {
    matches = [];
  }
  if (matches.length === 0) {
    console.log('[CodexTuiReady] verified composer ignored tab=' + String(tabId).slice(-12)
      + ' reason=' + reason + ' no-live-process');
    return false;
  }
  aiProcessLookupCache.set(aiProcessLookupCacheKey(tabId, 'codex'), { at: nodePerformance.now(), matches });
  const hadReady = codexTuiReadyTabs.has(tabId);
  codexTuiReadyTabs.add(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  codexTuiReadyLastNotReady.delete(tabId);
  finishCodexStartupLifecycle(tabId, reason);
  codexTuiReadyMeta.set(tabId, {
    at: Date.now(),
    source: 'verified-composer',
    reason,
    preview: '',
  });
  console.log('[CodexTuiReady] tab=' + String(tabId).slice(-12)
    + ' input ready via verified composer reason=' + reason
    + ' hadReady=' + hadReady
    + ' pids=' + matches.map(m => m.pid).join(','));
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:tui-ready', { tabId, ts: Date.now(), reason });
  }
  ipcMain.emit('agent:tui-ready-internal', null, { tabId, toolType: 'codex' });
  broadcastCodexReadySnapshot(tabId, reason);
  return true;
}

async function pokeCodexStartupPromptFromVisibleBuffer(tabId, reason = 'external-prompt') {
  if (!tabId || !mainWindow || mainWindow.isDestroyed()) {
    return { success: false, error: 'no-main-window' };
  }
  const snapshot = await requestTerminalVisibleBufferSnapshot(
    mainWindow.webContents,
    tabId,
    'codex-startup-' + reason,
    1000
  );
  if (!snapshot?.success || !Array.isArray(snapshot.lines)) {
    return { success: false, error: snapshot?.error || 'snapshot-unavailable' };
  }
  const snapshotSource = snapshot.source || 'visible-buffer';
  const visibleText = snapshot.lines.map((line) => line?.text || '').join('\n');
  tryHandleCodexStartupAutoEnter(tabId, '', {
    cleanSnapshot: visibleText,
    source: snapshotSource + ':' + reason,
  });
  const inspected = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyVisibleText(visibleText, snapshotSource), 'startup-visible-' + reason);
  return {
    success: true,
    ready: inspected.ready,
    reason: inspected.reason || null,
    blockers: inspected.blockers || null,
  };
}

async function probeCodexReadyFromVisibleBuffer(tabId, reason = 'visible-probe') {
  if (!tabId || !mainWindow || mainWindow.isDestroyed()) {
    return { success: false, error: 'no-main-window', ready: false };
  }
  const snapshot = await requestTerminalVisibleBufferSnapshot(
    mainWindow.webContents,
    tabId,
    'codex-ready-' + reason,
    700
  );
  if (!snapshot?.success || !Array.isArray(snapshot.lines)) {
    return { success: false, error: snapshot?.error || 'snapshot-unavailable', ready: false };
  }
  const snapshotSource = snapshot.source || 'visible-buffer';
  const visibleText = snapshot.lines.map((line) => line?.text || '').join('\n');
  tryHandleCodexStartupAutoEnter(tabId, '', {
    cleanSnapshot: visibleText,
    source: snapshotSource + ':' + reason,
  });
  const inspected = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyVisibleText(visibleText, snapshotSource), 'visible-probe-' + reason);
  if (!inspected.ready) {
    logCodexTuiReadyNotReady(tabId, inspected, '', visibleText, 'visible-probe-' + reason);
    maybeArmCodexMcpStartupWatchdog(tabId, inspected, visibleText, 'visible-probe-' + reason);
  }
  return {
    success: true,
    ready: inspected.ready,
    reason: inspected.reason || null,
    blockers: inspected.blockers || null,
    inspected,
    visibleText,
  };
}

async function markCodexTuiReadyFromVisibleProbe(tabId, reason = 'visible-probe') {
  if (!tabId || codexTuiReadyTabs.has(tabId)) return false;
  if (!mainWindow || mainWindow.isDestroyed()) return false;
  const snapshot = await requestTerminalVisibleBufferSnapshot(
    mainWindow.webContents,
    tabId,
    'codex-ready-' + reason,
    1000
  );
  if (!snapshot?.success || !Array.isArray(snapshot.lines)) return false;
  const snapshotSource = snapshot.source || 'visible-buffer';
  const visibleText = snapshot.lines.map((line) => line?.text || '').join('\n');
  const inspected = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyVisibleText(visibleText, snapshotSource), 'visible-probe-' + reason);
  if (!inspected.ready) return false;
  let matches = [];
  try {
    matches = await findAiDescendantProcessesByTab(tabId, 'codex');
  } catch {
    matches = [];
  }
  if (matches.length === 0 || codexTuiReadyTabs.has(tabId)) return false;
  aiProcessLookupCache.set(aiProcessLookupCacheKey(tabId, 'codex'), { at: nodePerformance.now(), matches });
  codexTuiReadyTabs.add(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  finishCodexStartupLifecycle(tabId, reason);
  const preview = visibleText.replace(/\s+/g, ' ').trim().slice(0, 220);
  codexTuiReadyMeta.set(tabId, {
    at: Date.now(),
    source: 'visible-probe',
    reason,
    preview,
  });
  console.log('[CodexTuiReady] tab=' + String(tabId).slice(-12)
    + ' input ready via visible probe reason=' + reason
    + ' pids=' + matches.map(m => m.pid).join(',')
    + ' preview=' + JSON.stringify(preview));
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:tui-ready', { tabId, ts: Date.now() });
  }
  ipcMain.emit('agent:tui-ready-internal', null, { tabId, toolType: 'codex' });
  broadcastCodexReadySnapshot(tabId, reason);
  return true;
}

function probeCodexStartupFromRawBuffer(tabId, reason = 'raw-probe') {
  const raw = codexTuiReadyBuffers.get(tabId) || '';
  if (!raw) {
    return { success: false, error: 'no-pty-buffer', ready: false, reason: 'no-pty-buffer' };
  }
  const clean = cleanCodexTuiFrame(raw);
  tryHandleCodexStartupAutoEnter(tabId, '', {
    cleanSnapshot: clean,
    source: 'raw-buffer:' + reason,
  });
  const inspected = normalizeCodexMcpStartupInspection(tabId, inspectCodexInputReadyFrame(clean, raw), 'raw-probe-' + reason);
  if (!inspected.ready) {
    logCodexTuiReadyNotReady(tabId, inspected, raw, clean, 'raw-probe-' + reason);
    maybeArmCodexMcpStartupWatchdog(tabId, inspected, clean, 'raw-probe-' + reason);
  }
  return {
    success: true,
    ready: inspected.ready,
    reason: inspected.reason || null,
    blockers: inspected.blockers || null,
    inspected,
    clean,
    raw,
  };
}

async function markCodexTuiReadyFromRawProbe(tabId, reason = 'raw-probe') {
  if (!tabId || codexTuiReadyTabs.has(tabId)) return false;
  const probe = probeCodexStartupFromRawBuffer(tabId, reason);
  if (!probe.success || !probe.ready) return false;
  let matches = [];
  try {
    matches = await findAiDescendantProcessesByTab(tabId, 'codex');
  } catch {
    matches = [];
  }
  if (matches.length === 0 || codexTuiReadyTabs.has(tabId)) return false;
  aiProcessLookupCache.set(aiProcessLookupCacheKey(tabId, 'codex'), { at: nodePerformance.now(), matches });
  codexTuiReadyTabs.add(tabId);
  codexTuiReadyBuffers.delete(tabId);
  codexTuiReadyRejectKeys.delete(tabId);
  codexTuiReadyLastNotReady.delete(tabId);
  finishCodexStartupLifecycle(tabId, reason);
  const preview = String(probe.clean || '').replace(/\s+/g, ' ').trim().slice(0, 220);
  codexTuiReadyMeta.set(tabId, {
    at: Date.now(),
    source: 'raw-probe',
    reason,
    preview,
  });
  console.log('[CodexTuiReady] tab=' + String(tabId).slice(-12)
    + ' input ready via raw probe reason=' + reason
    + ' pids=' + matches.map(m => m.pid).join(',')
    + ' preview=' + JSON.stringify(preview));
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('codex:tui-ready', { tabId, ts: Date.now(), reason });
  }
  ipcMain.emit('agent:tui-ready-internal', null, { tabId, toolType: 'codex' });
  broadcastCodexReadySnapshot(tabId, reason);
  return true;
}

async function ensureCodexInputReadyForExternalPrompt(tabId, {
  timeoutMs = CODEX_EXTERNAL_PROMPT_READY_TIMEOUT_MS,
  reason = 'external-prompt',
} = {}) {
  const initial = await getCodexTuiReadyState(tabId);
  if (initial.inputReady) return { success: true, ready: initial, waitedMs: 0 };
  if (initial.manualActionRequired) {
    return {
      success: false,
      error: 'codex_manual_action_required',
      reason: initial.manualActionType || initial.lastNotReady?.reason || 'manual-action-required',
      blockers: initial.lastNotReady?.blockers || null,
      ready: initial,
      waitedMs: 0,
    };
  }

  if (!codexStartupAutoEnter.has(tabId)) {
    armCodexStartupAutoEnter(tabId, {
      command: reason,
      sessionId: getCodexRuntimeSessionId(tabId),
      cwd: terminalProjects.get(tabId) || null,
    });
  }
  const poke = probeCodexStartupFromRawBuffer(tabId, reason);
  if (poke?.ready && await markCodexTuiReadyFromRawProbe(tabId, reason)) {
    const ready = await getCodexTuiReadyState(tabId);
    if (ready.inputReady) return { success: true, ready, waitedMs: 0, poke };
  }
  const afterPoke = await getCodexTuiReadyState(tabId);
  if (afterPoke.inputReady) return { success: true, ready: afterPoke, waitedMs: 0, poke };
  if (afterPoke.manualActionRequired) {
    return {
      success: false,
      error: 'codex_manual_action_required',
      reason: afterPoke.manualActionType || afterPoke.lastNotReady?.reason || 'manual-action-required',
      blockers: afterPoke.lastNotReady?.blockers || null,
      ready: afterPoke,
      waitedMs: 0,
      poke,
    };
  }

  const startedAt = Date.now();
  return await new Promise((resolve) => {
    let settled = false;
    const finish = async (payload) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      ipcMain.removeListener('agent:tui-ready-internal', onReady);
      resolve(payload);
    };
    const onReady = async (_event, payload) => {
      if (!payload || payload.tabId !== tabId || payload.toolType !== 'codex') return;
      const state = await getCodexTuiReadyState(tabId);
      if (state.inputReady) {
        finish({ success: true, ready: state, waitedMs: Date.now() - startedAt, poke });
      }
    };
    const timer = setTimeout(async () => {
      const state = await getCodexTuiReadyState(tabId);
      if (state.manualActionRequired) {
        finish({
          success: false,
          error: 'codex_manual_action_required',
          reason: state.manualActionType || state.lastNotReady?.reason || 'manual-action-required',
          blockers: state.lastNotReady?.blockers || null,
          ready: state,
          waitedMs: Date.now() - startedAt,
          poke,
        });
        return;
      }
      const lastPoke = probeCodexStartupFromRawBuffer(tabId, reason + '-timeout');
      if (lastPoke?.ready && await markCodexTuiReadyFromRawProbe(tabId, reason + '-timeout')) {
        const ready = await getCodexTuiReadyState(tabId);
        if (ready.inputReady) {
          finish({ success: true, ready, waitedMs: Date.now() - startedAt, poke: lastPoke });
          return;
        }
      }
      const afterLastPoke = await getCodexTuiReadyState(tabId);
      if (afterLastPoke.manualActionRequired) {
        finish({
          success: false,
          error: 'codex_manual_action_required',
          reason: afterLastPoke.manualActionType || afterLastPoke.lastNotReady?.reason || 'manual-action-required',
          blockers: afterLastPoke.lastNotReady?.blockers || null,
          ready: afterLastPoke,
          waitedMs: Date.now() - startedAt,
          poke: lastPoke || poke,
        });
        return;
      }
      finish({
        success: false,
        error: 'codex_not_input_ready',
        reason: lastPoke?.reason || poke?.reason || 'timeout',
        blockers: lastPoke?.blockers || poke?.blockers || null,
        ready: afterLastPoke || state,
        waitedMs: Date.now() - startedAt,
      });
    }, Math.max(1000, timeoutMs));
    ipcMain.on('agent:tui-ready-internal', onReady);
  });
}

function codexEventType(record) {
  if (!record || record.type !== 'event_msg') return null;
  return record.payload?.type || null;
}

function codexLiveUuid(state, record, kind) {
  state.liveMessageSeq = (state.liveMessageSeq || 0) + 1;
  const sid = state.sessionId || 'unknown';
  const ts = String(record?.timestamp || Date.now()).replace(/[^0-9A-Za-z]+/g, '-');
  return 'codex-live-' + sid + '-' + ts + '-' + state.liveMessageSeq + '-' + kind;
}

function extractCodexLiveText(content) {
  if (!content) return '';
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) {
    if (typeof content.text === 'string') return content.text;
    if (typeof content.value === 'string') return content.value;
    if (typeof content.message === 'string') return content.message;
    return '';
  }
  const out = [];
  for (const part of content) {
    if (!part) continue;
    if (typeof part === 'string') {
      out.push(part);
    } else if (typeof part.text === 'string') {
      out.push(part.text);
    } else if (typeof part.value === 'string') {
      out.push(part.value);
    } else if (typeof part.message === 'string') {
      out.push(part.message);
    }
  }
  return out.join('\n');
}

function extractCodexLiveReasoning(summary) {
  if (!summary) return '';
  if (typeof summary === 'string') return summary;
  if (!Array.isArray(summary)) return '';
  return summary.map((part) => {
    if (!part) return '';
    if (typeof part === 'string') return part;
    return part.text || part.summary || part.content || '';
  }).filter(Boolean).join('\n');
}

function parseCodexLiveArgs(payload) {
  const raw = payload?.arguments != null ? payload.arguments : payload?.input;
  if (raw == null) return {};
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === 'object' ? parsed : { value: parsed };
    } catch {
      return { raw };
    }
  }
  return raw && typeof raw === 'object' ? raw : { value: raw };
}

function buildCodexLiveRawMessage(state, record) {
  const payload = record?.payload || {};
  const event = codexEventType(record);
  const sessionId = state.sessionId || codexKnownSessions.get(state.tabId) || null;

  if (record.type === 'event_msg' && event === 'user_message') {
    const text = payload.message || extractCodexLiveText(payload.content) || '';
    if (!String(text).trim()) return null;
    const uuid = codexLiveUuid(state, record, 'user');
    return {
      type: 'user',
      uuid,
      sessionId,
      message: { role: 'user', content: [{ type: 'text', text }] },
    };
  }

  if (record.type !== 'response_item') return null;

  if (payload.type === 'reasoning') {
    const thinking = extractCodexLiveReasoning(payload.summary);
    if (!String(thinking).trim()) return null;
    const uuid = codexLiveUuid(state, record, 'thinking');
    return {
      type: 'assistant',
      uuid,
      sessionId,
      message: {
        id: uuid,
        role: 'assistant',
        content: [{ type: 'thinking', thinking }],
      },
    };
  }

  if (payload.type === 'message' && payload.role === 'assistant') {
    const text = extractCodexLiveText(payload.content);
    if (!String(text).trim()) return null;
    const uuid = codexLiveUuid(state, record, 'assistant');
    return {
      type: 'assistant',
      uuid,
      sessionId,
      message: {
        id: uuid,
        role: 'assistant',
        content: [{ type: 'text', text }],
      },
    };
  }

  if (payload.type === 'function_call' || payload.type === 'custom_tool_call') {
    const callId = payload.call_id || payload.id || codexLiveUuid(state, record, 'tool');
    const uuid = codexLiveUuid(state, record, 'tool');
    return {
      type: 'assistant',
      uuid,
      sessionId,
      message: {
        id: uuid,
        role: 'assistant',
        content: [{
          type: 'tool_use',
          id: callId,
          name: payload.name || payload.tool_name || payload.type || 'tool',
          input: parseCodexLiveArgs(payload),
        }],
      },
    };
  }

  if (payload.type === 'function_call_output' || payload.type === 'custom_tool_call_output') {
    const callId = payload.call_id || payload.id;
    if (!callId) return null;
    const output = typeof payload.output === 'string'
      ? payload.output
      : payload.output != null ? JSON.stringify(payload.output, null, 2) : '';
    const uuid = codexLiveUuid(state, record, 'tool-result');
    return {
      type: 'user',
      uuid,
      sessionId,
      message: {
        role: 'user',
        content: [{
          type: 'tool_result',
          tool_use_id: callId,
          content: output,
          is_error: !!payload.is_error,
        }],
      },
    };
  }

  return null;
}

function summarizeCodexTurnChunk(text) {
  const summary = {
    lines: 0,
    parseErrors: 0,
    eventCounts: new Map(),
    responseItems: 0,
    compacted: 0,
    otherTypes: new Map(),
    lastEvent: null,
    lastResponseItem: null,
  };
  const bump = (map, key) => map.set(key, (map.get(key) || 0) + 1);
  for (const line of String(text || '').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    summary.lines += 1;
    let record;
    try {
      record = JSON.parse(trimmed);
    } catch {
      summary.parseErrors += 1;
      continue;
    }
    if (record.type === 'event_msg') {
      const event = codexEventType(record) || 'unknown';
      bump(summary.eventCounts, event);
      summary.lastEvent = event + '@' + (record.timestamp || 'n/a');
    } else if (record.type === 'response_item') {
      summary.responseItems += 1;
      const item = record.payload || record.item || record.response_item || {};
      summary.lastResponseItem = (item.type || record.payload?.type || 'response_item') + '@' + (record.timestamp || 'n/a');
    } else if (record.type === 'compacted') {
      summary.compacted += 1;
    } else {
      bump(summary.otherTypes, record.type || 'unknown');
    }
  }
  const fmtMap = (map) => Array.from(map.entries()).map(([k, v]) => k + ':' + v).join(',') || '-';
  return {
    lines: summary.lines,
    parseErrors: summary.parseErrors,
    events: fmtMap(summary.eventCounts),
    responseItems: summary.responseItems,
    compacted: summary.compacted,
    other: fmtMap(summary.otherTypes),
    lastEvent: summary.lastEvent || '-',
    lastResponseItem: summary.lastResponseItem || '-',
  };
}

function processCodexTurnLine(state, line) {
  const text = String(line || '').trim();
  if (!text) return;
  let record;
  try {
    record = JSON.parse(text);
  } catch {
    return;
  }
  const liveMessage = buildCodexLiveRawMessage(state, record);
  if (liveMessage) {
    _webBroadcast(state.tabId, {
      type: 'message',
      sessionId: state.sessionId || codexKnownSessions.get(state.tabId) || null,
      message: liveMessage,
    });
  }
  const event = codexEventType(record);
  if (!event) return;
  if (event === 'user_message') {
    const audit = pendingCodexPasteAudit.get(state.tabId);
    if (audit) {
      try {
        const actualText = record.payload?.message || extractCodexLiveText(record.payload?.content) || '';
        const actualLen = actualText.length;
        const actualHash = pasteAuditHash(actualText);
        const match = actualLen === audit.expectedLen && actualHash === audit.expectedHash;
        if (match) {
          console.log('[CodexPasteAudit] tab=' + String(state.tabId).slice(-12)
            + ' source=' + (audit.source || '-')
            + ' ✅ match len=' + actualLen
            + ' hash=' + actualHash
            + ' (sent ' + (Date.now() - audit.sentAt) + 'ms ago)');
          finishCodexPasteAudit(state.tabId, audit, {
            success: true,
            actualLen,
            actualHash,
            expectedLen: audit.expectedLen,
            expectedHash: audit.expectedHash,
          });
        } else {
          const canonicalMatch = codexCanonicalUserMessageMatch({ ...audit, actualPayload: record.payload || null }, actualText);
          if (canonicalMatch) {
            console.warn('[CodexPasteAudit:CANONICAL_MATCH] tab=' + String(state.tabId).slice(-12)
              + ' source=' + (audit.source || '-')
              + ' reason=' + canonicalMatch.reason
              + ' expectedLen=' + audit.expectedLen
              + ' actualLen=' + actualLen
              + ' Δ=' + (actualLen - audit.expectedLen)
              + ' expectedHash=' + audit.expectedHash
              + ' actualHash=' + actualHash);
            finishCodexPasteAudit(state.tabId, audit, {
              success: true,
              canonicalized: true,
              canonicalReason: canonicalMatch.reason,
              actualLen,
              actualHash,
              expectedLen: audit.expectedLen,
              expectedHash: audit.expectedHash,
            });
            return;
          }
          console.warn('[CodexPasteAudit:MISMATCH] tab=' + String(state.tabId).slice(-12)
            + ' source=' + (audit.source || '-')
            + ' expectedLen=' + audit.expectedLen
            + ' actualLen=' + actualLen
            + ' Δ=' + (actualLen - audit.expectedLen)
            + ' expectedHash=' + audit.expectedHash
            + ' actualHash=' + actualHash
            + ' expectedHead=' + JSON.stringify(audit.headPreview)
            + ' actualHead=' + JSON.stringify(pasteAuditPreview(actualText))
            + ' expectedTail=' + JSON.stringify(audit.tailPreview)
            + ' actualTail=' + JSON.stringify(pasteAuditPreview(actualText, Math.max(0, actualText.length - 80))));
          finishCodexPasteAudit(state.tabId, audit, {
            success: false,
            error: 'codex_user_message_audit_mismatch',
            expectedLen: audit.expectedLen,
            actualLen,
            expectedHash: audit.expectedHash,
            actualHash,
          });
        }
      } catch (e) {
        console.warn('[CodexPasteAudit] compare failed tab=' + String(state.tabId).slice(-12) + ': ' + (e?.message || String(e)));
        finishCodexPasteAudit(state.tabId, audit, {
          success: false,
          error: 'codex_user_message_audit_compare_failed',
          message: e?.message || String(e),
          expectedLen: audit.expectedLen,
          expectedHash: audit.expectedHash,
        });
      }
    }
  }
  if (event === 'token_count') {
    // Codex emits token_count on every assistant step (and a final one at
    // turn end) — this is the live feed for the context-window meter. Not a
    // turn-lifecycle event, so it doesn't touch busy/lastEvent bookkeeping.
    emitCodexContextPct(state.tabId, record.payload?.info);
    return;
  }
  if (event === 'task_started') {
    state.lastEventType = event;
    state.lastEventTs = record.timestamp || null;
    state.liveTurnEvents = (state.liveTurnEvents || 0) + 1;
    state.busy = true;
    console.log('[CodexTurn] event tab=' + String(state.tabId).slice(-12) + ' session=' + state.sessionId + ' event=task_started ts=' + (record.timestamp || 'n/a'));
    clearCodexPromptInFlight(state.tabId, 'task_started');
    finishCodexStartupLifecycle(state.tabId, 'task_started');
    emitCodexBusy(state.tabId, true, 'task_started');
    return;
  }
  if (event === 'task_complete' || event === 'turn_aborted') {
    state.lastEventType = event;
    state.lastEventTs = record.timestamp || null;
    state.liveTurnEvents = (state.liveTurnEvents || 0) + 1;
    state.busy = false;
    console.log('[CodexTurn] event tab=' + String(state.tabId).slice(-12) + ' session=' + state.sessionId + ' event=' + event + ' ts=' + (record.timestamp || 'n/a'));
    const audit = pendingCodexPasteAudit.get(state.tabId);
    if (audit?.awaitUserMessage) {
      console.warn('[CodexPasteAudit] tab=' + String(state.tabId).slice(-12)
        + ' source=' + (audit.source || '-')
        + ' ended event=' + event
        + ' before matching user_message expectedLen=' + audit.expectedLen
        + ' expectedHash=' + audit.expectedHash);
      finishCodexPasteAudit(state.tabId, audit, {
        success: false,
        error: event === 'turn_aborted'
          ? 'codex_turn_aborted_before_user_message'
          : 'codex_turn_completed_without_user_message',
        expectedLen: audit.expectedLen,
        expectedHash: audit.expectedHash,
      });
    }
    clearCodexPromptInFlight(state.tabId, event);
    if (event === 'task_complete') {
      markCodexTuiReadyFromTurnEnd(state.tabId, event);
    } else {
      finishCodexStartupLifecycle(state.tabId, event);
    }
    emitCodexBusy(state.tabId, false, event);
    _webBroadcast(state.tabId, {
      type: 'done',
      sessionId: state.sessionId || codexKnownSessions.get(state.tabId) || null,
      reason: event,
    });
  }
}

function inferCodexBusyFromText(text) {
  let inferred = null;
  let lastTokenInfo = null;
  const lines = String(text || '').split('\n');
  for (const line of lines) {
    const trimmed = String(line || '').trim();
    if (!trimmed || trimmed[0] !== '{') continue;
    let record;
    try {
      record = JSON.parse(trimmed);
    } catch {
      continue;
    }
    const event = codexEventType(record);
    if (event === 'task_started') {
      inferred = { busy: true, event, timestamp: record.timestamp || null };
    } else if (event === 'task_complete' || event === 'turn_aborted') {
      inferred = { busy: false, event, timestamp: record.timestamp || null };
    } else if (event === 'token_count' && record.payload?.info) {
      // Carry the freshest token_count so a resumed/re-armed watcher can seed
      // the context meter from the transcript tail without waiting for the
      // next live turn. Returned separately from busy because token_count is
      // not a turn-lifecycle event.
      lastTokenInfo = record.payload.info;
    }
  }
  return { inferred, lastTokenInfo };
}

async function catchUpCodexTurnState(tabId, filePath, fileSize, { suppressBusy = false, reason = 'catch-up' } = {}) {
  const readSize = Math.min(fileSize, CODEX_TURN_CATCHUP_BYTES);
  if (readSize <= 0) return;
  const start = Math.max(0, fileSize - readSize);
  let handle = null;
  try {
    handle = await fs.promises.open(filePath, 'r');
    const buffer = Buffer.alloc(readSize);
    const { bytesRead } = await handle.read(buffer, 0, readSize, start);
    let text = buffer.subarray(0, bytesRead).toString('utf8');
    if (start > 0) {
      const firstNewline = text.indexOf('\n');
      text = firstNewline >= 0 ? text.slice(firstNewline + 1) : '';
    }

    const { inferred, lastTokenInfo } = inferCodexBusyFromText(text);
    const state = codexTurnWatchers.get(tabId);
    if (!state || state.filePath !== filePath) return;

    // Seed the context meter from the tail's freshest token_count, independent of
    // turn-lifecycle events: a resumed/re-armed watcher should show the current
    // context fill immediately instead of waiting for the next live turn. Fires
    // even when there were no task_* events in the window.
    if (lastTokenInfo) emitCodexContextPct(tabId, lastTokenInfo);

    if (!inferred) {
      console.log('[CodexTurn] catch-up no-events tab=' + String(tabId).slice(-12) + ' bytes=' + bytesRead + ' start=' + start);
      return;
    }

    if (
      state.liveTurnEvents > 0 &&
      (!inferred.timestamp || !state.lastEventTs || inferred.timestamp <= state.lastEventTs)
    ) {
      console.log('[CodexTurn] catch-up skipped tab=' + String(tabId).slice(-12) + ' inferred=' + inferred.event + ' inferredTs=' + (inferred.timestamp || 'n/a') + ' live=' + state.lastEventType + ' liveTs=' + (state.lastEventTs || 'n/a'));
      return;
    }

    if (suppressBusy && inferred.busy) {
      console.log('[CodexTurn] catch-up suppressed tab=' + String(tabId).slice(-12)
        + ' event=' + inferred.event
        + ' ts=' + (inferred.timestamp || 'n/a')
        + ' reason=' + reason
        + ' bytes=' + bytesRead
        + ' start=' + start);
      return;
    }

    state.lastEventType = inferred.event;
    state.lastEventTs = inferred.timestamp || null;
    console.log('[CodexTurn] catch-up tab=' + String(tabId).slice(-12) + ' event=' + inferred.event + ' busy=' + inferred.busy + ' ts=' + (inferred.timestamp || 'n/a') + ' bytes=' + bytesRead + ' start=' + start);
    if (state.busy !== inferred.busy) {
      state.busy = inferred.busy;
      if (!inferred.busy && inferred.event === 'task_complete') {
        clearCodexPromptInFlight(tabId, 'catch-up-' + inferred.event);
        markCodexTuiReadyFromTurnEnd(tabId, 'catch-up-' + inferred.event);
      }
      emitCodexBusy(tabId, inferred.busy, 'catch-up-' + inferred.event);
    }
    if (!inferred.busy) {
      _webBroadcast(tabId, {
        type: 'done',
        sessionId: state.sessionId || getCodexRuntimeSessionId(tabId),
        reason: 'catch-up-' + inferred.event,
      });
    }
  } catch (e) {
    console.warn('[CodexTurn] catch-up failed tab=' + String(tabId).slice(-12) + ' file=' + filePath + ' error=' + (e?.message || String(e)));
  } finally {
    if (handle) {
      try { await handle.close(); } catch {}
    }
  }
}

function processCodexTurnText(state, text) {
  const combined = (state.partial || '') + String(text || '');
  const lines = combined.split('\n');
  state.partial = lines.pop() || '';
  for (const line of lines) processCodexTurnLine(state, line);
}

async function scanCodexTurnAppend(tabId, reason = 'scan') {
  const state = codexTurnWatchers.get(tabId);
  if (!state) return;
  if (state.scanning) {
    state.needsScan = true;
    return;
  }
  state.scanning = true;
  try {
    do {
      state.needsScan = false;
      let stat;
      try {
        stat = await fs.promises.stat(state.filePath);
      } catch (e) {
        console.warn('[CodexTurn] stat failed tab=' + String(tabId).slice(-12) + ' reason=' + reason + ' error=' + e.message);
        return;
      }
      if (stat.size < state.offset) state.offset = 0;
      if (stat.size === state.offset) continue;

      const start = state.offset;
      const end = stat.size - 1;
      state.offset = stat.size;
      const chunk = await new Promise((resolve, reject) => {
        let out = '';
        const stream = fs.createReadStream(state.filePath, { start, end, encoding: 'utf8' });
        stream.on('data', (part) => { out += part; });
        stream.on('error', reject);
        stream.on('end', () => resolve(out));
      });
      const chunkSummary = summarizeCodexTurnChunk(chunk);
      console.log('[CodexTurn:Delta]' +
        ' tab=' + String(tabId).slice(-12) +
        ' session=' + (state.sessionId || 'unknown') +
        ' reason=' + reason +
        ' bytes=' + chunk.length +
        ' range=' + start + '..' + stat.size +
        ' lines=' + chunkSummary.lines +
        ' parseErrors=' + chunkSummary.parseErrors +
        ' events=' + chunkSummary.events +
        ' responseItems=' + chunkSummary.responseItems +
        ' compacted=' + chunkSummary.compacted +
        ' other=' + chunkSummary.other +
        ' lastEvent=' + chunkSummary.lastEvent +
        ' lastResponseItem=' + chunkSummary.lastResponseItem);
      processCodexTurnText(state, chunk);
    } while (state.needsScan);
  } finally {
    state.scanning = false;
  }
}

function startCodexTurnWatcher({ tabId, sessionId, filePath, catchUpPendingAudit = false, suppressBusyCatchUp = false, catchUpReason = 'start' }) {
  if (!tabId || !sessionId || !filePath) return false;
  const existing = codexTurnWatchers.get(tabId);
  if (existing?.sessionId === sessionId && existing?.filePath === filePath) return true;
  closeCodexTurnWatcher(tabId, 'replace');

  let offset = 0;
  let fileSize = 0;
  try {
    fileSize = fs.statSync(filePath).size;
    offset = catchUpPendingAudit && pendingCodexPasteAudit.has(tabId) ? 0 : fileSize;
  } catch (e) {
    console.warn('[CodexTurn] cannot start watcher tab=' + String(tabId).slice(-12) + ' session=' + sessionId + ' file=' + filePath + ' error=' + e.message);
    return false;
  }

  const state = {
    tabId,
    sessionId,
    filePath,
    offset,
    partial: '',
    busy: false,
    lastEventType: null,
    lastEventTs: null,
    liveTurnEvents: 0,
    scanning: false,
    needsScan: false,
    watcher: null,
    interval: null,
  };
  codexTurnWatchers.set(tabId, state);
  try {
    state.watcher = fs.watch(filePath, () => scanCodexTurnAppend(tabId, 'fs.watch'));
  } catch (e) {
    console.warn('[CodexTurn] fs.watch failed tab=' + String(tabId).slice(-12) + ' session=' + sessionId + ' error=' + e.message);
  }
  state.interval = setInterval(() => scanCodexTurnAppend(tabId, 'scan'), CODEX_WATCHER_SCAN_MS);
  console.log('[CodexTurn] watcher started tab=' + String(tabId).slice(-12) + ' session=' + sessionId + ' file=' + filePath + ' offset=' + offset + ' fileSize=' + fileSize + ' catchUpPendingAudit=' + !!catchUpPendingAudit + ' suppressBusyCatchUp=' + !!suppressBusyCatchUp);
  if (offset === 0 && fileSize > 0 && catchUpPendingAudit && pendingCodexPasteAudit.has(tabId)) {
    setImmediate(() => scanCodexTurnAppend(tabId, 'pending-audit-catchup'));
  } else {
    catchUpCodexTurnState(tabId, filePath, offset, {
      suppressBusy: !!suppressBusyCatchUp,
      reason: catchUpReason,
    });
  }
  return true;
}

function codexSessionIdFromDb(tabId) {
  if (!tabId || !projectManager?.db?.db) return null;
  try {
    const row = projectManager.db.db.prepare('SELECT codex_session_id FROM tabs WHERE tab_id = ? LIMIT 1').get(tabId);
    return row?.codex_session_id || null;
  } catch {
    return null;
  }
}

function getCodexBoundSessionId(tabId) {
  if (!tabId) return null;
  return codexTurnWatchers.get(tabId)?.sessionId
    || codexKnownSessions.get(tabId)
    || codexSessionIdFromDb(tabId)
    || null;
}

function getCodexSessionOwner(sessionId, exceptTabId = null) {
  if (!sessionId) return null;
  for (const [knownTabId, knownSessionId] of codexKnownSessions) {
    if (knownTabId !== exceptTabId && knownSessionId === sessionId) {
      return { tabId: knownTabId, source: 'memory' };
    }
  }
  try {
    const row = projectManager?.db?.db?.prepare(
      'SELECT tab_id FROM tabs WHERE codex_session_id = ? AND tab_id != ? LIMIT 1'
    ).get(sessionId, exceptTabId || '');
    if (row?.tab_id) return { tabId: row.tab_id, source: 'db' };
  } catch {}
  return null;
}

function getCodexWatcherExcludedSessionIds(tabId, sourceSessionId = null) {
  const ids = new Set();
  if (sourceSessionId) ids.add(String(sourceSessionId));
  for (const [, sessionId] of codexKnownSessions) {
    if (sessionId) ids.add(String(sessionId));
  }
  try {
    const rows = projectManager?.db?.db?.prepare(
      'SELECT tab_id, codex_session_id FROM tabs WHERE codex_session_id IS NOT NULL AND codex_session_id != ""'
    ).all() || [];
    for (const row of rows) {
      if (row?.codex_session_id) ids.add(String(row.codex_session_id));
    }
  } catch {}
  return Array.from(ids);
}

async function ensureCodexTurnWatcher(tabId, sessionId, cwd, options = {}) {
  const existing = codexTurnWatchers.get(tabId);
  if (existing && (!sessionId || existing.sessionId === sessionId)) return true;
  const resolvedSessionId = sessionId || codexSessionIdFromDb(tabId);
  if (!resolvedSessionId) {
    console.warn('[CodexTurn] no session id for watcher tab=' + String(tabId).slice(-12));
    return false;
  }
  try {
    const found = await codexDataModule._api.findCodexSessionFile(resolvedSessionId, cwd || terminalProjects.get(tabId));
    if (!found?.filePath) {
      console.warn('[CodexTurn] session file not found tab=' + String(tabId).slice(-12) + ' session=' + resolvedSessionId);
      return false;
    }
    return startCodexTurnWatcher({
      tabId,
      sessionId: resolvedSessionId,
      filePath: found.filePath,
      suppressBusyCatchUp: !!options.suppressBusyCatchUp,
      catchUpReason: options.catchUpReason || 'ensure',
    });
  } catch (e) {
    console.warn('[CodexTurn] ensure failed tab=' + String(tabId).slice(-12) + ' error=' + e.message);
    return false;
  }
}

function startCodexSessionWatcher(sender, { tabId, cwd, startedAt, sourceSessionId = null }) {
  closeCodexWatcher(tabId, 'restart');
  const sessionsDir = path.join(process.env.CODEX_HOME || path.join(os.homedir(), '.codex'), 'sessions');
  let found = false;
  let detecting = false;
  let detectCount = 0;
  const normalizedCwd = cwd || terminalProjects.get(tabId);

  const detect = async (reason = 'manual') => {
    if (found || detecting) return;
    detecting = true;
    detectCount += 1;
    try {
      const excludeSessionIds = getCodexWatcherExcludedSessionIds(tabId, sourceSessionId);
      const hit = await codexDataModule._api.findLatestCodexSession({
        cwd: normalizedCwd,
        sinceMs: startedAt || 0,
        sourceSessionId,
        excludeSessionIds,
      });
      if (hit?.sessionId && !found) {
        const owner = getCodexSessionOwner(hit.sessionId, tabId);
        if (owner) {
          console.warn('[Codex Watcher] duplicate session skipped:', hit.sessionId, 'candidateTab:', tabId, 'ownerTab:', owner.tabId, 'ownerSource:', owner.source, 'reason:', reason);
          return;
        }
        const boundSessionId = getCodexBoundSessionId(tabId);
        const strictLink = !!sourceSessionId && (
          hit.sourceMatched === true
          || hit.parentThreadId === sourceSessionId
          || hit.forkedFromId === sourceSessionId
        );
        if (boundSessionId && boundSessionId !== hit.sessionId && !strictLink) {
          console.warn('[Codex Watcher] adoption rejected: tab=' + String(tabId).slice(-12)
            + ' oldSession=' + String(boundSessionId).slice(0, 8)
            + ' newSession=' + String(hit.sessionId).slice(0, 8)
            + ' reason=' + reason
            + ' cwdMatched=' + !!hit.cwdMatched
            + ' sourceMatched=' + !!hit.sourceMatched
            + ' source=' + (sourceSessionId || 'n/a')
            + ' parent=' + (hit.parentThreadId || 'n/a')
            + ' forkedFrom=' + (hit.forkedFromId || 'n/a')
            + ' originator=' + (hit.originator || 'n/a')
            + ' threadSource=' + (hit.threadSource || 'n/a'));
          return;
        }
        found = true;
        console.log('[Codex Watcher] session detected:', hit.sessionId, 'tab:', tabId, 'reason:', reason, 'file:', hit.filePath, 'cwd:', hit.cwd || 'n/a', 'cwdMatched:', !!hit.cwdMatched, 'sourceMatched:', !!hit.sourceMatched, 'source:', sourceSessionId || 'n/a', 'threadSource:', hit.threadSource || 'n/a', 'parent:', hit.parentThreadId || 'n/a', 'forkedFrom:', hit.forkedFromId || 'n/a', 'originator:', hit.originator || 'n/a', 'excludeCount:', excludeSessionIds.length);
        setCodexKnownSession(tabId, hit.sessionId, sourceSessionId ? 'watcher-detected-linked' : 'watcher-detected');
        startCodexTurnWatcher({ tabId, sessionId: hit.sessionId, filePath: hit.filePath, catchUpPendingAudit: true });
        sender.send('codex:session-detected', { tabId, sessionId: hit.sessionId, cwd: hit.cwd || null });
        closeCodexWatcher(tabId, 'detected');
      } else if (detectCount <= 3 || detectCount % 10 === 0) {
        console.log('[Codex Watcher] miss tab:', tabId, 'reason:', reason, 'attempt:', detectCount, 'cwd:', normalizedCwd, 'since:', startedAt || 0, 'source:', sourceSessionId || 'n/a');
      }
    } catch (e) {
      console.warn('[Codex Watcher] detect failed:', e.message);
    } finally {
      detecting = false;
    }
  };

  try {
    fs.mkdirSync(sessionsDir, { recursive: true });
    const watcher = fs.watch(sessionsDir, { recursive: true }, () => {
      detect('fs.watch');
    });
    const interval = setInterval(() => detect('scan'), CODEX_WATCHER_SCAN_MS);
    const timeout = setTimeout(() => closeCodexWatcher(tabId, 'ttl'), CODEX_WATCHER_TTL_MS);
    codexWatchers.set(tabId, { watcher, interval, timeout, cwd: normalizedCwd, startedAt, sourceSessionId });
    console.log('[Codex Watcher] watching:', sessionsDir, 'tab:', tabId, 'cwd:', normalizedCwd, 'source:', sourceSessionId || 'n/a', 'ttlMs:', CODEX_WATCHER_TTL_MS);
  } catch (e) {
    console.warn('[Codex Watcher] fs.watch failed:', e.message);
    const interval = setInterval(() => detect('scan-no-watch'), CODEX_WATCHER_SCAN_MS);
    const timeout = setTimeout(() => closeCodexWatcher(tabId, 'ttl-no-watch'), CODEX_WATCHER_TTL_MS);
    codexWatchers.set(tabId, { watcher: null, interval, timeout, cwd: normalizedCwd, startedAt, sourceSessionId });
  }

  detect('start');
}

function shellQuote(value) {
  return "'" + String(value).replace(/'/g, "'\\''") + "'";
}

function readDefaultCodexSetting(key) {
  try {
    const value = projectManager?.db?.getAppState?.(key);
    if (typeof value !== 'string') return null;
    const trimmed = value.trim();
    if (!trimmed || trimmed === 'none') return null;
    return trimmed;
  } catch {
    return null;
  }
}

function tomlString(value) {
  return JSON.stringify(String(value || ''));
}

function codexHomeDir() {
  return process.env.CODEX_HOME || path.join(os.homedir(), '.codex');
}

function codexProfileNameForTab(tabId) {
  const digest = crypto.createHash('sha1').update(String(tabId || 'tab')).digest('hex').slice(0, 12);
  return 'noted-terminal-' + digest;
}

async function writeCodexDeveloperInstructionsProfile(tabId, developerInstructions) {
  const text = String(developerInstructions || '').trim();
  if (!text) return null;
  const profileName = codexProfileNameForTab(tabId);
  const filePath = path.join(codexHomeDir(), profileName + '.config.toml');
  const content = [
    '# Auto-generated by Noted Terminal. Do not edit by hand.',
    '# This profile is per PTY tab and only carries wrapper developer instructions.',
    'developer_instructions = ' + tomlString(text),
    '',
  ].join('\n');
  await fs.promises.mkdir(path.dirname(filePath), { recursive: true });
  await fs.promises.writeFile(filePath, content, 'utf8');
  return profileName;
}

function buildCodexCommand({ command, sessionId, cwd, model, effort, developerInstructions, profile }) {
  const parts = ['command', 'codex', '--no-alt-screen', '--dangerously-bypass-approvals-and-sandbox'];
  if (profile) parts.push('--profile', shellQuote(profile));
  if (model) parts.push('--model', shellQuote(model));
  if (effort) parts.push('-c', shellQuote('model_reasoning_effort="' + effort + '"'));
  if (cwd) parts.push('-C', shellQuote(cwd));
  if (developerInstructions && String(developerInstructions).trim()) {
    parts.push('-c', shellQuote('developer_instructions=' + tomlString(String(developerInstructions).trim())));
  }
  if (command === 'codex-c' && sessionId) parts.push('resume', shellQuote(sessionId));
  if (command === 'codex-f' && sessionId) parts.push('fork', shellQuote(sessionId));
  return parts.join(' ');
}

function cleanCodexTuiFrame(raw) {
  const spaced = String(raw || '').replace(/\x1b\[(\d*)C/g, (_m, n) => ' '.repeat(parseInt(n, 10) || 1));
  const normalized = spaced
    .replace(/\x1b\[\d*[ABD]/g, '')
    .replace(/\x1b\[\d+;\d+H/g, '\n')
    .replace(/\x1b\[\?25[hl]/g, '')
    .replace(/\x1b\[\?2026[hl]/g, '');
  return stripVTControlCharacters(normalized);
}

function clearCodexStartupAutoEnter(tabId, reason = 'clear') {
  const state = codexStartupAutoEnter.get(tabId);
  if (!state) return;
  if (state.timeout) clearTimeout(state.timeout);
  codexStartupAutoEnter.delete(tabId);
  const firedTypes = state.firedTypes ? Array.from(state.firedTypes).join(',') : '';
  console.log('[CodexStartupPrompt] clear tab=' + String(tabId).slice(-12) + ' reason=' + reason + ' fired=' + (!!state.fired || !!firedTypes) + (firedTypes ? ' types=' + firedTypes : ''));
}

function scheduleCodexStartupAutoEnterTimeout(tabId, state, ttlMs) {
  if (state.timeout) clearTimeout(state.timeout);
  state.timeout = setTimeout(() => {
    clearCodexStartupAutoEnter(tabId, 'ttl');
  }, ttlMs);
}

function armCodexStartupAutoEnter(tabId, { command, sessionId, cwd } = {}) {
  if (!tabId) return;
  clearCodexStartupAutoEnter(tabId, 'rearm');
  const normalizedCommand = command || 'codex';
  const allowedPromptTypes = new Set(['update-available', 'trust-directory']);
  if ((normalizedCommand === 'codex-c' || normalizedCommand === 'codex-f') && sessionId) {
    allowedPromptTypes.add('cwd-chooser');
  }
  const ttlMs = allowedPromptTypes.has('cwd-chooser')
    ? CODEX_STARTUP_AUTO_ENTER_TTL_MS
    : CODEX_TRUST_PROMPT_AUTO_ENTER_TTL_MS;
  const state = {
    raw: '',
    command: normalizedCommand,
    sessionId: sessionId || null,
    cwd: cwd || null,
    armedAt: Date.now(),
    allowedPromptTypes,
    firedTypes: new Set(),
    fired: false,
    timeout: null,
  };
  codexStartupAutoEnter.set(tabId, state);
  scheduleCodexStartupAutoEnterTimeout(tabId, state, ttlMs);
  console.log('[CodexStartupPrompt] armed tab=' + String(tabId).slice(-12) +
    ' command=' + (state.command || 'unknown') +
    ' session=' + (state.sessionId ? String(state.sessionId).slice(0, 8) : 'none') +
    ' cwd=' + (state.cwd || 'n/a') +
    ' prompts=' + Array.from(allowedPromptTypes).join(',') +
    ' ttlMs=' + ttlMs);
}

function inspectCodexCwdChooser(cleanText) {
  const text = String(cleanText || '').replace(/\u00a0/g, ' ');
  const compact = text.toLowerCase().replace(/\s+/g, ' ');
  const squashed = compact.replace(/[^a-z0-9]+/g, '');
  const hasPhrase = (phrase) => squashed.includes(String(phrase).toLowerCase().replace(/[^a-z0-9]+/g, ''));
  const hasAny = (phrases) => phrases.some(hasPhrase);
  const firstOptionPattern = /[›❯>]\s*1\.?\s*Use\s+session\s+directory/i;
  const secondOptionPattern = /[›❯>]\s*2\.?\s*Use\s+c\s*u?\s*rrent\s+directory/i;
  const firstOptionSelected = firstOptionPattern.test(text);
  const secondOptionSelected = secondOptionPattern.test(text);
  const sessionOptionVisible = hasPhrase('use session directory') || /1\.?\s*Use\s+session\s+directory/i.test(text);
  const currentOptionVisible = hasPhrase('use current directory')
    || /2\.?\s*Use\s+c\s*u?\s*rrent\s+directory/i.test(text)
    || (hasPhrase('current your current working directory') && /\b2\.?\s*Use\b/i.test(text));
  const checks = {
    chooserTitle: hasAny(['directory to resume this session', 'directory to fork this session']),
    sessionLine: hasAny([
      'session latest cwd recorded in the resumed session',
      'session latest cwd recorded in the forked session',
    ]),
    currentLine: hasPhrase('current your current working directory'),
    sessionOption: sessionOptionVisible,
    currentOption: currentOptionVisible,
    continueHint: hasPhrase('press enter to continue'),
  };
  const missing = Object.entries(checks)
    .filter(([, ok]) => !ok)
    .map(([key]) => key);
  const visible = checks.chooserTitle || (checks.sessionOption && (checks.currentOption || checks.currentLine));
  const action = hasPhrase('directory to fork this session') ? 'fork'
    : hasPhrase('directory to resume this session') ? 'resume'
      : 'unknown';
  const sessionDescriptor = hasPhrase('session latest cwd recorded in the forked session') ? 'forked'
    : hasPhrase('session latest cwd recorded in the resumed session') ? 'resumed'
      : 'unknown';
  const safeDefaultSelected = firstOptionSelected
    && !secondOptionSelected
    && checks.sessionOption
    && (checks.currentOption || checks.currentLine || checks.continueHint);
  const canAutoEnter = visible && safeDefaultSelected;
  let skipReason = null;
  if (visible && secondOptionSelected) skipReason = 'current-directory-selected';
  else if (visible && !firstOptionSelected) skipReason = 'session-directory-not-selected';
  else if (visible && !safeDefaultSelected && missing.length > 0) skipReason = 'missing:' + missing.join(',');
  return {
    visible,
    canAutoEnter,
    action,
    sessionDescriptor,
    firstOptionSelected,
    secondOptionSelected,
    missing,
    skipReason,
  };
}

function isCodexCwdChooser(cleanText) {
  return inspectCodexCwdChooser(cleanText).canAutoEnter;
}

function inspectCodexUpdatePrompt(cleanText) {
  const text = String(cleanText || '').replace(/\u00a0/g, ' ');
  const compact = text.toLowerCase().replace(/\s+/g, ' ');
  const squashed = compact.replace(/[^a-z0-9]+/g, '');
  const hasPhrase = (phrase) => squashed.includes(String(phrase).toLowerCase().replace(/[^a-z0-9]+/g, ''));
  const firstOptionSelected = /[›❯>]\s*1\.\s*Update\s+now/i.test(text);
  const secondOptionSelected = /[›❯>]\s*2\.\s*Skip(?!\s+until)/i.test(text);
  const thirdOptionSelected = /[›❯>]\s*3\.\s*Skip\s+until\s+next\s+version/i.test(text);
  const checks = {
    title: hasPhrase('update available'),
    updateNow: hasPhrase('update now'),
    skip: hasPhrase('skip'),
    skipUntilNext: hasPhrase('skip until next version'),
    continueHint: hasPhrase('press enter to continue'),
    installHint: hasPhrase('run npm install g openai codex to update'),
    releaseNotes: hasPhrase('github com openai codex releases latest') || hasPhrase('see full release notes'),
  };
  const missing = Object.entries(checks)
    .filter(([, ok]) => !ok)
    .map(([key]) => key);
  const interactiveVisible = checks.title && checks.updateNow && checks.skip && checks.skipUntilNext;
  const passiveVisible = checks.title && (checks.installHint || checks.releaseNotes);
  const visible = interactiveVisible || passiveVisible;
  const canAutoSkip = interactiveVisible && checks.continueHint && (firstOptionSelected || secondOptionSelected) && !thirdOptionSelected;
  let skipReason = null;
  if (passiveVisible && !interactiveVisible) skipReason = 'passive-update-banner';
  else if (visible && missing.length > 0) skipReason = 'missing:' + missing.join(',');
  else if (visible && thirdOptionSelected) skipReason = 'skip-until-next-selected';
  else if (visible && !firstOptionSelected && !secondOptionSelected) skipReason = 'skip-option-not-reachable';
  return {
    visible,
    canAutoSkip,
    interactiveVisible,
    passiveVisible,
    firstOptionSelected,
    secondOptionSelected,
    thirdOptionSelected,
    missing,
    skipReason,
  };
}

function isCodexUpdatePrompt(cleanText) {
  return inspectCodexUpdatePrompt(cleanText).canAutoSkip;
}

function isCodexTrustDirectoryPrompt(cleanText) {
  const text = String(cleanText || '').replace(/\u00a0/g, ' ');
  const compact = text.toLowerCase().replace(/\s+/g, ' ');
  const squashed = compact.replace(/[^a-z0-9]+/g, '');
  const hasPhrase = (phrase) => squashed.includes(String(phrase).toLowerCase().replace(/[^a-z0-9]+/g, ''));
  const firstOptionSelected = /[›❯>]\s*1\.\s*Yes\s*,?\s*continue/i.test(text);
  const secondOptionSelected = /[›❯>]\s*2\.\s*No\s*,?\s*quit/i.test(text);
  if (!firstOptionSelected || secondOptionSelected) return false;
  return hasPhrase('do you trust the contents of this directory') &&
    hasPhrase('working with untrusted contents') &&
    hasPhrase('higher risk of prompt injection') &&
    hasPhrase('trusting the directory allows project local config hooks and exec policies to load') &&
    hasPhrase('yes continue') &&
    hasPhrase('no quit');
}

function detectCodexStartupAutoEnterPrompt(cleanText, state) {
  const allowed = state?.allowedPromptTypes || new Set(['cwd-chooser']);
  const fired = state?.firedTypes || new Set();
  if (allowed.has('update-available') && !fired.has('update-available') && isCodexUpdatePrompt(cleanText)) {
    return 'update-available';
  }
  if (allowed.has('trust-directory') && !fired.has('trust-directory') && isCodexTrustDirectoryPrompt(cleanText)) {
    return 'trust-directory';
  }
  if (allowed.has('cwd-chooser') && !fired.has('cwd-chooser') && isCodexCwdChooser(cleanText)) {
    return 'cwd-chooser';
  }
  return null;
}

function tryHandleCodexStartupAutoEnter(tabId, data, options = {}) {
  const state = codexStartupAutoEnter.get(tabId);
  if (!state) return;
  const ageMs = Date.now() - state.armedAt;
  if (ageMs > CODEX_STARTUP_AUTO_ENTER_TTL_MS) {
    clearCodexStartupAutoEnter(tabId, 'expired-on-data');
    return;
  }
  let clean;
  let rawBytes;
  const source = options?.source || 'raw';
  if (typeof options?.cleanSnapshot === 'string') {
    clean = options.cleanSnapshot;
    rawBytes = clean.length;
  } else {
    state.raw += data;
    if (state.raw.length > CODEX_STARTUP_AUTO_ENTER_BUFFER_LIMIT) {
      state.raw = state.raw.slice(-CODEX_STARTUP_AUTO_ENTER_BUFFER_LIMIT);
    }
    clean = cleanCodexTuiFrame(state.raw);
    rawBytes = state.raw.length;
  }
  const promptType = detectCodexStartupAutoEnterPrompt(clean, state);
  if (!promptType && state.allowedPromptTypes?.has('cwd-chooser') && !state.firedTypes?.has('cwd-chooser')) {
    const chooser = inspectCodexCwdChooser(clean);
    if (chooser.visible) {
      const rejectKey = [
        chooser.action,
        chooser.sessionDescriptor,
        chooser.firstOptionSelected ? 'first' : 'first0',
        chooser.secondOptionSelected ? 'second' : 'second0',
        chooser.skipReason || 'unknown',
      ].join(':');
      if (state.lastCwdChooserRejectKey !== rejectKey) {
        state.lastCwdChooserRejectKey = rejectKey;
        const preview = clean.replace(/\s+/g, ' ').trim().slice(0, 260);
        console.log('[CodexStartupPrompt] cwd-chooser visible but not confirmed tab=' + String(tabId).slice(-12) +
          ' command=' + (state.command || 'unknown') +
          ' session=' + (state.sessionId ? String(state.sessionId).slice(0, 8) : 'none') +
          ' source=' + source +
          ' ageMs=' + ageMs +
          ' action=' + chooser.action +
          ' sessionDescriptor=' + chooser.sessionDescriptor +
          ' firstSelected=' + chooser.firstOptionSelected +
          ' secondSelected=' + chooser.secondOptionSelected +
          ' reason=' + (chooser.skipReason || 'unknown') +
          ' preview=' + JSON.stringify(preview));
      }
    }
  }
  if (!promptType && state.allowedPromptTypes?.has('update-available') && !state.firedTypes?.has('update-available')) {
    const updatePrompt = inspectCodexUpdatePrompt(clean);
    if (updatePrompt.visible) {
      const rejectKey = [
        updatePrompt.firstOptionSelected ? 'first' : 'first0',
        updatePrompt.secondOptionSelected ? 'second' : 'second0',
        updatePrompt.thirdOptionSelected ? 'third' : 'third0',
        updatePrompt.skipReason || 'unknown',
      ].join(':');
      if (state.lastUpdatePromptRejectKey !== rejectKey) {
        state.lastUpdatePromptRejectKey = rejectKey;
        const preview = clean.replace(/\s+/g, ' ').trim().slice(0, 260);
        console.log('[CodexStartupPrompt] update prompt visible but not auto-skipped tab=' + String(tabId).slice(-12) +
          ' command=' + (state.command || 'unknown') +
          ' source=' + source +
          ' ageMs=' + ageMs +
          ' firstSelected=' + updatePrompt.firstOptionSelected +
          ' secondSelected=' + updatePrompt.secondOptionSelected +
          ' thirdSelected=' + updatePrompt.thirdOptionSelected +
          ' reason=' + (updatePrompt.skipReason || 'unknown') +
          ' preview=' + JSON.stringify(preview));
      }
    }
  }
  if (!promptType) return;

  state.firedTypes.add(promptType);
  state.fired = true;
  const preview = clean.replace(/\s+/g, ' ').trim().slice(0, 260);
  console.log('[CodexStartupPrompt] detected tab=' + String(tabId).slice(-12) +
    ' command=' + (state.command || 'unknown') +
    ' prompt=' + promptType +
    ' session=' + (state.sessionId ? String(state.sessionId).slice(0, 8) : 'none') +
    ' source=' + source +
    ' ageMs=' + ageMs +
    ' rawBytes=' + rawBytes +
    ' preview=' + JSON.stringify(preview) +
    ' — sending Enter in 120ms');
  setTimeout(() => {
    const current = codexStartupAutoEnter.get(tabId);
    if (current !== state) return;
    const term = terminals.get(tabId);
    let wroteAction = false;
    if (term) {
      if (promptType === 'update-available') {
        const updatePrompt = inspectCodexUpdatePrompt(clean);
        const sequence = updatePrompt.secondOptionSelected ? '\r' : '\x1b[B\r';
        const action = updatePrompt.secondOptionSelected ? 'enter-skip' : 'down-enter-skip';
        console.log('[CodexStartupPrompt] writing ' + action + ' tab=' + String(tabId).slice(-12) + ' prompt=' + promptType);
        term.write(sequence);
      } else {
        console.log('[CodexStartupPrompt] writing Enter tab=' + String(tabId).slice(-12) + ' prompt=' + promptType);
        term.write('\r');
      }
      resetCodexTuiReadyDetection(tabId, 'startup-prompt-' + promptType);
      wroteAction = true;
    } else {
      console.warn('[CodexStartupPrompt] terminal missing before startup prompt action tab=' + String(tabId).slice(-12) + ' prompt=' + promptType);
    }
    if (!wroteAction) {
      clearCodexStartupAutoEnter(tabId, 'terminal-missing-' + promptType);
      return;
    }
    const remainingPromptTypes = Array.from(state.allowedPromptTypes || [])
      .filter(type => !state.firedTypes?.has(type));
    if (remainingPromptTypes.length > 0) {
      state.raw = '';
      state.armedAt = Date.now();
      const nextTtl = remainingPromptTypes.length === 1 && remainingPromptTypes[0] === 'cwd-chooser'
        ? CODEX_POST_TRUST_AUTO_ENTER_TTL_MS
        : CODEX_TRUST_PROMPT_AUTO_ENTER_TTL_MS;
      scheduleCodexStartupAutoEnterTimeout(tabId, state, nextTtl);
      console.log('[CodexStartupPrompt] keep armed tab=' + String(tabId).slice(-12) + ' reason=await-' + remainingPromptTypes.join(',') + ' ttlMs=' + nextTtl);
      return;
    }
    clearCodexStartupAutoEnter(tabId, 'confirmed-' + promptType);
  }, 120);
}

function normalizeCodexPickerValue(value) {
  return String(value || '')
    .toLowerCase()
    .replace(/\(current\)/g, '')
    .replace(/[^\w.-]+/g, ' ')
    .trim();
}

function codexCandidateAliases(candidate) {
  const normalized = normalizeCodexPickerValue(candidate);
  if (normalized === 'xhigh') return ['xhigh', 'x high', 'x-high', 'extra high', 'extra-high'];
  if (normalized === 'medium') return ['medium', 'med'];
  if (normalized === 'minimal') return ['minimal', 'minimum'];
  return [normalized];
}

function codexLineContainsCandidate(line, candidate) {
  const haystack = ' ' + normalizeCodexPickerValue(line) + ' ';
  const aliases = codexCandidateAliases(candidate);
  return aliases.some((needle) => {
    if (!needle) return false;
    const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
    return new RegExp('(^|[^a-z0-9_.-])' + escaped + '($|[^a-z0-9_.-])', 'i').test(haystack);
  });
}

function parseCodexNumberedPicker(cleanText, candidates = null) {
  const lines = String(cleanText || '').split(/[\r\n]+/).map(l => l.trim()).filter(Boolean);
  const items = [];
  const isNumberedPickerLine = (value) => {
    const bareValue = String(value || '').replace(/^[›❯>]\s*/, '').trim();
    return /^\d+\.\s*/.test(bareValue);
  };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const selected = /^[›❯>]\s*/.test(line);
    const bare = line.replace(/^[›❯>]\s*/, '').trim();
    const match = bare.match(/^(\d+)\.\s*(.*)$/);
    if (!match) continue;
    let rest = match[2].trim();
    // Codex may render narrow picker rows as:
    //   2.
    //   gpt-5.4
    //   Strong model...
    // or:
    //   4.
    //   Extra
    //   high
    //   Extra high reasoning depth...
    // Build a short label window from following non-numbered lines; candidate
    // matching uses the window, while display falls back to the first label.
    if (!rest && i + 1 < lines.length) {
      rest = lines[i + 1].replace(/^[›❯>]\s*/, '').trim();
    }
    if (!rest) continue;
    const labelParts = [rest];
    for (let j = i + 1; j < lines.length && labelParts.length < 4; j++) {
      if (isNumberedPickerLine(lines[j])) break;
      const part = lines[j].replace(/^[›❯>]\s*/, '').trim();
      if (part && part !== rest) labelParts.push(part);
    }
    const labelWindow = labelParts.join(' ');
    let value = null;
    if (Array.isArray(candidates) && candidates.length > 0) {
      const found = candidates.find(c => codexLineContainsCandidate(labelWindow, c));
      if (!found) continue;
      value = found;
    } else {
      const valueMatch = rest.match(/^([^\s(]+)/);
      value = valueMatch ? valueMatch[1] : rest;
    }
    items.push({
      ordinal: Number(match[1]),
      index: items.length,
      selected,
      value,
      label: labelWindow,
      line,
    });
  }
  return {
    items,
    selectedIndex: items.findIndex(item => item.selected),
  };
}

function captureCodexFrame(term, { timeoutMs = 3000, predicate = null, logPrefix = '[Codex:Picker]', settleMs = 0 } = {}) {
  return new Promise((resolve) => {
    let raw = '';
    let resolved = false;
    let sub = null;
    let timer = null;
    let quietTimer = null;
    let firstFrameLogged = false;
    let predicateSeen = false;
    const traceRewind = String(logPrefix || '').includes('Codex:Rewind');
    const finish = (timedOut) => {
      if (resolved) return;
      resolved = true;
      if (timer) clearTimeout(timer);
      if (quietTimer) clearTimeout(quietTimer);
      try { sub?.dispose?.(); } catch {}
      const clean = cleanCodexTuiFrame(raw);
      if (traceRewind) {
        console.log(logPrefix + ' capture finish timedOut=' + timedOut
          + ' raw=' + raw.length + 'B clean=' + JSON.stringify(clean.slice(0, 260)));
      }
      resolve({ raw, clean, timedOut });
    };
    const finishAfterQuiet = () => {
      if (quietTimer) clearTimeout(quietTimer);
      quietTimer = setTimeout(() => finish(false), Math.max(0, Number(settleMs || 0)));
    };
    timer = setTimeout(() => {
      console.log(logPrefix + ' capture timeout (' + timeoutMs + 'ms), raw=' + raw.length + 'B');
      finish(true);
    }, timeoutMs);
    sub = term.onData((data) => {
      raw += data;
      if (traceRewind && !firstFrameLogged) {
        firstFrameLogged = true;
        const clean = cleanCodexTuiFrame(raw);
        console.log(logPrefix + ' first frame chunk=' + String(data || '').length
          + 'B raw=' + raw.length + 'B clean=' + JSON.stringify(clean.slice(0, 220)));
      }
      if (!predicate) {
        if (quietTimer) clearTimeout(quietTimer);
        quietTimer = setTimeout(() => finish(false), 250);
      }
      const clean = cleanCodexTuiFrame(raw);
      if (predicate && predicate(clean, raw)) {
        if (traceRewind && !predicateSeen) {
          console.log(logPrefix + ' predicate matched raw=' + raw.length
            + 'B clean=' + JSON.stringify(clean.slice(0, 220)));
        }
        predicateSeen = true;
        if (settleMs > 0) {
          finishAfterQuiet();
          return;
        }
        finish(false);
        return;
      }
      if (!predicate && raw.includes(CODEX_SYNC_MARKER)) {
        finish(false);
      }
    });
  });
}

async function sendCodexKeyAndCapture(term, key, timeoutMs = 2500, logPrefix = '[Codex:Picker]', predicate = null) {
  const traceRewind = String(logPrefix || '').includes('Codex:Rewind');
  const capture = captureCodexFrame(term, {
    timeoutMs,
    logPrefix,
    predicate,
    settleMs: traceRewind && predicate ? 80 : 0,
  });
  if (String(logPrefix || '').includes('Codex:Rewind')) {
    const keyLabel = key === '\x1b'
      ? 'Esc'
      : key === '\r'
        ? 'Enter'
        : key === '\x1b[D'
          ? 'Left'
          : key === '\x1b[C'
            ? 'Right'
            : JSON.stringify(key);
    console.log(logPrefix + ' writing key=' + keyLabel + ' bytes=' + String(key || '').length);
  }
  term.write(key);
  return await capture;
}

async function sendCodexSlashCommand(term, command, logPrefix = '[Codex:Picker]', options = {}) {
  const text = String(command || '').trim();
  if (!text.startsWith('/')) {
    return { success: false, error: 'Codex command must start with /' };
  }
  const {
    clearStrategy = 'line',
    waitForSubmitFrame = false,
    submitTimeoutMs = 2500,
    submitPredicate = null,
  } = options;
  const t0 = Date.now();
  // Codex behaves like other Ink-style TUIs here: if text and Enter arrive in
  // the same raw write, Enter can be interpreted as a newline in the composer.
  // Use bracketed paste for the short slash command, then wait until the next
  // PTY frame either echoes the command or closes a synchronized TUI render.
  // Both are deterministic "Codex has ingested the input" signals; timeout is
  // only the error path.
  const inputFrame = captureCodexFrame(term, {
    timeoutMs: 2500,
    logPrefix: logPrefix + ':slash-input',
    predicate: (clean, raw) => clean.includes(text) || raw.includes(CODEX_SYNC_MARKER),
  });
  const clearPrefix = clearStrategy === 'line' ? '\x01\x0b' : '';
  term.write(clearPrefix + PASTE_START + text + PASTE_END);
  const frame = await inputFrame;
  if (frame.timedOut) {
    console.warn(logPrefix + ' slash input frame timed out for ' + JSON.stringify(text) + ' clean=' + JSON.stringify(frame.clean.slice(0, 500)));
    return { success: false, error: 'Codex slash input frame timed out', submitted: false };
  }
  const submitFramePromise = waitForSubmitFrame
    ? captureCodexFrame(term, {
      timeoutMs: submitTimeoutMs,
      logPrefix: logPrefix + ':slash-submit',
      predicate: submitPredicate,
    })
    : null;
  term.write('\r');
  if (submitFramePromise) {
    const submitFrame = await submitFramePromise;
    console.log(logPrefix + ' submit frame timedOut=' + submitFrame.timedOut + ' clean=' + JSON.stringify(submitFrame.clean.slice(0, 240)));
    if (submitFrame.timedOut) {
      return {
        success: false,
        error: 'Codex slash submit frame timed out',
        submitted: true,
        submitClean: submitFrame.clean,
      };
    }
    console.log(logPrefix + ' submit frame confirmed clean=' + JSON.stringify(submitFrame.clean.slice(0, 240)));
    const result = { success: true, submitted: true, submitClean: submitFrame.clean };
    const serviceTier = parseCodexServiceTierFeedback(submitFrame.clean);
    if (serviceTier) Object.assign(result, serviceTier);
    return result;
  }
  console.log(logPrefix + ' sent slash command ' + JSON.stringify(text) + ' after render +' + (Date.now() - t0) + 'ms');
  return { success: true, submitted: true };
}

function parseCodexServiceTierFeedback(text) {
  const match = String(text || '').replace(/\s+/g, ' ').match(/Service tier set to\s+(priority|default)/i);
  if (!match) return null;
  const serviceTier = match[1].toLowerCase();
  return {
    serviceTier,
    notice: serviceTier === 'priority' ? 'Fast applied' : 'Default applied',
    serviceTierSource: 'tui',
  };
}

async function moveCodexPickerTo(term, state, targetIndex, logPrefix) {
  let selectedIndex = state.selectedIndex;
  if (selectedIndex < 0) selectedIndex = 0;
  const delta = targetIndex - selectedIndex;
  if (delta === 0) return { success: true, pressCount: 0 };
  const key = delta > 0 ? '\x1b[B' : '\x1b[A';
  const dir = delta > 0 ? 'DOWN' : 'UP';
  const pressCount = Math.abs(delta);
  console.log(logPrefix + ' navigate ' + dir + ' x' + pressCount + ' from=' + selectedIndex + ' to=' + targetIndex);
  for (let i = 0; i < pressCount; i++) {
    const frame = await sendCodexKeyAndCapture(term, key, 2500, logPrefix + ':' + dir + '#' + (i + 1));
    if (frame.timedOut) {
      console.warn(logPrefix + ' navigation frame timed out at step ' + (i + 1) + '/' + pressCount);
      return { success: false, error: 'Codex picker navigation frame timed out', pressCount: i };
    }
  }
  return { success: true, pressCount };
}

async function selectCodexPickerItem(term, {
  kind,
  target,
  candidates = null,
  initialFrame,
  timeoutMs = 3000,
  confirmPredicate = null,
  logPrefix = '[Codex:Picker]',
}) {
  const state = parseCodexNumberedPicker(initialFrame.clean, candidates);
  console.log(logPrefix + ' ' + kind + ' items=' + state.items.map(item => (item.selected ? '>' : '') + item.value).join(', ') + ' selected=' + state.selectedIndex + ' target=' + target);

  if (state.items.length === 0) {
    return { success: false, error: 'No Codex ' + kind + ' options found', clean: initialFrame.clean };
  }
  const targetIndex = state.items.findIndex(item => normalizeCodexPickerValue(item.value) === normalizeCodexPickerValue(target));
  if (targetIndex < 0) {
    console.warn(logPrefix + ' ' + kind + ' option not found: ' + target + ' clean=' + JSON.stringify(initialFrame.clean.slice(0, 1200)));
    try { term.write('\x1b'); } catch {}
    return {
      success: false,
      error: 'Codex ' + kind + ' option not found: ' + target,
      options: state.items.map(item => item.value),
      clean: initialFrame.clean,
    };
  }

  const moveResult = await moveCodexPickerTo(term, state, targetIndex, logPrefix + ':' + kind);
  if (!moveResult.success) {
    return {
      success: false,
      error: moveResult.error || 'Codex picker navigation failed',
      options: state.items.map(item => item.value),
      clean: initialFrame.clean,
    };
  }
  const confirmFrame = await sendCodexKeyAndCapture(term, '\r', timeoutMs, logPrefix + ':' + kind + ':confirm', confirmPredicate);
  if (confirmFrame.timedOut) {
    return {
      success: false,
      error: 'Codex ' + kind + ' confirm frame timed out',
      selected: state.items[targetIndex].value,
      frame: confirmFrame,
      options: state.items.map(item => item.value),
    };
  }
  return {
    success: true,
    selected: state.items[targetIndex].value,
    frame: confirmFrame,
    options: state.items.map(item => item.value),
  };
}

async function stashCodexDraftForPicker(term, { logPrefix, draftPreview = '' } = {}) {
  const preview = String(draftPreview || '').slice(0, 80);
  console.log(logPrefix + ' draft-stash start preview=' + JSON.stringify(preview));
  try {
    const frame = await sendCodexKeyAndCapture(
      term,
      '\x03',
      1800,
      logPrefix + ':draft-stash',
      (clean, raw) => {
        if (raw.includes(CODEX_SYNC_MARKER)) return true;
        if (preview && clean.includes(preview)) return false;
        return /[›❯]\s*(Find and fix a bug|Explain this codebase)?/i.test(clean)
          || /Context\s+\d+%/i.test(clean);
      }
    );
    console.log(logPrefix + ' draft-stash ' + (frame.timedOut ? 'timeout' : 'frame') + ' clean=' + JSON.stringify(frame.clean.slice(0, 240)));
    return { success: !frame.timedOut, frame };
  } catch (error) {
    console.warn(logPrefix + ' draft-stash error: ' + (error?.message || String(error)));
    return { success: false, error: error?.message || String(error) };
  }
}

async function restoreCodexDraftAfterPicker(term, { logPrefix, slashSubmitted = false, expectedPreview = '' } = {}) {
  const presses = slashSubmitted ? 2 : 1;
  console.log(logPrefix + ' draft-restore start arrowUp=' + presses + ' slashSubmitted=' + slashSubmitted);
  let lastFrame = null;
  for (let i = 0; i < presses; i++) {
    try {
      const frame = await sendCodexKeyAndCapture(
        term,
        '\x1b[A',
        1600,
        logPrefix + ':draft-restore#' + (i + 1)
      );
      lastFrame = frame;
      console.log(logPrefix + ' draft-restore step=' + (i + 1) + '/' + presses + ' timedOut=' + frame.timedOut + ' clean=' + JSON.stringify(frame.clean.slice(0, 240)));
    } catch (error) {
      console.warn(logPrefix + ' draft-restore step=' + (i + 1) + ' error: ' + (error?.message || String(error)));
      break;
    }
  }
  const normalize = (value) => String(value || '').replace(/\s+/g, ' ').trim();
  const expected = normalize(expectedPreview);
  const actual = normalize(lastFrame?.clean || '');
  const expectedPrefix = expected.slice(0, 32);
  const matched = !expectedPrefix || actual.includes(expectedPrefix);
  console.log(logPrefix + ' draft-restore verify expectedPrefix=' + JSON.stringify(expectedPrefix) + ' matched=' + matched + ' actual=' + JSON.stringify(actual.slice(0, 240)));
}

async function selectCodexModelEffort(term, {
  tabId,
  model,
  effort,
  hasDraft = null,
  draftSource = '',
  draftPreview = '',
  visualHasDraft = null,
  visualSource = '',
  visualPreview = '',
}) {
  const logPrefix = '[Codex:Picker:' + tabId + ']';
  const t0 = Date.now();
  console.log(logPrefix + ' start model=' + model + ' effort=' + (effort || 'skip') + ' hasDraft=' + hasDraft + ' draftSource=' + (draftSource || 'n/a') + ' draftPreview=' + JSON.stringify(String(draftPreview || '').slice(0, 120)) + ' visualHasDraft=' + visualHasDraft + ' visualSource=' + (visualSource || 'n/a') + ' visualPreview=' + JSON.stringify(String(visualPreview || '').slice(0, 120)));

  const shouldRestoreDraft = hasDraft === true;
  let slashSubmitted = false;
  let outcome = null;

  if (hasDraft !== false && hasDraft !== true) {
    return { success: false, error: 'Cannot determine Codex input state safely' };
  }

  if (shouldRestoreDraft) {
    const stashResult = await stashCodexDraftForPicker(term, { logPrefix, draftPreview });
    if (!stashResult.success) {
      return {
        success: false,
        error: 'Codex draft stash did not confirm prompt state safely',
        draftSource,
        draftPreview,
      };
    }
  } else {
    console.log(logPrefix + ' skip Ctrl+C draft clear; picker only runs after empty-composer probe');
  }

  try {
    const openCapture = captureCodexFrame(term, {
      timeoutMs: 6000,
      logPrefix: logPrefix + ':open',
      predicate: (clean) => {
        if (!/Select Model/i.test(clean)) return false;
        const state = parseCodexNumberedPicker(clean);
        if (state.items.length < 2) return false;
        const hasTarget = state.items.some(item => codexLineContainsCandidate(item.label || item.value, model));
        return hasTarget || state.items.length >= 4;
      },
    });
    const slashResult = await sendCodexSlashCommand(term, '/model', logPrefix + ':open-command', {
      clearStrategy: 'line',
    });
    if (!slashResult.success) {
      outcome = slashResult;
      return slashResult;
    }
    slashSubmitted = true;
    const modelFrame = await openCapture;
    if (modelFrame.timedOut) {
      console.warn(logPrefix + ' model menu capture timed out. clean=' + JSON.stringify(modelFrame.clean.slice(0, 500)));
      outcome = { success: false, error: 'Codex model menu capture timed out', clean: modelFrame.clean };
      return outcome;
    }

    // xhigh must be checked before high: Codex renders it as "Extra high".
    const effortCandidates = CODEX_PICKER_EFFORT_CANDIDATES;
    const effortPredicate = effort
      ? (clean) => parseCodexNumberedPicker(clean, effortCandidates).items.length > 0
      : null;
    const modelResult = await selectCodexPickerItem(term, {
      kind: 'model',
      target: model,
      initialFrame: modelFrame,
      timeoutMs: 5000,
      confirmPredicate: effortPredicate,
      logPrefix,
    });
    if (!modelResult.success) {
      outcome = modelResult;
      return modelResult;
    }

    let effortResult = null;
    let parsedEffortOptions = [];
    if (effort) {
      let effortFrame = modelResult.frame;
      let effortState = parseCodexNumberedPicker(effortFrame.clean, effortCandidates);
      if (effortState.items.length === 0) {
        const lateFrame = await captureCodexFrame(term, {
          timeoutMs: 2500,
          logPrefix: logPrefix + ':effort-late',
          predicate: effortPredicate,
        });
        const lateState = parseCodexNumberedPicker(lateFrame.clean, effortCandidates);
        if (lateState.items.length > 0) {
          effortFrame = lateFrame;
          effortState = lateState;
        }
      }
      if (effortState.items.length > 0) {
        parsedEffortOptions = effortState.items.map(item => item.value);
        effortResult = await selectCodexPickerItem(term, {
          kind: 'effort',
          target: effort,
          candidates: effortCandidates,
          initialFrame: effortFrame,
          timeoutMs: 5000,
          logPrefix,
        });
        if (!effortResult.success) {
          outcome = effortResult;
          return effortResult;
        }
      } else {
        console.log(logPrefix + ' no effort picker after model confirm; clean=' + JSON.stringify(effortFrame.clean.slice(0, 500)));
        outcome = {
          success: false,
          error: 'Codex effort picker did not appear after model selection',
          model: modelResult.selected,
          modelOptions: modelResult.options,
          effortOptions: parsedEffortOptions,
        };
        return outcome;
      }
    }

    console.log(logPrefix + ' done in ' + (Date.now() - t0) + 'ms model=' + modelResult.selected + ' effort=' + (effortResult?.selected || 'skipped'));
    outcome = {
      success: true,
      model: modelResult.selected,
      effort: effortResult?.selected || null,
      modelOptions: modelResult.options,
      effortOptions: effortResult?.options || parsedEffortOptions,
      effortSkipped: !!effort && !effortResult,
    };
    return outcome;
  } finally {
    if (shouldRestoreDraft) {
      if (slashSubmitted && outcome?.success !== true) {
        try { term.write('\x1b'); } catch {}
      }
      await restoreCodexDraftAfterPicker(term, { logPrefix, slashSubmitted, expectedPreview: draftPreview });
    }
  }
}

async function sendCodexLiveSlashCommand(term, {
  tabId,
  command,
  hasDraft = null,
  draftSource = '',
  draftPreview = '',
  visualHasDraft = null,
  visualSource = '',
  visualPreview = '',
  turnBusy = false,
}) {
  const logPrefix = '[Codex:Slash:' + tabId + ']';
  const text = String(command || '').trim();
  const liveTurnBusy = codexTurnWatchers.get(tabId)?.busy === true;
  const effectiveTurnBusy = turnBusy === true || liveTurnBusy;
  console.log(logPrefix + ' start command=' + JSON.stringify(text) + ' hasDraft=' + hasDraft + ' draftSource=' + (draftSource || 'n/a') + ' draftPreview=' + JSON.stringify(String(draftPreview || '').slice(0, 120)) + ' visualHasDraft=' + visualHasDraft + ' visualSource=' + (visualSource || 'n/a') + ' visualPreview=' + JSON.stringify(String(visualPreview || '').slice(0, 120)) + ' turnBusy=' + turnBusy + ' liveTurnBusy=' + liveTurnBusy);

  if (!text.startsWith('/')) {
    return { success: false, error: 'Codex command must start with /' };
  }
  if (hasDraft !== false && hasDraft !== true) {
    return { success: false, error: 'Cannot determine Codex input state safely' };
  }
  if (effectiveTurnBusy && hasDraft === true) {
    return {
      success: false,
      error: 'Cannot stash Codex draft during active turn safely',
      code: 'busy_draft_unsafe',
      draftSource,
      draftPreview,
    };
  }

  const shouldRestoreDraft = hasDraft === true;
  let slashSubmitted = false;

  if (shouldRestoreDraft) {
    const stashResult = await stashCodexDraftForPicker(term, { logPrefix, draftPreview });
    if (!stashResult.success) {
      return {
        success: false,
        error: 'Codex draft stash did not confirm prompt state safely',
        draftSource,
        draftPreview,
      };
    }
  } else {
    console.log(logPrefix + ' skip Ctrl+C draft clear; slash command only runs after empty-composer probe');
  }

  try {
    const isFastCommand = /^\/fast(?:\s|$)/i.test(text);
    const slashResult = await sendCodexSlashCommand(term, text, logPrefix + ':command', {
      clearStrategy: 'line',
      waitForSubmitFrame: shouldRestoreDraft || isFastCommand,
      submitTimeoutMs: isFastCommand ? 3500 : 2500,
      submitPredicate: isFastCommand
        ? (clean) => !!parseCodexServiceTierFeedback(clean)
        : null,
    });
    if (slashResult.submitted === true) {
      slashSubmitted = true;
    }
    if (!slashResult.success) {
      return slashResult;
    }
    console.log(logPrefix + ' done command=' + JSON.stringify(text));
    return slashResult;
  } finally {
    if (shouldRestoreDraft) {
      await restoreCodexDraftAfterPicker(term, { logPrefix, slashSubmitted, expectedPreview: draftPreview });
    }
  }
}

// Gemini Sniper Watcher: watch for new session file creation when gemini starts
// IMPORTANT: Gemini creates session file only AFTER first user message, not at startup!
// Session files are stored in ~/.gemini/tmp/<SHA256_HASH>/chats/session-<datetime>-<id>.json
ipcMain.on('gemini:spawn-with-watcher', (event, { tabId, cwd, resumeSessionId, bareResume, yesMode }) => {
  console.log('[Gemini Sniper] ========================================');
  console.log('[Gemini Sniper] IPC received: gemini:spawn-with-watcher');
  console.log('[Gemini Sniper] TabId:', tabId);
  console.log('[Gemini Sniper] CWD from renderer:', cwd);
  geminiActiveTabs.add(tabId);

  // Close any existing watcher for this tab
  if (geminiWatchers.has(tabId)) {
    console.log('[Gemini Sniper] Closing existing watcher for tab');
    const oldWatcher = geminiWatchers.get(tabId);
    try { oldWatcher.close(); } catch (e) {}
    geminiWatchers.delete(tabId);
  }

  // Resolve project directory: slug (v0.30+) → hash (legacy) fallback
  const normalizedCwd = path.resolve(cwd || os.homedir());
  invalidateProjectsJsonCache(); // Fresh read — Gemini may have just created the mapping
  let resolved = resolveGeminiProjectDir(normalizedCwd);
  let chatsDir = resolved ? resolved.chatsDir : null;

  // If no existing dir found, predict slug-based path (Gemini 0.30+ will create it on first message)
  if (!chatsDir) {
    const { getGeminiProjectsJson, calculateGeminiHash } = require(path.join(srcMainDir, 'gemini-utils'));
    const pj = getGeminiProjectsJson();
    const slug = pj?.projects?.[normalizedCwd];
    if (slug) {
      chatsDir = path.join(os.homedir(), '.gemini', 'tmp', slug, 'chats');
    } else {
      // Hash fallback for projects not yet in projects.json
      const dirHash = calculateGeminiHash(normalizedCwd);
      chatsDir = path.join(os.homedir(), '.gemini', 'tmp', dirHash, 'chats');
    }
  }

  console.log('[Gemini Sniper] Normalized CWD:', normalizedCwd);
  console.log('[Gemini Sniper] Resolved method:', resolved ? resolved.method : 'predicted');
  console.log('[Gemini Sniper] Watching directory:', chatsDir);

  // Snapshot existing files — we will IGNORE change events on these (only accept rename = new file)
  const existingFilesSet = new Set();
  try {
    if (fs.existsSync(chatsDir)) {
      const existingFiles = fs.readdirSync(chatsDir);
      for (const f of existingFiles) existingFilesSet.add(f);
      console.log('[Gemini Sniper] Existing files:', existingFilesSet.size);
    } else {
      console.log('[Gemini Sniper] Chats dir does not exist yet');
    }
  } catch (e) {
    console.log('[Gemini Sniper] Could not list chats dir:', e.message);
  }

  const startTime = Date.now();
  let watcher = null;
  let sessionFound = false;

  const closeWatcher = () => {
    if (watcher) {
      try { watcher.close(); } catch (e) {}
      watcher = null;
      geminiWatchers.delete(tabId);
      console.log('[Gemini Sniper] Watcher closed for tab:', tabId);
    }
  };

  try {
    // Ensure directory exists (Gemini may create it)
    if (!fs.existsSync(chatsDir)) {
      console.log('[Gemini Sniper] Creating chats directory');
      fs.mkdirSync(chatsDir, { recursive: true });
    }

    console.log('[Gemini Sniper] Setting up fs.watch (no timeout - waits for first message)...');
    watcher = fs.watch(chatsDir, (eventType, filename) => {
      if (sessionFound) return;

      // Gemini session files: session-2026-01-22T22-19-788e351c.json
      if (!filename || !filename.startsWith('session-') || !filename.endsWith('.json')) return;

      console.log('[Gemini Sniper] Session file event:', eventType, filename);

      // CRITICAL: Ignore 'change' events on files that existed BEFORE we started watching.
      // Gemini may touch/update old session files on startup (indexing, migration).
      // Only 'rename' (= new file creation) is valid for pre-existing files.
      if (eventType === 'change' && existingFilesSet.has(filename)) {
        console.log('[Gemini Sniper] Ignoring change on pre-existing file:', filename);
        return;
      }

      const filePath = path.join(chatsDir, filename);

      // Check if file is fresh (created after our start time)
      fs.stat(filePath, (err, stats) => {
        if (err || sessionFound) return;

        // For rename events (new file): check mtime or birthtime
        // For change events on NEW files: also check mtime
        const fileTime = Math.max(stats.mtimeMs, stats.birthtimeMs || 0);
        if (fileTime >= startTime - 500) {
          sessionFound = true;
          console.log('[Gemini Sniper] New session file detected! (event=' + eventType + ')');

          // Read the file to get the full sessionId
          try {
            const content = fs.readFileSync(filePath, 'utf-8');
            const data = JSON.parse(content);
            const sessionId = data.sessionId;

            console.log('[Gemini Sniper] ✅ SUCCESS! Session:', sessionId);
            event.sender.send('gemini:session-detected', { tabId, sessionId });
          } catch (parseErr) {
            // Fallback: extract short ID from filename
            const match = filename.match(/session-.*-([a-f0-9]{8})\.json$/i);
            if (match) {
              console.log('[Gemini Sniper] ✅ Using short ID:', match[1]);
              event.sender.send('gemini:session-detected', { tabId, sessionId: match[1] });
            }
          }
          closeWatcher();
        }
      });
    });

    // Store watcher in map so it can be closed when tab closes
    geminiWatchers.set(tabId, watcher);
    console.log('[Gemini Sniper] fs.watch active (will wait for first Gemini message)');

    // 2s re-check: Gemini may create slug mapping after start — switch watcher if needed
    if (!resolved) {
      setTimeout(() => {
        if (sessionFound || !geminiWatchers.has(tabId)) return;
        invalidateProjectsJsonCache();
        const newResolved = resolveGeminiProjectDir(normalizedCwd);
        if (newResolved && newResolved.chatsDir !== chatsDir) {
          console.log('[Gemini Sniper] Re-check: slug dir appeared, switching watcher →', newResolved.chatsDir);
          closeWatcher();
          chatsDir = newResolved.chatsDir;
          // Re-create watcher on new dir (recursive re-entry via IPC)
          event.sender.send('gemini:watcher-redirect', { tabId, newChatsDir: chatsDir });
          // Note: the watcher restart is handled by re-setting up fs.watch below
          if (!fs.existsSync(chatsDir)) fs.mkdirSync(chatsDir, { recursive: true });
          // Snapshot existing files in new dir
          const recheckExisting = new Set();
          try { for (const f of fs.readdirSync(chatsDir)) recheckExisting.add(f); } catch {}
          watcher = fs.watch(chatsDir, (eventType, filename) => {
            if (sessionFound) return;
            if (!filename || !filename.startsWith('session-') || !filename.endsWith('.json')) return;
            if (eventType === 'change' && recheckExisting.has(filename)) return; // ignore old files
            const filePath = path.join(chatsDir, filename);
            fs.stat(filePath, (err, stats) => {
              if (err || sessionFound) return;
              const fileTime = Math.max(stats.mtimeMs, stats.birthtimeMs || 0);
              if (fileTime >= startTime - 500) {
                sessionFound = true;
                try {
                  const content = fs.readFileSync(filePath, 'utf-8');
                  const data = JSON.parse(content);
                  console.log('[Gemini Sniper] ✅ SUCCESS (re-check)! Session:', data.sessionId);
                  event.sender.send('gemini:session-detected', { tabId, sessionId: data.sessionId });
                } catch (parseErr) {
                  const match = filename.match(/session-.*-([a-f0-9]{8})\.json$/i);
                  if (match) event.sender.send('gemini:session-detected', { tabId, sessionId: match[1] });
                }
                closeWatcher();
              }
            });
          });
          geminiWatchers.set(tabId, watcher);
        }
      }, 2000);
    }

    // Safety timeout: 5 minutes (user might take a while to send first message)
    setTimeout(() => {
      if (!sessionFound && geminiWatchers.has(tabId)) {
        console.log('[Gemini Sniper] ⏱️ 5 min timeout - closing watcher');
        closeWatcher();
      }
    }, 5 * 60 * 1000);

  } catch (e) {
    console.error('[Gemini Sniper] ❌ Error setting up watcher:', e.message);
  }

  // Let the command through - write 'gemini' (or 'gemini -r <id>') to PTY
  const term = terminals.get(tabId);
  if (term) {
    if (resumeSessionId) {
      const cmd = yesMode ? 'gemini -y -r ' + resumeSessionId : 'gemini -r ' + resumeSessionId;
      console.log('[Gemini Sniper] Writing "' + cmd + '" to terminal');
      term.write(cmd + '\r');
      // For prefilled sessions, emit session-detected immediately (file already exists)
      sessionFound = true;
      event.sender.send('gemini:session-detected', { tabId, sessionId: resumeSessionId });
      closeWatcher();
    } else if (bareResume) {
      console.log('[Gemini Sniper] Writing "gemini -r" to terminal (bare resume)');
      term.write('gemini -r\r');
      // Bare "gemini -r" resumes latest session — find it by mtime (no new file created)
      closeWatcher(); // Don't need fs.watch, file already exists
      sessionFound = true;
      try {
        const chatFiles = fs.readdirSync(chatsDir)
          .filter(f => f.startsWith('session-') && f.endsWith('.json'))
          .map(f => ({ name: f, mtime: fs.statSync(path.join(chatsDir, f)).mtimeMs }))
          .sort((a, b) => b.mtime - a.mtime);
        if (chatFiles.length > 0) {
          const latestFile = path.join(chatsDir, chatFiles[0].name);
          const data = JSON.parse(fs.readFileSync(latestFile, 'utf-8'));
          console.log('[Gemini Sniper] ✅ Bare resume → latest session:', data.sessionId, '(' + chatFiles[0].name + ')');
          event.sender.send('gemini:session-detected', { tabId, sessionId: data.sessionId });
        } else {
          console.log('[Gemini Sniper] ⚠️ No session files found for bare resume');
        }
      } catch (e) {
        console.error('[Gemini Sniper] ❌ Error finding latest session:', e.message);
      }
    } else if (yesMode) {
      console.log('[Gemini Sniper] Writing "gemini -y" to terminal (auto-approve)');
      term.write('gemini -y\r');
    } else {
      console.log('[Gemini Sniper] Writing "gemini" to terminal');
      term.write('gemini\r');
    }
  } else {
    console.log('[Gemini Sniper] ❌ Terminal not found for tabId:', tabId);
  }
});

// Close Gemini watcher when tab closes
ipcMain.on('gemini:close-watcher', (event, { tabId }) => {
  if (geminiWatchers.has(tabId)) {
    console.log('[Gemini Sniper] Closing watcher for closed tab:', tabId);
    const watcher = geminiWatchers.get(tabId);
    try { watcher.close(); } catch (e) {}
    geminiWatchers.delete(tabId);
  }
});

// Gemini run command: execute gemini commands (gemini-c, gemini-f)
ipcMain.on('gemini:run-command', (event, { tabId, command, sessionId, cwd }) => {
  const term = terminals.get(tabId);
  if (!term) {
    console.error('[Gemini] Terminal not found:', tabId);
    return;
  }

  // Get cwd from terminalProjects if not provided
  const termCwd = cwd || terminalProjects.get(tabId);
  console.log('[Gemini] Running command:', command, 'sessionId:', sessionId, 'cwd:', termCwd);

  // Ensure spinner detection works for all Gemini commands (continue, fork, etc.)
  geminiActiveTabs.add(tabId);

  switch (command) {
    case 'gemini':
      // New session - handled by spawn-with-watcher
      break;

    case 'gemini-c':
      // Continue session (same session)
      if (sessionId) {
        term.write(`gemini -r ${sessionId}\r`);
      } else {
        console.error('[Gemini] No sessionId for gemini-c');
      }
      break;

    case 'gemini-f':
      // TRUE FORK: copy session file with new UUID
      if (!sessionId) {
        console.error('[Gemini] No sessionId for gemini-f');
        return;
      }

      console.log('[Gemini Fork] ========================================');
      console.log('[Gemini Fork] Source sessionId:', sessionId);

      try {
        // Resolve project directory: slug (v0.30+) → hash (legacy) fallback
        const resolved = resolveGeminiProjectDir(termCwd || os.homedir());
        if (!resolved) {
          console.error('[Gemini Fork] Chats directory not found');
          term.write(`echo "❌ Gemini chats directory not found"\r`);
          return;
        }
        const chatsDir = resolved.chatsDir;
        console.log('[Gemini Fork] Chats dir:', chatsDir, '(method:', resolved.method + ')');

        // Find source session file
        const found = findGeminiSessionFile(sessionId, chatsDir);
        if (!found) {
          console.error('[Gemini Fork] Source session not found:', sessionId);
          term.write(`echo "❌ Session not found: ${sessionId}"\r`);
          return;
        }
        const sourceFile = found.filePath;
        const sourceData = found.data;
        console.log('[Gemini Fork] ✓ Found source file:', path.basename(sourceFile));

        // Generate new UUID and timestamp
        const newUUID = crypto.randomUUID();
        const now = new Date();
        const newTimestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, -5); // 2026-01-24T12-30-45
        const shortId = newUUID.slice(-8);

        console.log('[Gemini Fork] New UUID:', newUUID);
        console.log('[Gemini Fork] New timestamp:', newTimestamp);

        // Patch the data
        const newData = {
          ...sourceData,
          sessionId: newUUID,
          startTime: now.toISOString(),
          lastUpdateTime: now.toISOString()
          // projectHash stays the same (same directory)
        };

        // Save with new filename
        const newFilename = `session-${newTimestamp}-${shortId}.json`;
        const newFilePath = path.join(chatsDir, newFilename);

        fs.writeFileSync(newFilePath, JSON.stringify(newData, null, 2), 'utf-8');
        console.log('[Gemini Fork] ✅ Created fork:', newFilename);

        // Run gemini -r with the NEW session ID
        term.write(`gemini -r ${newUUID}\r`);

        // Notify renderer about new session ID
        event.sender.send('gemini:session-detected', { tabId, sessionId: newUUID });
        console.log('[Gemini Fork] Sent session-detected event with new UUID');

      } catch (error) {
        console.error('[Gemini Fork] Error:', error);
        term.write(`echo "❌ Fork error: ${error.message}"\r`);
      }
      break;

    default:
      console.error('[Gemini] Unknown command:', command);
  }
});

// Send a slash command to Gemini CLI (chunked paste, fast mode)
// Serialized per tab: rapid clicks queue up instead of overlapping.
// Without this, two rapid Ctrl+C from ctrlCFirst trigger Gemini's
// "Press Ctrl+C again to exit" → second Ctrl+C kills the process.
// NOTE: geminiCommandQueue declared at top with other Maps (used by MCP delivery too)

ipcMain.on('gemini:send-command', (event, tabId, command) => {
  console.log('[gemini:send-command] Received: tabId=' + tabId + ' command="' + command + '"');
  const term = terminals.get(tabId);
  if (!term) { console.log('[gemini:send-command] Terminal not found'); return; }

  const prev = geminiCommandQueue.get(tabId) || Promise.resolve();
  const next = prev.then(async () => {
    // Wait for Gemini to settle after previous command
    await drainPtyData(term, 300);

    // Clear input line WITHOUT Ctrl+C (which triggers "Press Ctrl+C again to exit").
    // Ctrl+C at idle in Gemini = danger zone. Instead:
    // 1. Ctrl+A (Home) to move cursor to start
    // 2. Ctrl+K to kill from cursor to end of line (clears input)
    // Both are readline-compatible and safe in Gemini's TUI.
    term.write('\x01'); // Ctrl+A (beginning of line)
    term.write('\x0b'); // Ctrl+K (kill to end of line)
    await new Promise(r => setTimeout(r, 100));

    await safePasteAndSubmit(term, command, {
      submit: true,
      ctrlCFirst: false,
      fast: true,
      logPrefix: '[gemini:send-command:' + tabId + ']'
    });
    // Wait for Gemini to process the command before allowing next
    await drainPtyData(term, 500);
  });
  geminiCommandQueue.set(tabId, next.catch((err) => {
    console.error('[gemini:send-command] Error:', err.message);
  }));
});

// ========== CODEX INPUT INTERCEPTION ==========

ipcMain.on('codex:close-watcher', (_event, { tabId }) => {
  closeCodexWatcher(tabId);
});

async function runCodexCommandFromPayload(sender, payload = {}) {
  const { tabId, command, sessionId, cwd, model, effort, developerInstructions } = payload;
  const term = terminals.get(tabId);
  if (!term) {
    console.error('[Codex Runner] Terminal not found:', tabId);
    return { success: false, error: 'terminal_not_found' };
  }

  const termCwd = cwd || terminalProjects.get(tabId);
  const normalizedCommand = command || 'codex';
  const boundSessionId = getCodexBoundSessionId(tabId);
  if (normalizedCommand === 'codex' && !sessionId && boundSessionId && payload.allowNewOverExisting !== true) {
    console.warn('[Codex Runner] blocked plain start over bound session tab=' + String(tabId).slice(-12)
      + ' oldSession=' + String(boundSessionId).slice(0, 8)
      + ' cwd=' + (termCwd || 'n/a')
      + ' restartReason=' + (payload.restartReason || 'direct'));
    return {
      success: false,
      accepted: false,
      error: 'tab_has_resumable_session',
      reason: 'plain_codex_start_blocked_by_bound_session',
      tabId,
      command: normalizedCommand,
      sessionId: boundSessionId,
      conversationMaterialized: true,
      canResume: true,
      canCopySessionId: true,
      materializationReason: 'codex-session-bound',
    };
  }
  const startedAt = Date.now();
  const effectiveModel = model || readDefaultCodexSetting('defaultCodexModel');
  const effectiveEffort = effort || readDefaultCodexSetting('defaultCodexEffort');
  const restartReason = payload.restartReason || 'direct';
  const mcpStartupRestartAttempts = Number(payload.mcpStartupRestartAttempts) || 0;
  const launchId = payload.launchId || ('codex-' + Date.now() + '-' + (++codexLaunchSeq));
  codexLastRunCommandPayload.set(tabId, {
    launchId,
    tabId,
    command: normalizedCommand,
    sessionId,
    cwd: termCwd,
    model: effectiveModel,
    effort: effectiveEffort,
    developerInstructions,
    mcpStartupRestartAttempts,
    startedAt,
  });
  console.log('[Codex Runner] Command:', normalizedCommand, 'tab:', tabId, 'session:', sessionId || 'new', 'cwd:', termCwd, 'model:', effectiveModel || 'default', 'effort:', effectiveEffort || 'default', 'developerInstructionsChars:', developerInstructions ? String(developerInstructions).length : 0, 'restartReason:', restartReason, 'mcpStartupRestarts:', mcpStartupRestartAttempts, 'launchId:', launchId);

  codexSavedClipboardImagesByTab.delete(tabId);
  invalidateAiProcessLookupCache(tabId, 'codex');
  const commandState = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
  commandState.isRunning = true;
  clearTerminalCommandOrigin(tabId, commandState, 'codex-run-command');
  terminalCommandState.set(tabId, commandState);
  if (mainWindow && !mainWindow.isDestroyed()) {
    mainWindow.webContents.send('terminal:command-started', { tabId, commandType: 'codex' });
  }
  clearCodexTuiReady(tabId, 'run-command');
  armCodexStartupAutoEnter(tabId, { command: normalizedCommand, sessionId, cwd: termCwd });
  broadcastCodexStartingSnapshot(tabId, 'codex-run-command');

  if (normalizedCommand === 'codex-c' && sessionId) {
    closeCodexWatcher(tabId, 'resume-known-session');
    setCodexKnownSession(tabId, sessionId, 'resume-known-session');
    const notifyTarget = sender || (mainWindow && !mainWindow.isDestroyed() ? mainWindow.webContents : null);
    if (notifyTarget && typeof notifyTarget.send === 'function') {
      notifyTarget.send('codex:session-detected', { tabId, sessionId });
    }
    ensureCodexTurnWatcher(tabId, sessionId, termCwd, {
      suppressBusyCatchUp: true,
      catchUpReason: 'codex-c-resume',
    });
  } else if (normalizedCommand === 'codex-f' && sessionId) {
    startCodexSessionWatcher(sender, { tabId, cwd: termCwd, startedAt, sourceSessionId: sessionId });
    console.log('[Codex Runner] Fork source session provided; waiting for watcher to capture the new fork session id');
  } else {
    startCodexSessionWatcher(sender, { tabId, cwd: termCwd, startedAt });
  }

  let profile = null;
  try {
    profile = await writeCodexDeveloperInstructionsProfile(tabId, developerInstructions);
  } catch (err) {
    console.warn('[Codex Runner] failed to write developer profile tab=' + String(tabId).slice(-12) + ' ' + (err?.message || String(err)));
  }

  const cmdLine = buildCodexCommand({
    command: normalizedCommand,
    sessionId,
    cwd: termCwd,
    model: effectiveModel,
    effort: effectiveEffort,
    developerInstructions: profile ? '' : developerInstructions,
    profile,
  });
  term.write(cmdLine + '\r');
  const accepted = await waitForAiLaunchAccepted(tabId, 'codex', {
    timeoutMs: payload.acceptTimeoutMs || 5000,
    intervalMs: 120,
    reason: 'codex:run-command',
  });
  if (!accepted.accepted) {
    console.error(
      '[Codex Runner] launch not accepted tab=' + String(tabId).slice(-12) +
      ' command=' + normalizedCommand +
      ' reason=' + (accepted.reason || accepted.error || 'unknown')
    );
    clearCodexLaunchPayload(tabId, 'launch-not-accepted');
    clearCodexKnownSession(tabId, 'launch-not-accepted');
    closeCodexWatcher(tabId, 'launch-not-accepted');
    clearCodexTuiReady(tabId, 'launch-not-accepted');
    invalidateAiProcessLookupCache(tabId, 'codex');
    const failedState = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 1 };
    failedState.isRunning = false;
    failedState.lastExitCode = 1;
    terminalCommandState.set(tabId, failedState);
    _webBroadcast(tabId, {
      type: 'snapshot',
      sessionId: null,
      busy: false,
      sessionStatus: 'inactive',
      starting: false,
      inputReady: false,
      toolType: 'codex',
      commandType: 'codex',
      startupFailed: true,
      startupError: accepted.reason || accepted.error || 'codex_launch_not_accepted',
    });
    return {
      success: false,
      accepted: false,
      error: accepted.error || 'codex_launch_not_accepted',
      reason: accepted.reason || null,
      tabId,
      command: normalizedCommand,
      sessionId: sessionId || null,
    };
  }
  return {
    success: true,
    accepted: true,
    launchId,
    pid: accepted.pid || null,
    tabId,
    command: normalizedCommand,
    sessionId: sessionId || null,
  };
}

