ipcMain.handle('codex:send-command', async (_event, tabId, command, options = {}) => {
  const statusAtSend = options && typeof options.statusAtSend === 'string' ? options.statusAtSend : null;
  // `shouldQueue` is a UI/API handoff state: the prompt was submitted while
  // Codex was busy, so clients keep the local row marked queued until rollout
  // materializes it. It is NOT a request to press Codex's native Tab queue key.
  const shouldQueue = !!(options && (options.queue === true || statusAtSend === 'busy'));
  const handoffId = options && typeof options.handoffId === 'string' ? options.handoffId : null;
  const source = options && typeof options.source === 'string' ? options.source : null;
  const codexSource = source
    ? (source.startsWith('codex-') ? source : 'codex-' + source)
    : (shouldQueue ? 'codex-history-queue' : 'codex-history-send');
  const skipVisibleDraftGuard = !!(options && options.skipVisibleDraftGuard === true);
  console.log('[codex:send-command] Received: tabId=' + tabId + ' queue=' + shouldQueue + ' statusAtSend=' + (statusAtSend || '-') + ' handoff=' + (handoffId || '-') + ' source=' + (source || '-') + ' resolvedSource=' + codexSource + ' skipVisibleDraftGuard=' + skipVisibleDraftGuard + ' command="' + command + '"');
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no_terminal' };
  const candidates = await findAiDescendantProcessesByTab(tabId, 'codex');
  if (candidates.length === 0) {
    console.log('[codex:send-command] ❌ No live Codex process under shell pid=' + term.pid + ' tab=' + tabId);
    return { success: false, error: 'no_codex_session' };
  }
  const hasTurnWatcher = await ensureCodexTurnWatcher(tabId, null, terminalProjects.get(tabId));
  const hasSessionWatcher = codexWatchers.has(tabId);
  if (!hasTurnWatcher && !hasSessionWatcher) {
    console.warn('[codex:send-command] ❌ No Codex turn watcher for tab=' + String(tabId).slice(-12) + ' — refusing unverified Enter send');
    return { success: false, error: 'codex_turn_watcher_unavailable' };
  }
  try {
    const result = await safePasteAndSubmit(term, command, {
      submit: true,
      ctrlCFirst: false,
      fast: false,
      submitSequence: '\r',
      submitLabel: shouldQueue ? 'Enter(busy)' : 'Enter',
      handoffId,
      source: codexSource,
      skipRenderWait: true,
      awaitCodexUserMessageAudit: true,
      codexAuditTimeoutMs: CODEX_PASTE_AUDIT_TIMEOUT_MS,
      verifyCodexVisibleDraftBeforeSubmit: !skipVisibleDraftGuard,
      logPrefix: '[codex:send-command:' + tabId + ']',
    });
    if (result && typeof result === 'object') {
      result.queued = shouldQueue;
    }
    if (hasTurnWatcher && result && result.success === false) {
      if (result.submitted === true) {
        console.warn('[codex:send-command] send returned failure after submit tab=' + String(tabId).slice(-12) + ' error=' + (result.error || 'unknown') + ' — preserving Codex busy-state');
      } else {
        emitCodexBusy(tabId, false, 'send-command-failed');
      }
    }
    return result;
  } catch (error) {
    if (hasTurnWatcher) emitCodexBusy(tabId, false, 'send-command-error');
    console.error('[codex:send-command] Error:', error);
    return { success: false, error: error.message };
  }
});

ipcMain.handle('codex:select-model-effort', async (_event, {
  tabId,
  model,
  effort,
  hasDraft = null,
  draftSource = '',
  draftPreview = '',
  visualHasDraft = null,
  visualSource = '',
  visualPreview = '',
}) => {
  console.log('[codex:select-model-effort] Received: tabId=' + tabId + ' model=' + model + ' effort=' + (effort || '') + ' hasDraft=' + hasDraft + ' draftSource=' + (draftSource || 'n/a') + ' draftPreview=' + JSON.stringify(String(draftPreview || '').slice(0, 120)) + ' visualHasDraft=' + visualHasDraft + ' visualSource=' + (visualSource || 'n/a') + ' visualPreview=' + JSON.stringify(String(visualPreview || '').slice(0, 120)));
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'terminal not found' };
  if (!model) return { success: false, error: 'model is required' };

  const prev = codexPickerQueue.get(tabId) || Promise.resolve();
  const next = prev.catch(() => {}).then(async () => {
    try {
      return await withPtyWriteLock(term, () => selectCodexModelEffort(term, {
        tabId,
        model,
        effort,
        hasDraft,
        draftSource,
        draftPreview,
        visualHasDraft,
        visualSource,
        visualPreview,
      }));
    } catch (error) {
      console.error('[codex:select-model-effort] Error:', error);
      try { term.write('\x1b'); } catch {}
      return { success: false, error: error.message };
    }
  });
  codexPickerQueue.set(tabId, next);
  try {
    return await next;
  } finally {
    if (codexPickerQueue.get(tabId) === next) codexPickerQueue.delete(tabId);
  }
});

