// ========== GEMINI REWIND (TUI NAVIGATION) ==========
// Programmatic rewind: open /rewind menu, navigate to target, confirm.
// Gemini rewind menu:
//   /rewind\r → modal with ● on "Stay at current position" (bottom)
//   UP moves ● through messages (newest→oldest)
//   Enter → confirmation dialog "● 1. Rewind conversation / 2. Do nothing"
//   Enter → rewind executed
// Detection: RGB(166,227,161) green text = selected entry

ipcMain.handle('gemini:open-history-menu', async (event, { tabId, targetText, skipDuplicates = 0, pasteAfter }) => {
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no terminal' };

  const stripped = require('node:util').stripVTControlCharacters;

  // Extract text colored with RGB(166,227,161) — green selection color
  function extractGreenText(raw) {
    const GREEN_START = '\x1b[38;2;166;227;161m';
    const results = [];
    let searchFrom = 0;
    while (true) {
      const startIdx = raw.indexOf(GREEN_START, searchFrom);
      if (startIdx === -1) break;
      let endIdx = startIdx + GREEN_START.length;
      let text = '';
      while (endIdx < raw.length) {
        if (raw[endIdx] === '\x1b') {
          const remaining = raw.substring(endIdx);
          if (remaining.startsWith('\x1b[39m') || remaining.startsWith('\x1b[38;2;') || remaining.startsWith('\x1b[0m')) break;
          const escEnd = remaining.indexOf('m');
          if (escEnd !== -1 && escEnd < 30) { endIdx += escEnd + 1; continue; }
        }
        text += raw[endIdx];
        endIdx++;
      }
      const cleaned = stripped(text).trim();
      if (cleaned.length > 0 && cleaned !== '\u25CF') results.push(cleaned);
      searchFrom = endIdx;
    }
    return results;
  }

  function textMatchesTarget(selectedText, targetPrefix) {
    if (!selectedText || !targetPrefix) return false;
    const st = selectedText.trim().replace(/\s+/g, ' ').substring(0, 50);
    const tp = targetPrefix.trim().replace(/\s+/g, ' ').substring(0, 50);
    if (st.includes(tp) || tp.includes(st)) return true;
    // Fuzzy: >=60% word overlap
    const targetWords = tp.split(/\s+/).filter(w => w.length > 2);
    if (targetWords.length > 0) {
      const matched = targetWords.filter(w => st.includes(w));
      if (matched.length / targetWords.length >= 0.6) return true;
    }
    return false;
  }

  // Serialize with geminiCommandQueue
  const prev = geminiCommandQueue.get(tabId) || Promise.resolve();
  const result = await new Promise((resolveOuter) => {
    const next = prev.then(async () => {
      try {
        // Step 0: Check DangerZone
        const dz = claudeCtrlCDangerZone.get(tabId);
        if (dz) {
          console.log('[Gemini:Rewind] \u26A0\uFE0F DangerZone active — waiting...');
          await dz.promise;
          console.log('[Gemini:Rewind] \u2705 DangerZone cleared');
        }

        // Step 1: Clear input and send /rewind
        console.log('[Gemini:Rewind] Step 1: Sending /rewind...');
        term.write('\x01'); // Ctrl+A
        term.write('\x0b'); // Ctrl+K
        await new Promise(r => setTimeout(r, 100));

        await safePasteAndSubmit(term, '/rewind', {
          submit: true,
          ctrlCFirst: false,
          fast: true,
          logPrefix: '[Gemini:Rewind]'
        });

        // Step 2: Wait for menu to render (deterministic marker)
        console.log('[Gemini:Rewind] Step 2: Waiting for menu...');
        const menuRaw = await waitForPtyText(term, 'Stay at current position', 5000, '[Gemini:Rewind]');

        if (!menuRaw.includes('Rewind') && !menuRaw.includes('\u25CF')) {
          console.error('[Gemini:Rewind] Menu did not open (' + menuRaw.length + 'B)');
          resolveOuter({ success: false, error: 'Rewind menu did not open' });
          return;
        }
        console.log('[Gemini:Rewind] Menu opened (' + menuRaw.length + 'B)');

        // Step 3: Navigate UP to target
        const targetPrefix = (targetText || '').substring(0, 40);
        console.log('[Gemini:Rewind] Step 3: Navigating to: "' + targetPrefix + '"');

        let found = false;
        let pressCount = 0;
        const maxPresses = 50;
        let duplicatesRemaining = skipDuplicates;

        for (let i = 0; i < maxPresses; i++) {
          term.write('\x1b[A'); // UP
          const navRaw = await waitForPtyText(term, /\x1b\[38;2;166;227;161m/, 2000, '[Gemini:Rewind]');
          pressCount++;

          if (navRaw.length === 0) {
            console.log('[Gemini:Rewind] Hit top boundary at press #' + pressCount);
            break;
          }

          const greenTexts = extractGreenText(navRaw);
          // Last green text is the entry text (first is ● symbol)
          const selectedText = greenTexts.length > 0 ? greenTexts[greenTexts.length - 1] : null;
          console.log('[Gemini:Rewind] UP #' + pressCount + ' \u2192 "' + (selectedText || 'null').substring(0, 50) + '"');

          if (selectedText && textMatchesTarget(selectedText, targetPrefix)) {
            if (duplicatesRemaining > 0) {
              duplicatesRemaining--;
              console.log('[Gemini:Rewind] \u23E9 Skipping duplicate (' + duplicatesRemaining + ' remaining)');
              continue;
            }
            console.log('[Gemini:Rewind] \u2705 Target matched!');
            found = true;
            break;
          }
        }

        if (!found) {
          console.error('[Gemini:Rewind] \u274C Target not found after ' + pressCount + ' presses. Closing menu.');
          term.write('\x1b'); // Escape to close
          await waitForPtyText(term, /INSERT|NORMAL/, 2000, '[Gemini:Rewind]');
          resolveOuter({ success: false, error: 'Target not found', pressCount });
          return;
        }

        // Step 4: Confirm selection (Enter)
        console.log('[Gemini:Rewind] Step 4: Confirming selection...');
        term.write('\r');
        const confirmRaw = await waitForPtyText(term, 'Do nothing', 5000, '[Gemini:Rewind]');

        // Step 5: Handle confirmation dialog
        // After selecting an entry, Gemini shows: "● 1. Rewind conversation / 2. Do nothing"
        // ● is already on "Rewind conversation" — just press Enter
        const confirmClean = stripped(confirmRaw.replace(/\x1b\[\d+;\d+[Hf]/g, '\n').replace(/\x1b\[(\d*)C/g, ' '));
        if (confirmClean.includes('Rewind conversation') || confirmClean.includes('Do nothing')) {
          console.log('[Gemini:Rewind] Step 5: Confirmation dialog detected — pressing Enter...');
          term.write('\r');
          await waitForPtyText(term, /shift\+tab|INSERT|NORMAL/, 8000, '[Gemini:Rewind]');
        } else {
          console.log('[Gemini:Rewind] Step 5: No confirmation dialog (direct rewind)');
        }

        // Step 6: Wait for rewind to complete and prompt to restore
        console.log('[Gemini:Rewind] Step 6: Waiting for prompt...');
        await waitForPtyText(term, /shift\+tab|INSERT|NORMAL/, 5000, '[Gemini:Rewind]');

        // Step 7: Paste compact if provided
        if (pasteAfter && typeof pasteAfter === 'string' && pasteAfter.length > 0) {
          console.log('[Gemini:Rewind] Step 7: Pasting compact (' + pasteAfter.length + ' chars)...');

          term.write('\x01'); // Ctrl+A
          term.write('\x0b'); // Ctrl+K
          await new Promise(r => setTimeout(r, 100));

          await safePasteAndSubmit(term, pasteAfter, {
            submit: true,
            ctrlCFirst: false,
            fast: true,
            logPrefix: '[Gemini:Rewind:paste]'
          });
          await waitForPtyText(term, /shift\+tab/, 5000, '[Gemini:Rewind]');
        }

        console.log('[Gemini:Rewind] \u2705 Rewind complete');
        resolveOuter({ success: true, found: true, pressCount });
      } catch (err) {
        console.error('[Gemini:Rewind] Error:', err.message);
        try { term.write('\x1b'); } catch (e) {} // try close menu
        resolveOuter({ success: false, error: err.message });
      }
    });
    geminiCommandQueue.set(tabId, next.catch(() => {}));
  });

  return result;
});


// ========== GEMINI TIME MACHINE ==========
// Auto-backup session on every change, allow rollback to any turn

const MINAYU_HISTORY_DIR = path.join(os.homedir(), '.minayu', 'history');
const geminiHistoryWatchers = new Map(); // sessionId -> { watcher, filePath, lastTurnCount }

// Ensure history directory exists
if (!fs.existsSync(MINAYU_HISTORY_DIR)) {
  fs.mkdirSync(MINAYU_HISTORY_DIR, { recursive: true });
}

// Count user messages (turns) in a session
function countGeminiTurns(sessionData) {
  if (!sessionData.messages) return 0;
  return sessionData.messages.filter(m => m.type === 'user').length;
}

// Save a history snapshot for a specific turn
function saveGeminiHistorySnapshot(sessionId, sessionData, turnNumber) {
  const historyDir = path.join(MINAYU_HISTORY_DIR, sessionId);
  if (!fs.existsSync(historyDir)) {
    fs.mkdirSync(historyDir, { recursive: true });
  }

  const snapshotFile = path.join(historyDir, `turn-${String(turnNumber).padStart(3, '0')}.json`);

  // Don't overwrite existing snapshots
  if (fs.existsSync(snapshotFile)) {
    return false;
  }

  fs.writeFileSync(snapshotFile, JSON.stringify(sessionData, null, 2), 'utf-8');
  console.log('[Gemini TimeMachine] Saved snapshot:', snapshotFile);
  return true;
}

// Start watching a session file for changes
ipcMain.on('gemini:start-history-watcher', (event, { sessionId, cwd }) => {
  console.log('[Gemini TimeMachine] Starting history watcher for:', sessionId);

  // Close existing watcher for this session
  if (geminiHistoryWatchers.has(sessionId)) {
    const old = geminiHistoryWatchers.get(sessionId);
    try { old.watcher.close(); } catch (e) {}
    geminiHistoryWatchers.delete(sessionId);
  }

  // Find the session file via slug/hash resolver
  const resolved = resolveGeminiProjectDir(cwd);
  if (!resolved) {
    console.error('[Gemini TimeMachine] Project dir not found for:', cwd);
    return;
  }
  const found = findGeminiSessionFile(sessionId, resolved.chatsDir);
  if (!found) {
    console.error('[Gemini TimeMachine] Session file not found:', sessionId);
    return;
  }
  const sessionFilePath = found.filePath;
  console.log('[Gemini TimeMachine] Watching file:', sessionFilePath);

  // Read initial state
  let lastTurnCount = 0;
  try {
    const data = JSON.parse(fs.readFileSync(sessionFilePath, 'utf-8'));
    lastTurnCount = countGeminiTurns(data);
    // Save initial snapshot
    if (lastTurnCount > 0) {
      saveGeminiHistorySnapshot(sessionId, data, lastTurnCount);
    }
  } catch (e) {
    console.error('[Gemini TimeMachine] Error reading initial state:', e.message);
  }

  // Watch for changes
  const watcher = fs.watch(sessionFilePath, { persistent: false }, (eventType) => {
    if (eventType !== 'change') return;

    // Debounce: wait a bit for file to be fully written
    setTimeout(() => {
      try {
        const content = fs.readFileSync(sessionFilePath, 'utf-8');
        const data = JSON.parse(content);
        const currentTurnCount = countGeminiTurns(data);

        // New turn detected - save snapshot
        if (currentTurnCount > lastTurnCount) {
          console.log('[Gemini TimeMachine] New turn detected:', lastTurnCount, '->', currentTurnCount);
          saveGeminiHistorySnapshot(sessionId, data, currentTurnCount);
          lastTurnCount = currentTurnCount;

          // Notify renderer about new turn
          event.sender.send('gemini:history-updated', { sessionId, turnCount: currentTurnCount });
        }
      } catch (e) {
        // File might be in the middle of being written
      }
    }, 500);
  });

  geminiHistoryWatchers.set(sessionId, { watcher, filePath: sessionFilePath, lastTurnCount });
});

// Stop watching a session
ipcMain.on('gemini:stop-history-watcher', (event, { sessionId }) => {
  if (geminiHistoryWatchers.has(sessionId)) {
    const { watcher } = geminiHistoryWatchers.get(sessionId);
    try { watcher.close(); } catch (e) {}
    geminiHistoryWatchers.delete(sessionId);
    console.log('[Gemini TimeMachine] Stopped watching:', sessionId);
  }
});

// gemini:save-history, gemini:get-history, gemini:delete-history,
// gemini:create-prefilled-session, gemini:copy-range, gemini:get-timemachine,
// gemini:rollback, gemini:get-timeline, gemini:get-full-history → ipc/gemini-data.js
require(path.join(srcMainDir, 'ipc', 'gemini-data')).register({ projectManager, geminiUtils: { resolveGeminiProjectDir, findGeminiSessionFile, invalidateProjectsJsonCache, getGeminiProjectsJson, calculateGeminiHash }, terminals, terminalProjects, geminiHistoryWatchers });


// Legacy fork handler (for new tab creation)
ipcMain.on('claude:fork-session', async (event, { tabId, existingSessionId, cwd }) => {
  console.log('[Claude Fork] Starting fork for tab:', tabId);
  console.log('[Claude Fork] Existing session:', existingSessionId);
  console.log('[Claude Fork] CWD:', cwd);

  try {
    // Generate new session ID
    const newSessionId = crypto.randomUUID();
    console.log('[Claude Fork] New session ID:', newSessionId);

    // Calculate project slug (Claude uses path with / replaced by -)
    const projectSlug = cwd.replace(/\//g, '-');
    const projectDir = path.join(os.homedir(), '.claude', 'projects', projectSlug);
    console.log('[Claude Fork] Project dir:', projectDir);

    // If we have an existing session, copy its file
    if (existingSessionId) {
      const oldPath = path.join(projectDir, `${existingSessionId}.jsonl`);
      const newPath = path.join(projectDir, `${newSessionId}.jsonl`);

      if (fs.existsSync(oldPath)) {
        fs.copyFileSync(oldPath, newPath);
        console.log('[Claude Fork] Copied session file:', oldPath, '->', newPath);
      } else {
        console.log('[Claude Fork] Source session file not found:', oldPath);
      }
    }

    // Send event to renderer to create new tab and run claude
    // Renderer will handle tab creation and command execution
    event.sender.send('claude:fork-complete', {
      success: true,
      newSessionId,
      cwd
    });
  } catch (error) {
    console.error('[Claude Fork] Error:', error);
    event.sender.send('claude:fork-complete', {
      success: false,
      error: error.message
    });
  }
});

// ========== CLAUDE COMMAND RUNNER (from UI buttons) ========== 
// This handles claude commands triggered from InfoPanel buttons
// bypassing the terminal input interception (which only works for keyboard Enter)
function readClaudeSessionCwdFromFile(filePath) {
  try {
    const fd = fs.openSync(filePath, 'r');
    const buf = Buffer.alloc(64 * 1024);
    const bytesRead = fs.readSync(fd, buf, 0, buf.length, 0);
    fs.closeSync(fd);
    const head = buf.toString('utf-8', 0, bytesRead);
    for (const line of head.split('\n')) {
      if (!line.trim()) continue;
      try {
        const entry = JSON.parse(line);
        if (entry && typeof entry.cwd === 'string' && entry.cwd.trim()) {
          return entry.cwd;
        }
      } catch {}
    }
  } catch (e) {
    console.warn('[Claude Runner] Could not read session cwd from', filePath, e.message);
  }
  return null;
}

ipcMain.on('claude:run-command', async (event, { tabId, command, sessionId, forkSessionId, prompt, cdTo }) => {
  console.log('[Claude Runner] Command:', command, 'Tab:', tabId, 'Prompt:', prompt ? `${prompt.slice(0, 50)}...` : 'none');

  const term = terminals.get(tabId);
  if (!term) {
    console.error('[Claude Runner] Terminal not found for tab:', tabId);
    return;
  }

  // Get cwd for this terminal
  const cwd = terminalProjects.get(tabId);
  if (!cwd) {
    console.error('[Claude Runner] CWD not found for tab:', tabId);
    return;
  }

  switch (command) {
    case 'claude': {
      // New session — session ID will be detected by SessionBridge (via StatusLine)
      console.log('[Claude Runner] Starting new session for tab:', tabId);

      // Enable thinking mode detection (will send Tab when prompt appears)
      claudeState.set(tabId, 'WAITING_PROMPT');

      // If prompt provided, save it to send AFTER thinking mode is enabled
      if (prompt && prompt.trim()) {
        claudePendingPrompt.set(tabId, prompt.trim());
        console.log('[Claude Runner] Prompt saved, will send after thinking mode enabled');
      }

      // Always launch claude without prompt (prompt will be sent after Tab)
      term.write('claude --dangerously-skip-permissions\r');
      claudeCliActive.set(tabId, true);
      const commandState = terminalCommandState.get(tabId) || { isRunning: false, lastExitCode: 0 };
      commandState.isRunning = true;
      clearTerminalCommandOrigin(tabId, commandState, 'claude-run-command');
      terminalCommandState.set(tabId, commandState);
      claudeStartupIntents.set(tabId, { sessionId: null, at: Date.now(), reason: 'claude-run-command' });
      if (mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('terminal:command-started', { tabId, commandType: 'claude' });
      }
      _webBroadcast(tabId, {
        type: 'snapshot',
        sessionId: null,
        busy: false,
        sessionStatus: 'starting',
        starting: true,
        inputReady: false,
        toolType: 'claude',
        commandType: 'claude',
      });
      break;
    }

    case 'claude-c':
      // Continue session
      if (sessionId) {
        console.log('[Claude Runner] Continuing session:', sessionId, cdTo ? '(cd ' + cdTo + ')' : '');
        const tabCwd = terminalProjects.get(tabId);
        const liveOwner = getClaudeJsonlLiveOwner(sessionId, tabId)
          || await getClaudeJsonlExternalOwner(sessionId, tabCwd);
        if (liveOwner) {
          console.warn('[Claude Runner] BLOCKED duplicate claude-c resume of ' + sessionId.slice(0, 8) +
            ': owner tab=' + String(liveOwner.tabId || '').slice(-12) +
            ' reason=' + liveOwner.reason);
          break;
        }
        // Enable thinking mode detection (will send Tab when '>' prompt appears)
        claudeState.set(tabId, 'WAITING_PROMPT');

        // If prompt provided (e.g. Update API: /model haiku + trigger), queue it for handshake
        if (prompt && prompt.trim()) {
          claudePendingPrompt.set(tabId, prompt.trim());
          console.log('[Claude Runner] Resume prompt queued, will send after prompt detected');
        }

        // Trim accumulated trailing startup slash commands from JSONL BEFORE resume. Safe here
        // (and ONLY here): the previous claude process is dead — nobody will append
        // a child to the record we truncate, so the phantom-parentUuid race that
        // killed the old live EffortCleanup watcher cannot occur. Strict suffix-match:
        // only fires when `/model`/`/effort` is literally the file tail with no real message
        // after it. See claude-data.js::_trimTrailingEffortEntries and
        // fact-claude-tui-control.md::On-restart trailing startup slash trim.
        try {
          const r = trimTrailingEffortEntries(sessionId, tabCwd);
          if (r && r.trimmed > 0) {
            console.log('[Claude Runner] Trimmed ' + r.trimmed + ' trailing startup slash line(s) before resume of ' + sessionId.slice(0, 8) + ' (model=' + (r.model || 0) + ', effort=' + (r.effort || 0) + ')');
          }
        } catch (e) {
          console.warn('[Claude Runner] trimTrailingEffortEntries failed (non-fatal): ' + e.message);
        }

        // Optional cd: `claude --resume <uuid>` matches by project-slug derived from cwd.
        // Resuming a session that originated in a different project requires us to land
        // in that directory first; otherwise Claude reports "No conversation found".
        // Compose `cd "<path>" && claude ...` in one line so the user can't intercept.
        let cmdLine = `claude --dangerously-skip-permissions --resume ${sessionId}`;
        if (cdTo && typeof cdTo === 'string' && cdTo.trim()) {
          // Single-quote escaping: replace any ' inside the path with '\'' before wrapping.
          const safe = cdTo.replace(/'/g, "'\\''");
          cmdLine = `cd '${safe}' && ${cmdLine}`;
        }
        if (!markClaudePendingJsonlOwner(sessionId, tabId, 'claude-c')) {
          console.warn('[Claude Runner] BLOCKED claude-c pending-lock session=' + sessionId.slice(0, 8) +
            ' tab=' + String(tabId).slice(-12));
          break;
        }
        term.write(cmdLine + '\r');
        claudeCliActive.set(tabId, true);
        console.log('[Claude Runner] claudeCliActive SET for tab', tabId, '(claude-c)');

        // Signal that command started (for Timeline visibility)
        if (mainWindow && !mainWindow.isDestroyed()) {
          mainWindow.webContents.send('terminal:command-started', { tabId, commandType: 'claude' });
        }
      } else {
        console.error('[Claude Runner] No sessionId for claude-c');
      }
      break;

    case 'claude-f':
      // Fork session - copy file and signal renderer
      // IMPORTANT: Search ALL project directories because session might be from different project
      if (forkSessionId) {
        console.log('[Claude Runner] Forking session:', forkSessionId);

        const claudeProjectsDir = path.join(os.homedir(), '.claude', 'projects');
        const forkProjectSlug = cwd.replace(/\//g, '-');
        const primaryDir = path.join(claudeProjectsDir, forkProjectSlug);
        const primaryPath = path.join(primaryDir, `${forkSessionId}.jsonl`);

        let sourcePath = null;
        let sourceDir = null;

        // First try primary location (cwd-based)
        if (fs.existsSync(primaryPath)) {
          sourcePath = primaryPath;
          sourceDir = primaryDir;
          console.log('[Claude Runner] Found in primary location:', sourcePath);
        } else {
          // Search ALL project directories
          console.log('[Claude Runner] Not in primary, searching all projects...');
          if (fs.existsSync(claudeProjectsDir)) {
            const projectDirs = fs.readdirSync(claudeProjectsDir, { withFileTypes: true })
              .filter(dirent => dirent.isDirectory())
              .map(dirent => dirent.name);

            for (const dir of projectDirs) {
              const checkPath = path.join(claudeProjectsDir, dir, `${forkSessionId}.jsonl`);
              if (fs.existsSync(checkPath)) {
                sourcePath = checkPath;
                sourceDir = path.join(claudeProjectsDir, dir);
                console.log('[Claude Runner] ✓ Found in:', sourcePath);
                break;
              }
            }
          }
        }

        if (sourcePath && sourceDir) {
          const sessionCwd = readClaudeSessionCwdFromFile(sourcePath) || cwd;
          const destProjectSlug = sessionCwd.replace(/\//g, '-');
          const destDir = path.join(claudeProjectsDir, destProjectSlug);
          const newSessionId = crypto.randomUUID();
          // Copy to the session-cwd project directory so `cd <sessionCwd> && claude --resume`
          // uses the same slug Claude stored in the JSONL and does not show the cwd chooser.
          if (!fs.existsSync(destDir)) {
            fs.mkdirSync(destDir, { recursive: true });
          }
          const destPath = path.join(destDir, `${newSessionId}.jsonl`);

          // Get Timeline UUIDs snapshot using Backtrace algorithm
          const entryUuids = parseTimelineUuids(sourcePath);
          console.log('[Claude Runner] Timeline entries:', entryUuids.length);

          fs.copyFileSync(sourcePath, destPath);
          const rawLines = fs.readFileSync(destPath, 'utf-8').split('\n');
          const rewritten = rawLines.map(line => {
            if (!line.trim()) return line;
            try {
              const rec = JSON.parse(line);
              if (rec.sessionId) rec.sessionId = newSessionId;
              return JSON.stringify(rec);
            } catch { return line; }
          });
          fs.writeFileSync(destPath, rewritten.join('\n'));
          console.log('[Claude Runner] Copied session file, new ID:', newSessionId);
          console.log('[Claude Runner] From:', sourcePath);
          console.log('[Claude Runner] To:', destPath);
          console.log('[Claude Runner] Session cwd:', sessionCwd);

          // Save fork marker with UUIDs snapshot (always save, even if empty — marks fork at beginning)
          try {
            projectManager.db.saveForkMarker(forkSessionId, newSessionId, entryUuids);
            console.log('[Claude Runner] Fork marker saved with', entryUuids.length, 'UUIDs');
          } catch (e) { console.warn('[Claude Runner] Fork marker error:', e.message); }

          // Carry purple notes and pink rewind markers over to the fork's sessionId.
          // Notes/markers are keyed on (entry_uuid, session_id); fork creates a new
          // session_id for the same UUIDs, so we explicitly rebind them.
          try {
            const allUuids = [];
            for (const line of rewritten) {
              if (!line.trim()) continue;
              try {
                const r = JSON.parse(line);
                if (r.uuid) allUuids.push(r.uuid);
              } catch {}
            }
            const copied = projectManager.db.copyTimelineMetadataForFork(newSessionId, allUuids, tabId);
            if (copied.notes > 0 || copied.rewindMarkers > 0) {
              console.log('[Claude Runner] Copied timeline metadata: notes=' + copied.notes + ' rewindMarkers=' + copied.rewindMarkers);
            }
          } catch (e) {
            console.warn('[Claude Runner] Could not copy timeline metadata:', e.message);
          }

          // Import session_links from other DB (prod↔dev) for the source session chain
          try {
            const imported = projectManager.db.importSessionLinksFromOtherDb(forkSessionId);
            if (imported > 0) {
              console.log('[Claude Runner] Imported', imported, 'session links from other DB');
            }
          } catch (e) {
            console.warn('[Claude Runner] Could not import session links:', e.message);
          }

          // Run claude --resume in CURRENT terminal (not new tab!)
          // This is for claude-f <uuid> - resuming external session
          // Enable thinking mode detection (will send Tab when '>' prompt appears)
          claudeState.set(tabId, 'WAITING_PROMPT');
          let cmdLine = `claude --dangerously-skip-permissions --resume ${newSessionId}`;
          if (sessionCwd && sessionCwd.trim()) {
            const safe = sessionCwd.replace(/'/g, "'\\''");
            cmdLine = `cd '${safe}' && ${cmdLine}`;
          }
          term.write(cmdLine + '\r');
          claudeCliActive.set(tabId, true);
          console.log('[Claude Runner] claudeCliActive SET for tab', tabId);

          // Notify renderer about new session ID
          event.sender.send('claude:session-detected', { tabId, sessionId: newSessionId });
          _notifyClaudeSession(tabId, newSessionId);
          console.log('[Claude Runner] Started claude --resume in current terminal');
        } else {
          console.error('[Claude Runner] Source session not found in ANY project');
          console.error('[Claude Runner] Searched for:', forkSessionId);
          // Just echo error to terminal
          term.write(`echo "❌ Session not found: ${forkSessionId}"\r`);
        }
      } else {
        console.error('[Claude Runner] No forkSessionId for claude-f');
      }
      break;

    default:
      console.error('[Claude Runner] Unknown command:', command);
  }
});

// ====================== CLAUDE SDK ======================
// Manages Claude Agent SDK sessions (headless, no PTY)
// SDK writes its own JSONL — Timeline reads it via existing claude:get-timeline
// (mcpServers forwarding from ~/.claude.json — added below)

// (sdkSessions declared early at top-of-file so web-server can receive the Map by reference)

// SDK does NOT inherit the user's ~/.claude.json mcpServers automatically (Claude Code CLI does,
// but the agent SDK is conservative — empty mcpServers by default). We load the global config
// once at first use, cache it for the life of the Electron main process, then forward it into
// every query() options object. Each SDK session spawns its OWN set of stdio MCP processes
// (one set per active tab — they exit when session.query.close() runs). Singletons like the
// browser-mcp bridge handle multiple per-session clients on their own.
// Authoritative source for "which effort levels does model X support" — SDK
// ships a manifest via query.supportedModels() returning ModelInfo[] with
// supportedEffortLevels. We can't hard-code the table (Anthropic ships new
// generations independent of our release cycle); we call SDK once at first
// need, cache for the life of the Electron main process. Restart picks up
// new SDK versions automatically.
//
// Why a streaming query just to read metadata: supportedModels() is a Query
// method, not a top-level export. We open a minimal streaming query, call the
// method, close the query — net cost is a few hundred ms once per launch.
let _sdkModelCapsCache = null;
let _sdkModelCapsPromise = null;
async function loadSdkModelCapabilities() {
  if (_sdkModelCapsCache) return _sdkModelCapsCache;
  if (_sdkModelCapsPromise) return _sdkModelCapsPromise;
  _sdkModelCapsPromise = (async () => {
    try {
      const { query } = await import('@anthropic-ai/claude-agent-sdk');
      // Streaming input mode is required for control-request methods. We feed
      // an async iterable that never yields — the query stays parked waiting
      // for input, which is fine because we only need control methods.
      const neverEnding = (async function*() {
        // eslint-disable-next-line no-constant-condition
        while (true) {
          await new Promise(r => setTimeout(r, 60000));
          yield { type: 'user', message: { role: 'user', content: '' } };
        }
      })();
      // SDK 0.3.x requires `allowDangerouslySkipPermissions: true` alongside
      // `permissionMode: 'bypassPermissions'` — without it the CLI process
      // refuses to start (safety gate against accidentally inheriting bypass).
      const claudeBin = resolveClaudeBinaryPath();
      const q = query({ prompt: neverEnding, options: {
        permissionMode: 'bypassPermissions',
        allowDangerouslySkipPermissions: true,
        ...(claudeBin ? { pathToClaudeCodeExecutable: claudeBin } : {}),
      } });
      const models = await q.supportedModels();
      try { q.close(); } catch {}
      const map = {};
      for (const m of models) {
        if (!m?.value) continue;
        // Record EVERY model — including ones with NO supportedEffortLevels
        // (e.g. Haiku, which ships the field absent). Storing an explicit empty
        // array lets the renderer distinguish "model supports zero efforts →
        // hide the whole effort cluster" from "caps not loaded yet → don't gate".
        // Previously these models were skipped entirely, so caps[haiku] was
        // undefined and the gating fell through to "show all effort pills".
        map[m.value] = Array.isArray(m.supportedEffortLevels) ? m.supportedEffortLevels : [];
      }
      console.log('[ClaudeSDK] model capabilities loaded: ' + Object.keys(map).length + ' models (' + Object.entries(map).map(([k, v]) => k + ':' + (v.length || 0)).join(', ') + ')');
      _sdkModelCapsCache = map;
      return map;
    } catch (err) {
      console.warn('[ClaudeSDK] failed to read model capabilities:', err.message);
      _sdkModelCapsCache = {};
      return _sdkModelCapsCache;
    } finally {
      _sdkModelCapsPromise = null;
    }
  })();
  return _sdkModelCapsPromise;
}

// Resolve the path to the native Claude binary shipped by the SDK's optional
// platform package (@anthropic-ai/claude-agent-sdk-<plat>-<arch>). The SDK
// resolves this internally via createRequire(import.meta.url) and hands the
// path to child_process.spawn — but in a packaged Electron app sdk.mjs lives
// at app.asar/.../sdk.mjs, so the resolved path is also inside app.asar.
// spawn() on an asar-wrapped binary path errors with ENOTDIR (asar is a file,
// not a directory). electron-builder rewrites fs/require for app.asar.unpacked
// targets but NOT spawn args. Fix: resolve once at startup, rewrite asar →
// asar.unpacked when both paths are inside the application bundle, hand the
// real on-disk path to SDK via options.pathToClaudeCodeExecutable.
//
// Two resolve attempts in priority order, both via plain require.resolve from
// this file (works in dev — node_modules on disk — AND in production — main.js
// lives inside app.asar so Electron's asar-patched resolver finds the SDK's
// optional platform package the same way):
//   1) require.resolve('@anthropic-ai/claude-agent-sdk-<plat>-<arch>/claude')
//   2) fallback: derive from require.resolve('@anthropic-ai/claude-agent-sdk')
//      → SDK main entry sdk.mjs → ../<platformPkg>/claude
// Earlier version used createRequire from package.json — that fails because
// SDK's "exports" field doesn't expose package.json, throwing
// ERR_PACKAGE_PATH_NOT_EXPORTED. Don't go through package.json.
// Cached because the resolution does sync FS work.
let _claudeBinaryPath = undefined; // undefined = not yet probed; null = probed, not found
function resolveClaudeBinaryPath() {
  if (_claudeBinaryPath !== undefined) return _claudeBinaryPath;
  const platformPkg = '@anthropic-ai/claude-agent-sdk-' + process.platform + '-' + process.arch;
  const candidates = [];
  // Direct resolve — works as long as the platform pkg is reachable from
  // main.js's module graph (it is — both in dev node_modules and in app.asar).
  try { candidates.push({ src: 'direct', path: require.resolve(platformPkg + '/claude') }); }
  catch (e) { console.warn('[ClaudeSDK] direct resolve of ' + platformPkg + '/claude failed: ' + e.message); }
  // Fallback: locate SDK main entry (sdk.mjs), then walk to the optional
  // platform pkg. platformPkg already includes the @anthropic-ai/ scope.
  try {
    const sdkMain = require.resolve('@anthropic-ai/claude-agent-sdk');
    // sdkMain ≈ <prefix>/node_modules/@anthropic-ai/claude-agent-sdk/sdk.mjs
    // Option A — top-level sibling (npm dedup'd the optional pkg):
    //   <prefix>/node_modules/@anthropic-ai/<scopelessPlatformPkg>/claude
    // Option B — nested inside SDK's own node_modules (npm did NOT dedup,
    // this is what production currently has):
    //   <sdkDir>/node_modules/<platformPkg>/claude
    const sdkDir = path.dirname(sdkMain);
    const scopeRoot = path.dirname(sdkDir);                // .../node_modules/@anthropic-ai
    const platformPkgName = platformPkg.replace(/^@anthropic-ai\//, '');
    const sibling = path.join(scopeRoot, platformPkgName, 'claude');
    const nested = path.join(sdkDir, 'node_modules', platformPkg, 'claude');
    candidates.push({ src: 'sibling', path: sibling });
    candidates.push({ src: 'nested', path: nested });
  } catch (e) {
    console.warn('[ClaudeSDK] cannot resolve @anthropic-ai/claude-agent-sdk main: ' + e.message);
  }
  if (candidates.length === 0) {
    console.warn('[ClaudeSDK] no candidates for claude binary path — SDK will fall back to default lookup (likely ENOTDIR in packaged build)');
    _claudeBinaryPath = null;
    return _claudeBinaryPath;
  }
  for (const { src, path: candidate } of candidates) {
    // Rewrite app.asar → app.asar.unpacked. asarUnpack in package.json
    // ensures the binary is present on disk under .unpacked.
    const unpacked = candidate.replace(/([\/\\])app\.asar([\/\\])/, '$1app.asar.unpacked$2');
    if (fs.existsSync(unpacked)) {
      console.log('[ClaudeSDK] claude binary resolved via ' + src + ': ' + unpacked + (unpacked !== candidate ? ' (rewrote from asar)' : ''));
      _claudeBinaryPath = unpacked;
      return _claudeBinaryPath;
    }
    if (fs.existsSync(candidate)) {
      console.log('[ClaudeSDK] claude binary resolved via ' + src + ': ' + candidate);
      _claudeBinaryPath = candidate;
      return _claudeBinaryPath;
    }
  }
  console.warn('[ClaudeSDK] claude binary not found on disk. Candidates tried:\n' + candidates.map(c => '  ' + c.src + ': ' + c.path).join('\n'));
  _claudeBinaryPath = null;
  return _claudeBinaryPath;
}

let _sdkMcpServersCache = null;
function loadGlobalMcpServers() {
  if (_sdkMcpServersCache !== null) return _sdkMcpServersCache;
  try {
    const cfgPath = require('path').join(require('os').homedir(), '.claude.json');
    const raw = require('fs').readFileSync(cfgPath, 'utf8');
    const cfg = JSON.parse(raw);
    _sdkMcpServersCache = (cfg && cfg.mcpServers) ? cfg.mcpServers : {};
    console.log('[ClaudeSDK] mcpServers loaded from ~/.claude.json: ' + Object.keys(_sdkMcpServersCache).join(','));
  } catch (err) {
    console.warn('[ClaudeSDK] failed to read ~/.claude.json mcpServers, running without MCP:', err.message);
    _sdkMcpServersCache = {};
  }
  return _sdkMcpServersCache;
}

// Best-effort handle to web-server (lazy require — survives if module missing).
// Same path resolution as the startup load — must use srcMainDir, not relative.
function _webBroadcast(tabId, payload) {
  try {
    require(path.join(srcMainDir, 'web-server')).webBroadcast(tabId, payload);
  } catch (err) {
    console.warn('[WebBcast:MainError] tab=' + String(tabId || '').slice(-12) + ' type=' + (payload?.type || '-') + ' error=' + (err?.message || String(err)));
  }
  const type = payload && payload.type;
  if (type === 'busy' || type === 'done' || type === 'snapshot') {
    scheduleProjectActivityBroadcast('tab-' + type);
  }
}

// Event-driven hand-off: fired whenever a tab's Claude sessionId becomes
// known (Bridge:Fresh, explicit resume, fork, restore). web-server's
// JSONL-watcher uses this to promote "parked" mobile-web subscribers from
// "waiting for sessionId" → live fs.watch — no polling required.
function _notifyClaudeSession(tabId, sessionId) {
  if (!tabId || !sessionId) return;
  try {
    require(path.join(srcMainDir, 'web-server')).notifyClaudeSessionAvailable(tabId);
  } catch {}
  scheduleProjectActivityBroadcast('claude-session');
  // Mobile subscribers also need the sessionId itself for their snapshot —
  // sending it through the WS protocol lets the phone update without waiting
  // for the next /status poll.
  if (!aiStoppingTabs.has(tabId)) {
    let persisted = null;
    try {
      persisted = projectManager?.db?.db?.prepare(
        'SELECT cwd FROM tabs WHERE tab_id = ? LIMIT 1'
      ).get(tabId) || null;
    } catch {}
    let materialization = null;
    try {
      materialization = getSessionMaterialization(sessionId, persisted?.cwd || process.cwd());
    } catch (err) {
      console.warn('[ClaudeSessionNotify] materialization check failed tab=' + String(tabId).slice(-12) + ' session=' + String(sessionId).slice(0, 8) + ' err=' + (err?.message || String(err)));
    }
    const conversationMaterialized = materialization?.materialized === true;
    const busy = claudeTurnBusy.get(tabId) === true || claudeLocalCommandWatchers.has(tabId);
    const promptReady = claudePromptReady.has(tabId);
    const sessionStatus = busy ? 'busy' : (promptReady ? 'active' : 'starting');
    _webBroadcast(tabId, {
      type: 'snapshot',
      sessionId,
      busy,
      sessionStatus,
      starting: sessionStatus === 'starting',
      inputReady: promptReady && !busy,
      toolType: 'claude',
      commandType: 'claude',
      conversationMaterialized,
      canResume: false,
      canCopySessionId: conversationMaterialized,
      timelineCount: typeof materialization?.timelineCount === 'number' ? materialization.timelineCount : null,
      materializationReason: materialization?.reason || null,
    });
  }
}

// Validate that a session UUID actually has a resumable conversation in
// Claude's JSONL store. Bug we hit: tab.claudeSessionId could be stale (we
// captured it once, but Claude later forgot the conversation — the JSONL
// either doesn't exist or only has our own metadata records). Without this
// check `query({resume: <staleId>})` rejects with "No conversation found".
//
// Heuristic: file exists AND contains at least one record with a `type` of
// `user` or `assistant`. Our project metadata writes (ai-title, last-prompt,
// queue-operation) DO populate the file but don't make it resumable for SDK.
function isResumableSession(sessionUuid, cwd) {
  if (!sessionUuid) return false;
  try {
    // Use the same materialization contract as PTY/mobile: a UUID or JSONL file
    // is not enough. Resume is allowed only after user-visible Timeline entries
    // exist, which filters out pre-prompt mode/permission metadata files.
    const materialization = getSessionMaterialization(sessionUuid, cwd || process.cwd());
    return materialization?.materialized === true;
  } catch (err) {
    console.warn('[ClaudeSDK] isResumableSession check failed:', err.message);
    return false;
  }
}

// Shared function: start SDK query and stream results to renderer
// Long-lived input channel: query() consumes this AsyncIterable, we can push
// new SDKUserMessages into it at any time (including mid-stream). priority:'next'
// makes the SDK deliver the message at the next block boundary (between tool-use
// sub-iterations) WITHOUT waiting for the full turn to finish — exactly the
// «mid-stream queue» behavior the native CLI offers via stdin priority. See
// node_modules/@anthropic-ai/claude-agent-sdk/sdk.d.ts:2248-2281 +
// packages/claude-code-src/query.ts:1566-1590 (mid-chain drain).
function createInputChannel(initialMsg, debugTag = '?', onConsumed = null) {
  const buffer = initialMsg ? [initialMsg] : [];
  let signal = null;
  let wakeUp = null;
  let ended = false;
  let yieldedCount = 0;
  let pushedCount = initialMsg ? 1 : 0;
  const makeSignal = () => { signal = new Promise(r => { wakeUp = r; }); };
  makeSignal();
  const log = (m) => console.log('[Channel:' + debugTag + '] ' + m);
  log('created initialMsg=' + (initialMsg ? 'YES' : 'NO') + ' bufLen=' + buffer.length);
  const iterable = (async function* () {
    log('iterable START');
    while (true) {
      while (buffer.length > 0) {
        const m = buffer.shift();
        if (m === null) { log('iterable: end sentinel, return'); return; }
        yieldedCount++;
        const preview = m && m.message && m.message.content && m.message.content[0] && m.message.content[0].text ? m.message.content[0].text.slice(0, 40) : '?';
        const prio = m && m.priority ? m.priority : 'none';
        log('iterable: YIELD #' + yieldedCount + ' prio=' + prio + ' text="' + preview + '" bufRemaining=' + buffer.length);
        yield m;
        log('iterable: returned from yield #' + yieldedCount + ' bufLen=' + buffer.length + ' pushed=' + !!m.__pushed);
        // Fire consumed callback for mid-stream pushed messages (NOT for the
        // initial msg which seeds the query). SDK's `for await` resumed past
        // `yield m` ⇒ it has the msg in hand and is about to enqueue it into
        // the API stream. This is the closest moment we have to «attachment
        // recorded in JSONL» — promote the chip→bubble here.
        if (m.__pushed && onConsumed) {
          try {
            onConsumed(m);
          } catch (cbErr) {
            log('onConsumed callback threw: ' + (cbErr && cbErr.message ? cbErr.message : cbErr));
          }
        }
      }
      if (ended) { log('iterable: ended=true, return'); return; }
      log('iterable: AWAIT (no buffer)');
      await signal;
      log('iterable: AWAIT resolved, makeSignal next');
      makeSignal();
    }
  })();
  return {
    iterable,
    push(msg) {
      if (ended) {
        log('push REJECTED: channel ended');
        return;
      }
      pushedCount++;
      const preview = msg && msg.message && msg.message.content && msg.message.content[0] && msg.message.content[0].text ? msg.message.content[0].text.slice(0, 40) : '?';
      const prio = msg && msg.priority ? msg.priority : 'none';
      log('push #' + pushedCount + ' prio=' + prio + ' text="' + preview + '" bufBefore=' + buffer.length + ' hadWaiter=' + !!wakeUp);
      try { msg.__pushed = true; } catch {}
      buffer.push(msg);
      const w = wakeUp;
      makeSignal();
      if (w) w();
      log('push: complete bufAfter=' + buffer.length);
    },
    end() {
      if (ended) return;
      ended = true;
      log('end() called');
      buffer.push(null);
      const w = wakeUp;
      makeSignal();
      if (w) w();
    },
  };
}

// Build the initial SDKUserMessage that opens a fresh query.
function buildUserMessage(text, priority) {
  return {
    type: 'user',
    message: { role: 'user', content: [{ type: 'text', text: String(text || '') }] },
    parent_tool_use_id: null,
    ...(priority ? { priority } : {}),
  };
}

// JSONL tail watcher — tracks per-tab session JSONL file growth and reports
// when an `attachment` record with `type:'queued_command'` lands. This is the
// authoritative moment a mid-stream pushed message becomes visible in Claude's
// transcript (and therefore the correct position to promote the QUEUED chip
// into the user-facing thread). Lifecycle: started/refreshed by `sdkStartQuery`
// once sessionId is known, stopped in `finally`. Independent of any other
// JSONL reader in main — we use a dedicated `fs.watch` and incremental tail
// reads (NOT the shared `_jsonlCache` Timeline uses, to avoid cross-talking
// with concurrent timeline refreshes that snapshot pre-await cache state).
const jsonlWatchers = new Map(); // tabId → { watcher, filePath, lastSize, leftover }

function _watcherLog(tabId, msg) {
  console.log('[SDK:JsonlWatch:' + tabId.slice(-8) + '] ' + msg);
}

async function _processJsonlTail(tabId, w, win) {
  // Read from lastSize to current file size, split on newlines, parse JSON,
  // look for queued_command attachments. Each found landing emits an IPC
  // event with the attachment text — renderer matches against its pending
  // mid-stream queue and promotes the matching chip.
  let stat;
  try { stat = await fs.promises.stat(w.filePath); }
  catch (e) { _watcherLog(tabId, 'stat failed: ' + e.message); return; }
  if (stat.size <= w.lastSize) return; // truncate or no growth
  const prevSize = w.lastSize;
  const prevLeftover = w.leftover || '';
  w.lastSize = stat.size; // claim range upfront so next change event is queued behind us
  let fd;
  try {
    fd = await fs.promises.open(w.filePath, 'r');
    const length = stat.size - prevSize;
    const buf = Buffer.allocUnsafe(length);
    const { bytesRead } = await fd.read(buf, 0, length, prevSize);
    const chunk = prevLeftover + buf.slice(0, bytesRead).toString('utf8');
    const lines = chunk.split('\n');
    w.leftover = lines.pop() || ''; // last fragment may be incomplete
    for (const line of lines) {
      if (!line.trim()) continue;
      let rec;
      try { rec = JSON.parse(line); } catch { continue; }
      if (!rec) continue;

      // Interrupt marker: the CLI writes `[Request interrupted by user]` as a
      // type:'user' single-text record when WE call query.interrupt() on stop.
      // It is shaped IDENTICALLY to a Path-B sdk-cli mid-stream push, so it
      // MUST be matched first and skipped — otherwise it gets mis-promoted as a
      // queued chip. Emit a dedicated event so a live stop (no reload) can also
      // anchor the durable «stopped» badge by parentUuid. (On reopen, loadHistory
      // re-derives the same flag from this record.)
      if (rec.type === 'user') {
        const c = rec.message && rec.message.content;
        let mtext = null;
        if (typeof c === 'string') mtext = c;
        else if (Array.isArray(c) && c.length === 1 && c[0] && c[0].type === 'text') mtext = c[0].text;
        if (mtext != null && INTERRUPT_TEXTS.has(String(mtext).trim())) {
          _watcherLog(tabId, 'interrupt marker landed uuid=' + (rec.uuid || '?').slice(-12) + ' parent=' + String(rec.parentUuid || '').slice(-12));
          if (win && !win.isDestroyed()) {
            win.webContents.send('claude-sdk:interrupted', {
              tabId,
              sessionId: rec.sessionId || w.sessionId || null,
              markerUuid: rec.uuid || null,
              parentUuid: rec.parentUuid || null,
              toolUse: String(mtext).includes('for tool use'),
            });
          }
          continue;
        }
      }

      // Path A: classic queued_command attachment record (TypeScript SDK
      // entrypoint: sdk-ts). Earlier Claude Code versions wrote mid-stream
      // pushed messages this way. Modern sdk-cli entrypoint uses Path B.
      if (rec.type === 'attachment' && rec.attachment && rec.attachment.type === 'queued_command') {
        const prompt = rec.attachment.prompt;
        const text = Array.isArray(prompt) && prompt[0] && typeof prompt[0].text === 'string' ? prompt[0].text : '';
        const uuid = rec.uuid || null;
        _watcherLog(tabId, 'landed queued_command uuid=' + (uuid || '?').slice(-12) + ' textLen=' + text.length);
        if (win && !win.isDestroyed()) {
          win.webContents.send('claude-sdk:midstream-jsonl-landed', { tabId, text, attachmentUuid: uuid, ts: Date.now() });
        }
        continue;
      }

      // Path B: plain user-text record with entrypoint:'sdk-cli'. This is
      // what current Claude Code (2.1.150+) writes for SDK mid-stream pushes
      // via streamInput priority:'next'. The record is indistinguishable in
      // shape from a regular user message — the only way to tell it's our
      // mid-stream push is to match by text content. Renderer's pending
      // queue does the text-based match (text → state:'sent' or 'queued'
      // entry). It's resilient to multiple identical pushes because we
      // splice the oldest match.
      if (rec.type === 'user' && rec.entrypoint === 'sdk-cli') {
        let text = null;
        const c = rec.message && rec.message.content;
        if (typeof c === 'string') text = c;
        else if (Array.isArray(c)) {
          const b0 = c.find(b => b && b.type === 'text' && typeof b.text === 'string');
          if (b0) text = b0.text;
        }
        if (text != null) {
          const uuid = rec.uuid || null;
          _watcherLog(tabId, 'landed user-text uuid=' + (uuid || '?').slice(-12) + ' textLen=' + text.length);
          if (win && !win.isDestroyed()) {
            win.webContents.send('claude-sdk:midstream-jsonl-landed', { tabId, text, attachmentUuid: uuid, ts: Date.now() });
          }
        }
      }
    }
  } catch (e) {
    _watcherLog(tabId, 'tail read failed: ' + e.message);
  } finally {
    if (fd) try { await fd.close(); } catch {}
  }
}

function _attachFileWatcher(tabId, w) {
  // Attach a file-level fs.watch on w.filePath. Used both by
  // startJsonlWatcher when the file already exists, and by the
  // directory-watcher fallback after the file is created by CLI.
  try {
    w.watcher = fs.watch(w.filePath, { persistent: false }, () => {
      if (w.debounceTimer) return;
      w.debounceTimer = setTimeout(() => {
        w.debounceTimer = null;
        _processJsonlTail(tabId, w, BrowserWindow.getAllWindows()[0]).catch(e => _watcherLog(tabId, 'process error: ' + e.message));
      }, 30);
    });
    w.watcher.on('error', (err) => _watcherLog(tabId, 'watcher error: ' + err.message));
    _watcherLog(tabId, 'file watcher attached size=' + w.lastSize);
  } catch (e) {
    _watcherLog(tabId, 'fs.watch failed: ' + e.message);
  }
}

function startJsonlWatcher(tabId, sessionId, cwd) {
  const existing = jsonlWatchers.get(tabId);
  if (existing && existing.sessionId === sessionId) return; // already watching this session
  if (existing) stopJsonlWatcher(tabId); // session rotated (e.g. resume)
  if (!sessionId) return;

  // We may know the sessionId before CLI has flushed the JSONL to disk
  // (SDK emits session_id message ~30-100ms before the first file write).
  // Derive the expected path from cwd's project-slug and prefer it. Fall
  // back to scanning all projects if cwd doesn't match a slug.
  const claudeProjectsDir = path.join(os.homedir(), '.claude', 'projects');
  const projectSlug = cwd ? cwd.replace(/\//g, '-') : null;
  const slugDir = projectSlug ? path.join(claudeProjectsDir, projectSlug) : null;
  const slugFile = slugDir ? path.join(slugDir, sessionId + '.jsonl') : null;
  let located;
  try { located = findSessionFile(sessionId, cwd); } catch {}
  const w = {
    sessionId,
    filePath: (located && located.filePath) || slugFile,
    projectDir: (located && located.projectDir) || slugDir,
    lastSize: 0,
    leftover: '',
    watcher: null,
    dirWatcher: null,
    debounceTimer: null,
  };
  if (!w.filePath || !w.projectDir) {
    _watcherLog(tabId, 'cannot derive JSONL path — sessionId=' + sessionId.slice(-12) + ' cwd=' + (cwd || '?') + ', aborting');
    return;
  }
  jsonlWatchers.set(tabId, w);

  // Path A: file already on disk — attach file-watcher immediately.
  if (fs.existsSync(w.filePath)) {
    try { w.lastSize = fs.statSync(w.filePath).size; } catch {}
    _watcherLog(tabId, 'start file=' + w.filePath + ' initSize=' + w.lastSize + ' mode=immediate');
    _attachFileWatcher(tabId, w);
    return;
  }

  // Path B: file doesn't exist yet — watch the parent dir for creation.
  // When the file appears, close dir-watcher, attach file-watcher, do an
  // immediate tail-read to catch initial content (including a
  // queued_command that may have been written before fs.watch armed).
  _watcherLog(tabId, 'start file=' + w.filePath + ' mode=deferred dir=' + w.projectDir);
  if (!fs.existsSync(w.projectDir)) {
    try { fs.mkdirSync(w.projectDir, { recursive: true }); }
    catch (e) { _watcherLog(tabId, 'mkdir projectDir failed: ' + e.message); }
  }
  try {
    const fileBasename = path.basename(w.filePath);
    w.dirWatcher = fs.watch(w.projectDir, { persistent: false }, (_evt, filename) => {
      if (filename !== fileBasename) return;
      if (!fs.existsSync(w.filePath)) return;
      try { w.dirWatcher.close(); } catch {}
      w.dirWatcher = null;
      _watcherLog(tabId, 'JSONL appeared on disk — promoting to file watcher');
      _attachFileWatcher(tabId, w);
      _processJsonlTail(tabId, w, BrowserWindow.getAllWindows()[0]).catch(e => _watcherLog(tabId, 'initial tail-read failed: ' + e.message));
    });
    w.dirWatcher.on('error', (err) => _watcherLog(tabId, 'dir-watcher error: ' + err.message));
  } catch (e) {
    _watcherLog(tabId, 'fs.watch on dir failed: ' + e.message);
    jsonlWatchers.delete(tabId);
  }
}

function stopJsonlWatcher(tabId) {
  const w = jsonlWatchers.get(tabId);
  if (!w) return;
  if (w.debounceTimer) { clearTimeout(w.debounceTimer); w.debounceTimer = null; }
  if (w.watcher) { try { w.watcher.close(); } catch {} }
  if (w.dirWatcher) { try { w.dirWatcher.close(); } catch {} }
  jsonlWatchers.delete(tabId);
  _watcherLog(tabId, 'stop');
}

async function sdkStartQuery(tabId, cwd, prompt, resumeSessionId, model, effort, thinking, wasQueued) {
  // Close existing query if still running (prevents dual streaming loops)
  const existing = sdkSessions.get(tabId);
  if (existing?.query) {
    try { existing.channel?.end?.(); } catch {}
    try { existing.query.close(); } catch {}
    stopJsonlWatcher(tabId);
    sdkSessions.delete(tabId);
  }

  const { query } = await import('@anthropic-ai/claude-agent-sdk');

  const abortController = new AbortController();
  const mcpServers = loadGlobalMcpServers();
  // thinking: 'adaptive' (default — Opus 4.7+, effort drives thinking depth) or 'disabled'.
  // We always set it explicitly so toggling the UI Think pill is observable in JSONL.
  const thinkingMode = thinking === 'disabled' ? 'disabled' : 'adaptive';
  const claudeBin = resolveClaudeBinaryPath();

  // 'ultracode' is NOT a valid --effort value — the CLI's --effort flag is a
  // closed zod enum [low|medium|high|xhigh|max] and rejects 'ultracode' with
  // exit 1 (verified: forensic 2026-05-29 tab-3197). ultracode is a SESSION
  // SETTING (xhigh effort + standing dynamic-workflow orchestration), enabled
  // via the `ultracode` flag in the settings layer, NOT via --effort. So we
  // translate: pick ultracode → send --effort xhigh AND inject ultracode:true
  // through the settings passthrough. (The slash form `/effort ultracode` used
  // by PTY tabs goes through a DIFFERENT, interactive parser that DOES accept
  // it — that's why PTY works and the SDK --effort flag does not.)
  const wantUltracode = effort === 'ultracode';
  const effortFlag = wantUltracode ? 'xhigh' : (effort || 'high');

  // `enableWorkflows` and `ultracode` live in the SDK's Settings schema, NOT in
  // the query() Options type — passing them as top-level options is silently
  // dropped. The settings layer is fed via the `--settings <json>` CLI arg,
  // reachable from query() through extraArgs (doc: "Keys are argument names
  // without --"). extraArgs emit: `--settings {json}`.
  const settingsLayer = { enableWorkflows: true };
  if (wantUltracode) settingsLayer.ultracode = true;

  const options = {
    abortController,
    cwd: cwd || process.cwd(),
    permissionMode: 'bypassPermissions',
    // SDK 0.3.x explicit safety gate — must be true together with
    // bypassPermissions or the CLI rejects the request at handshake.
    allowDangerouslySkipPermissions: true,
    // Interactive AskUserQuestion bridge. Even under bypassPermissions the SDK
    // routes AskUserQuestion through canUseTool, because the CLI's permission
    // resolver returns behavior:'ask' for requiresUserInteraction tools BEFORE
    // the bypass short-circuit (decompile: permissions.ts step 1e precedes 2a).
    // The mere PRESENCE of canUseTool makes the SDK spawn the CLI with
    // `--permission-prompt-tool stdio`; do NOT also set permissionPromptTool
    // (mutually exclusive — SDK throws). For AskUserQuestion we park a Promise
    // and ask the renderer; for EVERY other tool we auto-allow with the original
    // input — the exact no-op equivalent of bypassPermissions, so no regression.
    canUseTool: async (toolName, input, { toolUseID, signal }) => {
      if (toolName !== 'AskUserQuestion') {
        return { behavior: 'allow', updatedInput: input };
      }
      const key = tabId + ':' + toolUseID;
      const win = BrowserWindow.getAllWindows()[0];
      if (win && !win.isDestroyed()) {
        win.webContents.send('claude-sdk:ask-question', {
          tabId, toolUseID, questions: input.questions || [],
        });
        // Reuse the purple awaiting-input glow channel (PTY feature) — keyed by
        // tabId, already consumed in App.tsx / TabBar for any tab.
        win.webContents.send('claude:awaiting-input', { tabId, awaiting: true });
      }
      _webBroadcast(tabId, { type: 'ask-question', source: 'sdk', toolUseID, questions: input.questions || [] });
      console.log('[ClaudeSDK] canUseTool fired tool=AskUserQuestion tab=' + tabId.slice(-12) + ' qs=' + ((input.questions || []).length) + ' toolUseID=' + String(toolUseID).slice(0, 12));
      return await new Promise((resolve) => {
        const onAbort = () => {
          if (!pendingQuestions.has(key)) return;
          pendingQuestions.delete(key);
          // Turn aborted elsewhere (query.interrupt / hard kill) — deny WITHOUT
          // interrupt so we don't double-abort an already-aborting turn.
          resolve({ behavior: 'deny', message: 'Turn aborted before question was answered.' });
          const w2 = BrowserWindow.getAllWindows()[0];
          if (w2 && !w2.isDestroyed()) {
            w2.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
            w2.webContents.send('claude-sdk:question-cancelled', { tabId, toolUseID });
          }
          _webBroadcast(tabId, { type: 'question-cancelled', source: 'sdk', toolUseID });
        };
        try { if (signal) signal.addEventListener('abort', onAbort, { once: true }); } catch {}
        // Store `questions` too so a phone connecting mid-question can be handed
        // the content in the SSE snapshot (getClaudePendingQuestion).
        pendingQuestions.set(key, { resolve, tabId, signal, onAbort, questions: input.questions || [] });
      });
    },
    // Packaged app: rewrite asar→asar.unpacked path. Without this SDK's own
    // resolver hands an asar-wrapped path to child_process.spawn → ENOTDIR.
    ...(claudeBin ? { pathToClaudeCodeExecutable: claudeBin } : {}),
    model: model || undefined,
    effort: effortFlag,
    thinking: { type: thinkingMode },
    mcpServers,
    // SDK 0.3.x background-task surface: opt-in to AI-generated summaries on
    // task_progress events and live subagent text-deltas. Without these flags
    // the iterator emits only task_started/task_notification (start+end), no
    // mid-flight status. We surface the live data in BackgroundTasksBar +
    // TaskDetailPane, so the renderer wants the full stream.
    agentProgressSummaries: true,
    forwardSubagentText: true,
    // Workflows feature + (optionally) ultracode, fed through the settings layer.
    extraArgs: { settings: JSON.stringify(settingsLayer) },
  };
  if (wantUltracode) console.log('[ClaudeSDK] ultracode ON tab=' + tabId.slice(-8) + ' → effort=xhigh + settings.ultracode=true');
  // Resume only if the session JSONL actually has a resumable conversation.
  // Caller-supplied `resumeSessionId` can be stale (caller is renderer/mobile
  // reading from store/cache that hasn't seen Claude's session-rotation).
  // Without this guard SDK throws "No conversation found with session ID".
  if (resumeSessionId && isResumableSession(resumeSessionId, cwd)) {
    options.resume = resumeSessionId;
  } else if (resumeSessionId) {
    console.warn('[ClaudeSDK] stale resumeSessionId ' + resumeSessionId.slice(0, 8) + ' — JSONL missing or empty, starting fresh');
    resumeSessionId = null;
  }

  // Open a long-lived input channel. First message is the initial prompt with
  // no priority (it opens the conversation, not mid-stream). Subsequent pushes
  // use priority:'next' to land at the next block boundary mid-stream.
  // Warm-start: prompt === null means "boot the process and PARK it idle"
  // (clicking the ОСТАНОВЛЕН chip). The channel opens with NO seed message — the
  // CLI subprocess spawns and waits; the first real prompt arrives later via
  // mid-stream push. Verified on 2.1.156 (2026-05-29): with options.resume set,
  // the warm process keeps full memory + the same JSONL on the first pushed turn.
  const isWarmStart = prompt == null;
  const initialMsg = isWarmStart ? null : buildUserMessage(prompt);
  const channelTag = tabId.slice(-8) + '-' + Date.now().toString().slice(-4);
  // onConsumed fires the instant SDK pulled a *pushed* message out of the
  // channel — that is the closest signal we have to «attachment now landed in
  // JSONL at this position». Renderer uses it to promote the QUEUED chip into
  // the visual thread at the correct position (after the current tool/turn
  // block, not at the moment the chip was created). This matches what native
  // Claude TUI does and what users see when they later open the JSONL.
  const channel = createInputChannel(initialMsg, channelTag, (consumedMsg) => {
    try {
      const win = BrowserWindow.getAllWindows()[0];
      if (!win || win.isDestroyed()) return;
      const text = consumedMsg && consumedMsg.message && Array.isArray(consumedMsg.message.content) && consumedMsg.message.content[0] && consumedMsg.message.content[0].text
        ? consumedMsg.message.content[0].text
        : '';
      console.log('[ClaudeSDK] midstream-consumed tabId=' + tabId.slice(-12) + ' textLen=' + text.length);
      win.webContents.send('claude-sdk:midstream-consumed', { tabId, text, ts: Date.now() });
    } catch (cbErr) {
      console.warn('[ClaudeSDK] midstream-consumed broadcast failed:', cbErr && cbErr.message ? cbErr.message : cbErr);
    }
  });
  const q = query({ prompt: channel.iterable, options });
  const session = {
    query: q,
    abortController,
    sessionId: resumeSessionId || null,
    cwd: cwd || process.cwd(),
    channel,
    // Set true by the 'claude-sdk:stop' handler right before query.interrupt().
    // A graceful interrupt makes the CLI emit a synthetic result with
    // subtype:'error_during_execution' (the [ede_diagnostic] result_type=user
    // shape) and then throw the same as a string error. That is the EXPECTED
    // shape of a user stop — NOT a real failure — so the stream loop below
    // suppresses both (no error toast, no duplicate error result) when this
    // flag is set. The durable «stopped» badge comes from the JSONL marker the
    // CLI writes on interrupt, independent of what the stream forwards.
    userInterrupted: false,
    // push(text) — пихаем сообщение в живой query. SDK его доставит между
    // блоками текущего turn'а (т.е. на следующей границе sub-iteration —
    // после очередного thinking/text/tool_use блока). См. query.ts:1566.
    push(text) {
      channel.push(buildUserMessage(text, 'next'));
    },
  };
  sdkSessions.set(tabId, session);

  // If we already know the sessionId (resume path), arm the JSONL watcher
  // now — we won't get a fresh `sessionId captured` event since session.sessionId
  // was set at construction. Without this, mid-stream pushes that land
  // immediately into the resumed turn never get their `landed` event.
  if (resumeSessionId) {
    try { startJsonlWatcher(tabId, resumeSessionId, session.cwd); }
    catch (e) { console.warn('[ClaudeSDK] startJsonlWatcher (resume) failed: ' + e.message); }
  }

  console.log('[ClaudeSDK] query started tabId=' + tabId + (resumeSessionId ? ' resume=' + resumeSessionId : ' new'));
  // Process-alive signal (single source for the control-bar indicator AND the
  // tab activity plate). alive=true the moment a query exists; alive=false only
  // when the stream loop's finally tears down (hard kill / natural end / tab
  // close). A soft interrupt does NOT end the loop, so the process stays alive
  // between turns — that's the «Активен» (idle) state.
  {
    const win = BrowserWindow.getAllWindows()[0];
    if (win && !win.isDestroyed()) win.webContents.send('claude-sdk:process-state', { tabId, alive: true });
  }
  // Mirror busy state and the user's prompt to phone clients (they need to
  // render the user-message bubble too — local renderer does it from its own
  // state, but the phone has no such state without help). SKIP on warm-start:
  // there is no prompt and no turn — the process is just parked idle, so a
  // busy:true + empty user-bubble would be a lie.
  if (!isWarmStart) {
    _webBroadcast(tabId, { type: 'busy', busy: true });
    _webBroadcast(tabId, {
      type: 'message',
      sessionId: resumeSessionId || null,
      message: {
        type: 'user',
        message: { role: 'user', content: [{ type: 'text', text: typeof prompt === 'string' ? prompt : '' }] },
        __webSynthetic: true,
        // wasQueued — desktop отправил из type-ahead очереди. Прокидываем флаг
        // в WS-payload → mobile reducer пометит entry, EntryView отрендерит
        // "queued" chip. Live-only; reload истории на мобиле потеряет флаг
        // (Anthropic JSONL не хранит UI-метаданные — mirror desktop behavior).
        __wasQueued: !!wasQueued,
      },
    });
  }

  // Stream messages to renderer (fire-and-forget)
  (async () => {
    try {
      let staleResumeRetry = null; // { reason, originalSessionId } if recovery needed
      for await (const message of q) {
        const win = BrowserWindow.getAllWindows()[0];
        if (!win || win.isDestroyed()) break;

        // [Workflow] Concise trace of workflow lifecycle events only — kept
        // (not full-dump scaffolding) because the workflow_progress[] shape is
        // undocumented and we want a breadcrumb if a future SDK changes it.
        // Enable verbose per-message dump with NOTED_DEBUG_SDK_STREAM=1.
        try {
          const m = message;
          if (process.env.NOTED_DEBUG_SDK_STREAM === '1') {
            console.log('[BgProbe] tabId=' + tabId.slice(-12) + ' ' + m?.type + '/' + (m?.subtype || '') + ' keys=' + Object.keys(m || {}).join(','));
            if (m?.type === 'system') console.log('[BgProbe] SYSTEM_FULL=' + JSON.stringify(m).slice(0, 800));
          }
          if (m?.type === 'system' && m?.subtype === 'task_started' && m?.task_type === 'local_workflow') {
            console.log('[Workflow] started tab=' + tabId.slice(-8) + ' name=' + (m.workflow_name || '∅') + ' id=' + String(m.task_id).slice(-6));
          } else if (m?.type === 'system' && m?.subtype === 'task_progress' && Array.isArray(m?.workflow_progress)) {
            const agents = m.workflow_progress.filter(w => w?.type === 'workflow_agent');
            const phases = m.workflow_progress.filter(w => w?.type === 'workflow_phase');
            const states = agents.map(a => a.label + ':' + a.state).join(',');
            console.log('[Workflow] progress tab=' + tabId.slice(-8) + ' phases=' + phases.length + ' agents=' + agents.length + (states ? ' [' + states.slice(0, 200) + ']' : ''));
          }
        } catch (e) {
          console.warn('[Workflow] log failed:', e.message);
        }

        // Capture sessionId from first message that has it
        if (message.session_id && !session.sessionId) {
          session.sessionId = message.session_id;
          console.log('[ClaudeSDK] sessionId captured: ' + session.sessionId);
          // Start tail-watcher on this session's JSONL — this is the
          // earliest moment we have a real sessionId to locate the file.
          // Subsequent mid-stream pushes use the already-running watcher.
          try { startJsonlWatcher(tabId, session.sessionId, session.cwd); }
          catch (e) { console.warn('[ClaudeSDK] startJsonlWatcher failed: ' + e.message); }
        } else if (message.session_id && session.sessionId && message.session_id !== session.sessionId) {
          // Session rotation (e.g. mid-stream /compact). Restart watcher on
          // the new file so subsequent queued_command attachments land at
          // the new transcript.
          const oldSid = session.sessionId;
          session.sessionId = message.session_id;
          console.log('[ClaudeSDK] sessionId rotated ' + oldSid.slice(-12) + ' → ' + session.sessionId.slice(-12));
          try { startJsonlWatcher(tabId, session.sessionId, session.cwd); }
          catch (e) { console.warn('[ClaudeSDK] startJsonlWatcher (rotation) failed: ' + e.message); }
        }

        // Detect "stale resume" error: SDK delivers it as a regular result
        // event rather than throwing. Pattern: type=result, subtype=error,
        // result text contains "No conversation found". On match, drop the
        // error from UI, retry the original prompt without resume.
        const isStaleResume = message?.type === 'result'
          && (message.subtype === 'error' || message.is_error)
          && /No conversation found/i.test(String(message.result || ''));
        if (isStaleResume && resumeSessionId) {
          console.warn('[ClaudeSDK] stale resume detected mid-stream: ' + resumeSessionId.slice(0, 8) + ' — will retry without resume');
          staleResumeRetry = { reason: 'stale-resume', originalSessionId: resumeSessionId };
          // Don't forward the error event — UI gets a clean retry instead.
          break;
        }

        // Expected interrupt fallout: once WE called query.interrupt() (user
        // stop), the CLI emits a result{subtype:'error_during_execution'}
        // (the [ede_diagnostic] result_type=user shape) and then throws the
        // same as a string. That is NOT a real error — swallow the result so
        // the renderer doesn't pop a red error toast on every stop. The
        // «stopped» badge is driven by the JSONL marker + the live in-memory
        // flag, not by this result.
        if (session.userInterrupted && message?.type === 'result' && (message.subtype === 'error_during_execution' || message.is_error)) {
          console.log('[ClaudeSDK] suppressing interrupt result (user stop) tabId=' + tabId.slice(-12));
          continue;
        }

        win.webContents.send('claude-sdk:message', { tabId, message, sessionId: session.sessionId || message.session_id });
        _webBroadcast(tabId, { type: 'message', message, sessionId: session.sessionId || message.session_id });
      }

      // Run retry AFTER the iterator closes naturally (SDK iterator is in a
      // weird state if we throw out of it). New query with the SAME prompt,
      // no resume → Claude starts fresh, user sees the prompt go through.
      if (staleResumeRetry) {
        sdkSessions.delete(tabId);
        // Notify renderer to clear stale tab.claudeSessionId so future
        // prompts don't replay the same stale-resume cycle.
        const win = BrowserWindow.getAllWindows()[0];
        if (win && !win.isDestroyed()) {
          win.webContents.send('claude-sdk:stale-resume-cleared', { tabId, staleSessionId: staleResumeRetry.originalSessionId });
        }
        await sdkStartQuery(tabId, cwd, prompt, null, model, effort, thinking);
        return;
      }
    } catch (err) {
      // A graceful user interrupt makes the SDK iterator THROW
      // "Claude Code returned an error result: [ede_diagnostic] result_type=user …"
      // (it surfaces the same ede_diagnostic result as a thrown error). When WE
      // initiated the stop, that throw is expected — don't forward it as a real
      // error. AbortError (our abortController) is likewise expected.
      if (err.name !== 'AbortError' && !session.userInterrupted) {
        console.error('[ClaudeSDK] stream error:', err.message);
        const win = BrowserWindow.getAllWindows()[0];
        const errorMsg = { type: 'result', subtype: 'error', result: String(err.message || err), is_error: true };
        if (win && !win.isDestroyed()) {
          win.webContents.send('claude-sdk:message', { tabId, sessionId: session.sessionId, message: errorMsg });
        }
        _webBroadcast(tabId, { type: 'message', sessionId: session.sessionId, message: errorMsg });
      } else if (session.userInterrupted) {
        console.log('[ClaudeSDK] stream loop ended via user interrupt (expected) tabId=' + tabId.slice(-12));
      }
    } finally {
      try { session.channel?.end?.(); } catch {}
      // One final tail-read before tearing down: catches queued_command
      // attachments that landed in JSONL after our last fs.watch event but
      // before stream end. Without this, a chip can hang permanently if the
      // final flush from CLI happened between two debounce ticks.
      try {
        const w = jsonlWatchers.get(tabId);
        if (w) {
          await _processJsonlTail(tabId, w, BrowserWindow.getAllWindows()[0]);
        }
      } catch (e) {
        console.warn('[ClaudeSDK] final tail-read failed: ' + e.message);
      }
      stopJsonlWatcher(tabId);
      sdkSessions.delete(tabId);
      // Resolve any AskUserQuestion parked for this tab — the stream (and the CLI
      // subprocess that owns the control request) is gone, so the Promise would
      // leak otherwise. deny WITHOUT interrupt (the turn is already ending).
      for (const [k, p] of pendingQuestions) {
        if (p.tabId !== tabId) continue;
        try { if (p.signal && p.onAbort) p.signal.removeEventListener('abort', p.onAbort); } catch {}
        pendingQuestions.delete(k);
        try { p.resolve({ behavior: 'deny', message: 'Session ended before question was answered.' }); } catch {}
      }
      _webBroadcast(tabId, { type: 'question-cancelled', source: 'sdk' });
      const win = BrowserWindow.getAllWindows()[0];
      if (win && !win.isDestroyed()) {
        win.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
        win.webContents.send('claude-sdk:question-cancelled', { tabId });
        win.webContents.send('claude-sdk:done', { tabId, sessionId: session.sessionId });
        // Process truly gone — the loop ended (hard kill / natural completion /
        // tab close). Soft interrupt never reaches here (loop keeps iterating).
        win.webContents.send('claude-sdk:process-state', { tabId, alive: false });
      }
      _webBroadcast(tabId, { type: 'busy', busy: false });
      _webBroadcast(tabId, { type: 'done', sessionId: session.sessionId });
      console.log('[ClaudeSDK] stream ended tabId=' + tabId);
    }
  })();

  return session;
}

ipcMain.handle('claude-sdk:create-session', async (event, { tabId, cwd, prompt, model, effort, thinking, wasQueued }) => {
  console.log('[ClaudeSDK] create-session tabId=' + tabId + ' cwd=' + cwd + ' effort=' + effort + ' thinking=' + thinking + (wasQueued ? ' wasQueued=true' : ''));
  try {
    await sdkStartQuery(tabId, cwd, prompt, null, model, effort, thinking, !!wasQueued);
    return { success: true };
  } catch (err) {
    console.error('[ClaudeSDK] create-session failed:', err.message);
    return { success: false, error: String(err.message || err) };
  }
});

// Warm-start: boot the CLI process and PARK it idle WITHOUT sending a prompt.
// Backs the ОСТАНОВЛЕН-chip click — the user wants the process to come alive
// («активен») deterministically on click, not only after the first message.
// prompt:null → sdkStartQuery opens an empty channel; the process spawns, the
// stream loop parks, process-state alive:true fires. With resumeSessionId the
// warm process keeps full memory + the same JSONL on the first pushed turn
// (verified 2026-05-29). No-op if a session is already live for this tab.
ipcMain.handle('claude-sdk:warm-start', async (event, { tabId, cwd, model, effort, thinking, resumeSessionId }) => {
  if (sdkSessions.has(tabId)) {
    console.log('[ClaudeSDK] warm-start skipped — session already live tabId=' + tabId.slice(-12));
    return { success: true, alreadyAlive: true };
  }
  console.log('[ClaudeSDK] warm-start tabId=' + tabId + ' resume=' + (resumeSessionId ? resumeSessionId.slice(0, 8) : 'NEW'));
  try {
    await sdkStartQuery(tabId, cwd, null, resumeSessionId || null, model, effort, thinking, false);
    return { success: true };
  } catch (err) {
    console.error('[ClaudeSDK] warm-start failed:', err.message);
    return { success: false, error: String(err.message || err) };
  }
});

ipcMain.handle('claude-sdk:send-message', async (event, { tabId, cwd, prompt, model, effort, thinking, resumeSessionId, wasQueued }) => {
  // Resume priority (high → low):
  //   1) caller-supplied `resumeSessionId` — comes from store/cache (persistent)
  //   2) `sdkSessions.get(tabId).sessionId` — only set during an ACTIVE stream;
  //      the Map is wiped in the `finally` of sdkStartQuery, so this only ever
  //      matches if the user fires send-message while a previous turn is still
  //      streaming (rare race).
  //
  // Why caller-supplied first: the in-memory Map cleared between turns, so
  // before this fix every turn started with `?--resume=null` → fresh JSONL,
  // fresh sessionId, Claude with no memory of the previous turn. Logs showed
  // every `query started` line as `new` (never `resume=...`), one new UUID per
  // turn even when 5 prompts arrived back-to-back to the same tab.
  // See knowledge/fix-sdk-session-amnesia.md.
  const existingSession = sdkSessions.get(tabId);

  // Mid-stream type-ahead path: if a query is already running for this tab,
  // PUSH the message into the live input channel with priority:'next'. SDK
  // delivers it at the next block boundary (between thinking/text/tool_use
  // sub-iterations of the current turn) — no need to wait for the full
  // `result` event. This is what the user means by «дожидается окончания
  // блока, потом сразу отправляется». See createInputChannel + buildUserMessage.
  if (existingSession && existingSession.push) {
    console.log('[ClaudeSDK] mid-stream push tabId=' + tabId + ' wasQueued=' + !!wasQueued + ' len=' + (prompt ? prompt.length : 0));
    // New turn on a parked (soft-interrupted) session: clear the interrupt flag
    // so this turn's result is NOT swallowed as "expected interrupt fallout".
    // Without this, a genuine error in the next turn would be silently dropped.
    existingSession.userInterrupted = false;
    try {
      existingSession.push(prompt);
      // Broadcast user-bubble immediately to phone clients (renderer пушит
      // свой bubble отдельно через onNew). Без этого мобайл бы не показал
      // user-message пока SDK сам не запишет его в JSONL.
      _webBroadcast(tabId, {
        type: 'message',
        sessionId: existingSession.sessionId || null,
        message: {
          type: 'user',
          message: { role: 'user', content: [{ type: 'text', text: typeof prompt === 'string' ? prompt : '' }] },
          __webSynthetic: true,
          __wasQueued: !!wasQueued,
        },
      });
      return { success: true, midStream: true };
    } catch (err) {
      console.error('[ClaudeSDK] mid-stream push failed:', err.message);
      // Fall through to a fresh sdkStartQuery as recovery
    }
  }

  const resumeFromStore = resumeSessionId || null;
  const resumeFromActive = existingSession?.sessionId || null;
  const resumeId = resumeFromStore || resumeFromActive;
  console.log('[ClaudeSDK] send-message tabId=' + tabId + ' effort=' + effort + ' thinking=' + thinking + ' resume=' + (resumeId ? resumeId.slice(0, 8) : 'NEW') + ' source=' + (resumeFromStore ? 'caller' : resumeFromActive ? 'active' : 'none') + (wasQueued ? ' wasQueued=true' : ''));

  try {
    await sdkStartQuery(
      tabId,
      cwd || existingSession?.cwd,
      prompt,
      resumeId,
      model, effort, thinking,
      !!wasQueued,
    );
    return { success: true };
  } catch (err) {
    console.error('[ClaudeSDK] send-message failed:', err.message);
    return { success: false, error: String(err.message || err) };
  }
});

// Forward SDK busy state to TabBar via existing claude:busy-state channel
ipcMain.on('claude-sdk:busy-state', (event, { tabId, busy, reason }) => {
  // Activity tracking — for SDK tabs this is the ONLY busy signal (no PTY,
  // no spinner heuristic, no Stop hook). Idempotent recorder.
  recordActivity(tabId, busy, 'claude-sdk');
  const win = BrowserWindow.getAllWindows()[0];
  if (win && !win.isDestroyed()) {
    win.webContents.send('claude:busy-state', { tabId, busy, reason });
  }
});

// Load session history from JSONL (for converted/restored SDK tabs)
ipcMain.handle('claude-sdk:load-history', async (event, { sessionId, cwd }) => {
  console.log('[ClaudeSDK] load-history sessionId=' + sessionId + ' cwd=' + cwd);
  try {
    const { getSessionMessages } = await import('@anthropic-ai/claude-agent-sdk');
    // Try with dir first, then without (searches all projects)
    let msgs = await getSessionMessages(sessionId, { dir: cwd || undefined });
    if (msgs.length === 0 && cwd) {
      console.log('[ClaudeSDK] load-history: 0 with dir, retrying without dir...');
      msgs = await getSessionMessages(sessionId);
    }
    console.log('[ClaudeSDK] loaded ' + msgs.length + ' messages for ' + sessionId.slice(0, 8));
    return { success: true, messages: msgs };
  } catch (err) {
    console.error('[ClaudeSDK] load-history failed:', err.message);
    return { success: false, error: String(err.message || err), messages: [] };
  }
});

function clearClaudeAwaitingQuestion(tabId, reason) {
  if (!tabId) return;
  const wasAwaiting = !!claudeAwaitingInput.get(tabId);
  if (!wasAwaiting) return;
  claudeAwaitingInput.set(tabId, false);
  const win = BrowserWindow.getAllWindows()[0];
  if (win && !win.isDestroyed()) win.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
  console.log('[ClaudeQuestion] awaiting cleared tab=' + tabId.slice(-12) + ' reason=' + reason);
}

// ── Answer a PTY-Claude AskUserQuestion by driving the Ink TUI keystrokes ────
// PTY-Claude renders its question picker in the xterm (Ink CustomSelect). There
// is NO IPC answer path like SDK's parked canUseTool — the desktop user answers
// by literally pressing arrows + Enter in the terminal. So to answer from mobile
// we synthesise the same keystrokes into the PTY.
//
// Ink navigation (decompiled QuestionView.tsx / AskUserQuestionPermissionRequest.tsx):
//   • Options are a vertical list; cursor starts at index 0. ↓ (\x1b[B) moves down.
//   • Enter (\r) on a single-select option picks it AND advances to the next
//     question (or submits when it's the only/last and hideSubmitTab is true).
//   • hideSubmitTab = (questions.length === 1 && !multiSelect) → one plain
//     question auto-submits on Enter, no Submit view.
//   • multiSelect: Space toggles the focused option; you then →/Submit to finish.
//   • Esc (\x1b) cancels the whole question (= "respond to Claude manually").
//
// We support the common cases deterministically: single-select (one Enter per
// question after ↓-navigating to the chosen option) and multiSelect (Space on
// each chosen option, then advance). For ≥2 questions we answer each in order;
// the final Enter lands on / confirms the Submit view. Best-effort with small
// inter-keystroke delays so Ink processes each event (it batches stdin per frame).
async function answerClaudeQuestionPTY(tabId, answers) {
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no_terminal' };
  const pending = claudePendingQuestion.get(tabId);
  if (!pending) return { success: false, error: 'no_pending_question' };
  const questions = pending.questions || [];
  const KEY = { down: '\x1b[B', up: '\x1b[A', right: '\x1b[C', enter: '\r', space: ' ', esc: '\x1b' };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const press = async (seq, gap = 70) => { term.write(seq); await sleep(gap); };
  try {
    for (let qi = 0; qi < questions.length; qi++) {
      const q = questions[qi];
      const opts = Array.isArray(q.options) ? q.options : [];
      // answers is keyed by question text; value is a single label (single-select)
      // or comma-joined labels (multiSelect), matching the SDK answers schema.
      const want = answers[q.question];
      const wantLabels = typeof want === 'string'
        ? want.split(',').map((s) => s.trim()).filter(Boolean)
        : (Array.isArray(want) ? want : []);
      if (q.multiSelect) {
        // Walk top→bottom, Space-toggle each wanted option. Cursor starts at 0.
        for (let oi = 0; oi < opts.length; oi++) {
          if (wantLabels.includes(opts[oi].label)) await press(KEY.space);
          if (oi < opts.length - 1) await press(KEY.down);
        }
        // Advance to next question / submit tab.
        await press(KEY.right, 90);
      } else {
        // Single-select: ↓ to the chosen index, then Enter (picks + advances).
        const idx = Math.max(0, opts.findIndex((o) => wantLabels.includes(o.label)));
        for (let s = 0; s < idx; s++) await press(KEY.down);
        await press(KEY.enter, 110);
      }
    }
    // For multi-question or multiSelect, a final Enter confirms the Submit view.
    // (Single plain question already auto-submitted via the Enter above —
    // hideSubmitTab. An extra Enter there would land in the freed composer; to
    // avoid a stray newline we only send it when a Submit view is expected.)
    const needsSubmitEnter = questions.length > 1 || questions.some((q) => q.multiSelect);
    if (needsSubmitEnter) await press(KEY.enter, 110);
    console.log('[ClaudeQuestion] PTY answered tab=' + tabId.slice(-12) + ' qs=' + questions.length + ' submitEnter=' + needsSubmitEnter);
    // Clear our stored pending — PostToolUse(AskUserQuestion) will also fire and
    // broadcast, this just makes the map honest immediately.
    claudePendingQuestion.delete(tabId);
    return { success: true };
  } catch (e) {
    console.error('[ClaudeQuestion] PTY answer failed:', e.message);
    return { success: false, error: String(e.message || e) };
  }
}

// Cancel a PTY question (mobile "Type something / Stop") = Esc into the TUI →
// Claude stops asking and returns to the prompt for free-text. Mirrors the SDK
// stop path semantically.
async function stopClaudeQuestionPTY(tabId) {
  const term = terminals.get(tabId);
  if (!term) return { success: false, error: 'no_terminal' };
  try {
    term.write('\x1b'); // Esc — onCancel in QuestionView
    claudePendingQuestion.delete(tabId);
    _webBroadcast(tabId, { type: 'question-cancelled', source: 'pty' });
    console.log('[ClaudeQuestion] PTY stopped (Esc) tab=' + tabId.slice(-12));
    return { success: true };
  } catch (e) {
    return { success: false, error: String(e.message || e) };
  }
}

// Unified answer entrypoint used by the web-server (mobile). Routes by source:
//   • 'sdk' → resolve the parked canUseTool Promise (same as desktop SDKAskQuestion).
//   • 'pty' → drive the Ink TUI keystrokes (answer) or Esc (stop).
// Returns { success }.
async function answerClaudeQuestionUnified({ tabId, source, toolUseID, questions, answers, stop }) {
  if (source === 'pty') {
    const result = stop ? await stopClaudeQuestionPTY(tabId) : await answerClaudeQuestionPTY(tabId, answers || {});
    if (result?.success) clearClaudeAwaitingQuestion(tabId, stop ? 'pty-stop' : 'pty-answer');
    return result;
  }
  // SDK: reuse the existing parked-Promise resolver via the same code the IPC
  // handler runs. We replicate its core here (the IPC handler is renderer-only).
  const key = tabId + ':' + toolUseID;
  const p = pendingQuestions.get(key);
  if (!p) return { success: false, error: 'not-pending' };
  try { if (p.signal && p.onAbort) p.signal.removeEventListener('abort', p.onAbort); } catch {}
  pendingQuestions.delete(key);
  if (stop) {
    const session = sdkSessions.get(tabId);
    if (session) session.userInterrupted = true;
    p.resolve({ behavior: 'deny', message: 'User chose to respond manually.', interrupt: true });
  } else {
    const updatedInput = { questions: questions || [], answers: answers || {} };
    p.resolve({ behavior: 'allow', updatedInput });
  }
  const win = BrowserWindow.getAllWindows()[0];
  if (win && !win.isDestroyed()) win.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
  return { success: true };
}

// Read the current pending question for a tab (SDK or PTY) so the web-server can
// include it in the SSE connect snapshot (phone opened mid-question → still sees it).
function getClaudePendingQuestion(tabId) {
  // PTY store first.
  const pty = claudePendingQuestion.get(tabId);
  if (pty) return { source: 'pty', toolUseID: 'pty', questions: pty.questions || [] };
  // SDK parked promises are keyed `${tabId}:${toolUseID}`.
  for (const [k, p] of pendingQuestions) {
    if (p.tabId !== tabId) continue;
    const toolUseID = k.slice(tabId.length + 1);
    return { source: 'sdk', toolUseID, questions: p.questions || [] };
  }
  return null;
}

ipcMain.handle('claude:get-pending-question', async (_event, { tabId } = {}) => {
  if (!tabId) return { success: false, error: 'tabId required', pendingQuestion: null };
  const pendingQuestion = getClaudePendingQuestion(tabId);
  console.log('[ClaudeQuestion:IPC] get-pending tab=' + tabId.slice(-12) + ' source=' + (pendingQuestion?.source || 'none') + ' qs=' + (pendingQuestion?.questions?.length || 0));
  return { success: true, pendingQuestion };
});

ipcMain.handle('claude:answer-question', async (_event, payload = {}) => {
  const tabId = payload.tabId;
  if (!tabId) return { success: false, error: 'tabId required' };
  const pendingQuestion = getClaudePendingQuestion(tabId);
  const source = payload.source || pendingQuestion?.source;
  console.log('[ClaudeQuestion:IPC] answer tab=' + tabId.slice(-12) + ' source=' + (source || 'none') + ' stop=' + !!payload.stop + ' qs=' + ((payload.questions || pendingQuestion?.questions || []).length) + ' answers=' + Object.keys(payload.answers || {}).length);
  if (!source) return { success: false, error: 'no_pending_question' };
  const result = await answerClaudeQuestionUnified({
    tabId,
    source,
    toolUseID: payload.toolUseID || pendingQuestion?.toolUseID,
    questions: payload.questions || pendingQuestion?.questions || [],
    answers: payload.answers || {},
    stop: !!payload.stop,
  });
  console.log('[ClaudeQuestion:IPC] answer-result tab=' + tabId.slice(-12) + ' success=' + !!result?.success + ' error=' + (result?.error || result?.reason || '-'));
  return result;
});

// Resolve a parked AskUserQuestion (SDK tab). The renderer's <SDKAskQuestion>
// posts either the collected answers or a stop request; we resolve the parked
// canUseTool Promise accordingly and clear the awaiting glow.
//  - answer → { behavior:'allow', updatedInput:{ questions, answers, annotations? } }
//    updatedInput FULLY REPLACES the tool input (queryHelpers.ts:262 — no merge),
//    so we MUST echo `questions` back (the tool's strict schema requires
//    questions.min(1); answers-only would be schema-invalid at tool.call).
//  - stop  → { behavior:'deny', interrupt:true } aborts the whole turn. We set
//    session.userInterrupted=true FIRST so the existing error_during_execution
//    suppression (main.js result-handler) treats it as a user interrupt, not an
//    API error (no red toast). Mirrors the claude-sdk:stop machinery rather than
//    duplicating interrupt detection (CLAUDE.md: «не дублируй детекцию событий»).
ipcMain.handle('claude-sdk:answer-question', async (_e, { tabId, toolUseID, questions, answers, annotations, stop }) => {
  const key = tabId + ':' + toolUseID;
  const p = pendingQuestions.get(key);
  if (!p) {
    console.warn('[ClaudeSDK] answer-question: no pending question for ' + key);
    return { success: false, reason: 'not-pending' };
  }
  // Detach the abort listener so resolving here doesn't race onAbort.
  try { if (p.signal && p.onAbort) p.signal.removeEventListener('abort', p.onAbort); } catch {}
  pendingQuestions.delete(key);

  if (stop) {
    const session = sdkSessions.get(tabId);
    // Pre-mark as user-interrupt so the turn-abort that deny+interrupt triggers
    // is suppressed like a Stop, not surfaced as an error.
    if (session) session.userInterrupted = true;
    p.resolve({ behavior: 'deny', message: 'User chose to respond manually.', interrupt: true });
    console.log('[ClaudeSDK] answer-question STOP tab=' + tabId.slice(-12) + ' toolUseID=' + String(toolUseID).slice(0, 12));
  } else {
    const updatedInput = { questions: questions || [], answers: answers || {} };
    if (annotations && Object.keys(annotations).length) updatedInput.annotations = annotations;
    p.resolve({ behavior: 'allow', updatedInput });
    console.log('[ClaudeSDK] answer-question ANSWERED tab=' + tabId.slice(-12) + ' answers=' + Object.keys(answers || {}).length);
  }
  const win = BrowserWindow.getAllWindows()[0];
  if (win && !win.isDestroyed()) win.webContents.send('claude:awaiting-input', { tabId, awaiting: false });
  return { success: true };
});

// Load a subagent's transcript from its own JSONL (lives at
// ~/.claude/projects/<dir>/<sessionId>/subagents/agent-<agentId>.jsonl).
// Used by TaskDetailPane to render the agent's mini-thread when the user
// expands a running/finished background-agent chip.
ipcMain.handle('claude-sdk:get-subagent-messages', async (event, { sessionId, agentId, cwd }) => {
  if (!sessionId || !agentId) return { success: false, error: 'sessionId and agentId required', messages: [] };
  try {
    const { getSubagentMessages } = await import('@anthropic-ai/claude-agent-sdk');
    let msgs = await getSubagentMessages(sessionId, agentId, { dir: cwd || undefined });
    if ((!msgs || msgs.length === 0) && cwd) {
      msgs = await getSubagentMessages(sessionId, agentId);
    }
    return { success: true, messages: msgs || [] };
  } catch (err) {
    console.error('[ClaudeSDK] get-subagent-messages failed:', err.message);
    return { success: false, error: String(err.message || err), messages: [] };
  }
});

// Read a background-task output file (task_notification.output_file) from
// the given byte offset. Returns { content, size } where size is the new
// file length — caller advances its tail pointer for the next poll. Used by
// TaskDetailPane to live-tail background bash stdout.
ipcMain.handle('claude-sdk:read-background-output', async (event, { path: filePath, offset }) => {
  if (!filePath) return { success: false, error: 'path required', content: '', size: 0 };
  try {
    if (!fs.existsSync(filePath)) return { success: true, content: '', size: 0, missing: true };
    const stat = fs.statSync(filePath);
    const start = Math.max(0, Number(offset) || 0);
    if (start >= stat.size) return { success: true, content: '', size: stat.size };
    const fd = fs.openSync(filePath, 'r');
    try {
      const len = stat.size - start;
      const buf = Buffer.alloc(len);
      fs.readSync(fd, buf, 0, len, start);
      return { success: true, content: buf.toString('utf8'), size: stat.size };
    } finally {
      try { fs.closeSync(fd); } catch {}
    }
  } catch (err) {
    return { success: false, error: String(err.message || err), content: '', size: 0 };
  }
});

// Exposes SDK-shipped model capability table to renderer. Returns
// { [modelId]: ['low','medium','high','xhigh','max'][] }. Renderer uses this
// to gate effort pills per active model and auto-downgrade unsupported pairs.
ipcMain.handle('claude-sdk:get-model-caps', async () => {
  const caps = await loadSdkModelCapabilities();
  return { success: true, caps };
});

// [SlashProbe] Probes Query control-API: shipped slash-commands (with
// aliases), MCP server status, context-usage breakdown. Reuses active
// session's Query when available so result matches THIS session; otherwise
// spawns a throw-away one. Caller dumps result to console — full enumeration
// of what /usage / /status / /cost / /compact resolve to in CLI mode.
ipcMain.handle('claude-sdk:probe-commands', async (event, { tabId }) => {
  console.log('[SlashProbe] probe-commands invoked tabId=' + (tabId || '<none>'));
  try {
    const sdk = await import('@anthropic-ai/claude-agent-sdk');
    let q;
    let spawned = false;
    const active = tabId ? sdkSessions.get(tabId) : null;
    if (active?.query) {
      q = active.query;
      console.log('[SlashProbe] reusing active session query for tabId=' + tabId.slice(-12));
    } else {
      // never-resolves Promise inside the iterator keeps the underlying
      // streaming-input alive for the duration of all three probe calls.
      // Bare `(async function*(){})()` reaches `return` immediately → SDK
      // tears down ProcessTransport between probe calls.
      const neverYield = (async function*() { await new Promise(() => {}); })();
      const claudeBin = resolveClaudeBinaryPath();
      q = sdk.query({
        prompt: neverYield,
        options: {
          allowDangerouslySkipPermissions: true,
          permissionMode: 'bypassPermissions',
          ...(claudeBin ? { pathToClaudeCodeExecutable: claudeBin } : {}),
        },
      });
      spawned = true;
      console.log('[SlashProbe] spawned probe-only query (no active session)');
    }
    const out = {};
    // Sequential awaits — parallel Promise.all crashed because closing the
    // throw-away query (when no active session) tore down ProcessTransport
    // mid-call. supportedCommands resolved first, the other two errored with
    // "Query closed before response received" / "ProcessTransport is not
    // ready". Sequential = each control-request fully completes before next.
    try {
      const cmds = await q.supportedCommands();
      out.commands = cmds;
      console.log('[SlashProbe] supportedCommands count=' + cmds.length + ' names=' + cmds.map(c => '/' + c.name).join(','));
      cmds.forEach(c => {
        const aliases = c.aliases?.length ? ' aliases=[' + c.aliases.map(a => '/' + a).join(',') + ']' : '';
        console.log('[SlashProbe]   /' + c.name + ' — ' + String(c.description || '').slice(0, 100) + aliases);
      });
    } catch (e) {
      console.warn('[SlashProbe] supportedCommands failed:', e?.message);
      out.commandsError = String(e?.message || e);
    }
    try {
      const usage = await q.getContextUsage();
      out.contextUsage = usage;
      console.log('[SlashProbe] contextUsage=' + JSON.stringify(usage).slice(0, 500));
    } catch (e) {
      console.warn('[SlashProbe] getContextUsage failed:', e?.message);
      out.contextUsageError = String(e?.message || e);
    }
    try {
      const mcpStatus = await q.mcpServerStatus();
      out.mcpServerStatus = mcpStatus;
      console.log('[SlashProbe] mcpServerStatus count=' + mcpStatus.length + ' summary=' + mcpStatus.map(s => s.name + ':' + s.status).join(','));
    } catch (e) {
      console.warn('[SlashProbe] mcpServerStatus failed:', e?.message);
      out.mcpServerStatusError = String(e?.message || e);
    }
    if (spawned) {
      try { await q.close(); } catch {}
    }
    return { success: true, ...out };
  } catch (err) {
    console.error('[SlashProbe] probe-commands fatal:', err.message);
    return { success: false, error: String(err.message || err) };
  }
});

// Quick predicate for renderer: is there an active SDK query for this tab?
// Used by truncateAndResend to know whether it needs to stop a live query
// before resending (mid-stream type-ahead would otherwise push into the live
// channel with priority:'next' instead of starting a fresh truncated turn).
ipcMain.handle('claude-sdk:has-active-session', async (event, { tabId }) => {
  const session = sdkSessions.get(tabId);
  return { active: !!session, sessionId: session?.sessionId || null };
});

// TWO distinct stop semantics (matches native Claude Code):
//   • SOFT (default) — "interrupt the current TURN". Like pressing Esc in the
//     native TUI: the foreground answer stops, but the CLI subprocess + session
//     STAY ALIVE and any background workflow agents KEEP RUNNING and will still
//     deliver their task_notification. Proven on CLI 2.1.156 (2026-05-29 live
//     A/B): after query.interrupt() WITHOUT close(), the streaming query parks
//     and a later pushed message runs a fresh turn (session survived). We do
//     NOT abort/close/end-channel/delete — only interrupt() + flush the durable
//     `[Request interrupted by user]` marker via the final tail-read. The
//     stream loop keeps iterating (the ede_diagnostic result is swallowed by
//     the userInterrupted guard), so a background agent's later task_notification
//     still reaches the renderer and flips its chip terminal.
//   • HARD (opts.hard) — "kill the whole session". close() the query (SIGTERM→
//     SIGKILL the one CLI child, which takes all in-process subagents with it),
//     stopTask any tracked tasks first for a clean per-task stopped notification,
//     abort, end the channel, stop the watcher, delete the session. Used by the
//     control-bar kill button, tab close, and Edit/Repeat (JSONL surgery can't
//     run against a live stream).
ipcMain.handle('claude-sdk:stop', async (event, { tabId, runningTaskIds, hard }) => {
  console.log('[ClaudeSDK] stop tabId=' + tabId + ' hard=' + !!hard + ' runningTaskIds=' + JSON.stringify(runningTaskIds || []));
  const session = sdkSessions.get(tabId);
  if (!session) {
    console.warn('[BgProbe:STOP] no active session for tabId=' + tabId.slice(-12));
    return { success: false, error: 'no active session' };
  }
  console.warn('[BgProbe:STOP] found session sid=' + session.sessionId?.slice(0,8) + ' hard=' + !!hard);

  // GRACEFUL INTERRUPT (both paths). query.interrupt() sends a control
  // 'interrupt' request; the CLI runs createUserInterruptionMessage and WRITES
  // the synthetic `[Request interrupted by user]` record to the session JSONL —
  // the durable anchor for the «stopped» badge. (A/B 2026-05-29: interrupt ⇒
  // marker on disk; bare abort()+close() ⇒ no marker.) userInterrupted makes the
  // stream loop swallow the expected ede_diagnostic result instead of toasting.
  session.userInterrupted = true;
  try {
    await session.query.interrupt();
    console.warn('[BgProbe:STOP] interrupt() ok');
  } catch (err) {
    console.warn('[BgProbe:STOP] interrupt() err: ' + err.message);
  }

  // Let the CLI flush the interrupt marker before the tail-read picks it up
  // (interrupt() resolves on control-ack; the disk write lands a few ms later).
  await new Promise(r => setTimeout(r, 150));
  try {
    const w = jsonlWatchers.get(tabId);
    if (w) await _processJsonlTail(tabId, w, BrowserWindow.getAllWindows()[0]);
  } catch (e) {
    console.warn('[ClaudeSDK] final tail-read on stop failed: ' + e.message);
  }

  if (!hard) {
    // SOFT stop done. Session stays parked: do NOT abort/close/end/delete and do
    // NOT stopTask — background agents keep running (native Esc behavior). The
    // stream loop is still iterating; the next prompt resumes this same session
    // via the mid-stream push path. Re-arm userInterrupted=false on the next
    // dispatch (handled in send-message) so real errors aren't swallowed.
    // Turn-level busy is over (mirror to phone); the process stays alive, so we
    // do NOT emit process-state alive:false here.
    _webBroadcast(tabId, { type: 'busy', busy: false });
    console.log('[ClaudeSDK] soft-interrupt complete (session alive) tabId=' + tabId.slice(-12));
    return { success: true, soft: true };
  }

  // HARD stop: tear everything down. stopTask each tracked task first so the CLI
  // emits a clean task_notification{stopped} per task before the transport dies.
  if (Array.isArray(runningTaskIds) && runningTaskIds.length > 0) {
    for (const tid of runningTaskIds) {
      try {
        await session.query.stopTask(tid);
        console.warn('[BgProbe:STOP] stopTask(' + tid.slice(0,8) + ') ok');
      } catch (err) {
        console.warn('[BgProbe:STOP] stopTask(' + tid.slice(0,8) + ') err: ' + err.message);
      }
    }
  }
  try { session.abortController?.abort(); } catch (err) { console.warn('[BgProbe:STOP] abort err: ' + err.message); }
  try { session.channel?.end?.(); } catch {}
  try {
    session.query.close();
    console.warn('[BgProbe:STOP] query.close() ok');
  } catch (err) {
    console.error('[ClaudeSDK] stop error:', err.message);
  }
  // The stream loop's finally will fire (iterator ended by close): it does the
  // stopJsonlWatcher + sdkSessions.delete + claude-sdk:done. But that's async;
  // do it here too (idempotent) so a synchronous caller sees a clean state.
  stopJsonlWatcher(tabId);
  sdkSessions.delete(tabId);
  return { success: true, hard: true };
});

// Stop ONE background task (a single workflow agent / bash) WITHOUT closing the
// whole query — the rest of the workflow keeps running. Backs the `x` hotkey in
// WorkflowPanel. stopTask emits task_notification{status:'stopped'} which the
// renderer maps to BgTask.status='stopped'.
ipcMain.handle('claude-sdk:stop-task', async (event, { tabId, taskId }) => {
  const session = sdkSessions.get(tabId);
  if (!session || !session.query) return { success: false, error: 'no active session' };
  if (!taskId) return { success: false, error: 'no taskId' };
  try {
    await session.query.stopTask(taskId);
    console.warn('[BgProbe:STOP] stop-task(' + String(taskId).slice(0, 8) + ') ok tab=' + tabId.slice(-8));
    return { success: true };
  } catch (err) {
    console.warn('[BgProbe:STOP] stop-task(' + String(taskId).slice(0, 8) + ') err: ' + err.message);
    return { success: false, error: err.message };
  }
});

// Truncate session JSONL: drop everything from `targetUuid` to the end of the
// active branch. Used by Edit/Repeat in ClaudeSDKTab — both buttons rewrite
// history so the next message becomes the new branch tip. No compact entry,
// no relinking: the surviving prefix is the new chain root, last surviving
// record is the new tip (its UUID becomes the parent for the next message that
// `claude-sdk:send-message` writes via `--resume <sessionId>`).
//
// Parent-chain backtrace = same algorithm as Timeline / edit-range. We walk
// from the file's last record up via parentUuid, then cut the active branch at
// targetUuid (inclusive) and drop everything at-or-after that index, plus any
// records *not* in the active prefix (dead branches, stale bridges) so they
// can't beat the new tip on timestamp during `--resume`.
ipcMain.handle('claude-sdk:truncate-history', async (event, { sessionId, cwd, targetUuid, truncateAfter, userPosition }) => {
  // Two ways to point at the cut-off record:
  //   • `userPosition` (preferred, idempotent) — 0-based index среди type:'user'
  //     записей в активной ветке. Repeat/Edit пользуется только этим. Кликаешь
  //     5 раз на тот же чип → 5 раз вычисляется тот же N → 5 раз cut на одной
  //     и той же позиции. Никакой зависимости от msgId/placeholder/persisted.
  //   • `targetUuid` (legacy) + optional `truncateAfter:true` — оставлено
  //     для совместимости со старыми caller-ами (если есть).
  // Cut всегда **inclusive** (target и всё после уходит) для userPosition.
  console.log('[ClaudeSDK] truncate-history sid=' + sessionId?.slice(0, 8) + (typeof userPosition === 'number' ? ' userPos=' + userPosition : ' target=' + targetUuid?.slice(0, 8) + ' mode=' + (truncateAfter ? 'after' : 'inclusive')));
  if (!sessionId) return { success: false, error: 'sessionId required' };
  if (typeof userPosition !== 'number' && !targetUuid) return { success: false, error: 'userPosition or targetUuid required' };

  try {
    const found = findSessionFile(sessionId, cwd);
    if (!found) return { success: false, error: 'Session file not found' };
    const filePath = found.filePath;

    const content = await fs.promises.readFile(filePath, 'utf-8');
    const lines = content.split('\n').filter(l => l.trim());

    // Parse all records keeping originals so we can write back unchanged ones.
    const allRecords = [];
    const recordMap = new Map();
    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        allRecords.push({ entry, raw: line });
        if (entry.uuid) recordMap.set(entry.uuid, entry);
      } catch {
        // Preserve unparseable lines (proxy crashes can leave half-written records);
        // they'll be carried through unless they happen to come after targetUuid in
        // the file order, in which case we treat them as junk and drop them.
        allRecords.push({ entry: null, raw: line });
      }
    }

    // Build the active branch by walking parentUuid back from the last entry.
    const lastParseable = allRecords.filter(r => r.entry?.uuid).pop();
    if (!lastParseable) return { success: false, error: 'No parseable records' };

    const activeBranch = []; // entries from root → tip
    {
      let cur = lastParseable.entry.uuid;
      const seen = new Set();
      while (cur && !seen.has(cur)) {
        seen.add(cur);
        const rec = recordMap.get(cur);
        if (!rec) break;
        activeBranch.unshift(rec);
        cur = rec.logicalParentUuid || rec.parentUuid;
      }
    }

    let targetIdx = -1;
    if (typeof userPosition === 'number') {
      // Найти N-ный по счёту user-prompt в активной ветке. Кроме обычных
      // type:'user' учитываем также queued_command attachment'ы — они
      // тоже рендерятся в UI как user-bubble (mid-stream pushes), поэтому
      // их индекс в renderer'е попадает в userPos. Без этого Edit/Repeat
      // на queued-промпте резал не ту запись.
      // Sidechain'ы и tool_result'ы у нас в active branch не встречаются
      // (Timeline уже их отфильтровал на стороне renderer'а), но на
      // всякий — берём только чистые user-prompt'ы (без isSidechain
      // /parent_tool_use_id).
      const isUserPrompt = (e) => {
        if (e.type === 'attachment' && e.attachment && e.attachment.type === 'queued_command') return true;
        if (e.type !== 'user') return false;
        if (e.isSidechain) return false;
        if (e.parent_tool_use_id) return false;
        return true;
      };
      let seen = 0;
      for (let i = 0; i < activeBranch.length; i++) {
        const e = activeBranch[i];
        if (!isUserPrompt(e)) continue;
        if (seen === userPosition) { targetIdx = i; break; }
        seen++;
      }
      if (targetIdx === -1) {
        return { success: false, error: 'userPosition ' + userPosition + ' out of range (have ' + seen + ' user entries on active branch)' };
      }
    } else {
      if (!recordMap.has(targetUuid)) {
        return { success: false, error: 'targetUuid not in session file' };
      }
      targetIdx = activeBranch.findIndex(e => e.uuid === targetUuid);
      if (targetIdx === -1) {
        return { success: false, error: 'targetUuid not in active branch (probably belongs to a dead fork)' };
      }
    }

    // Surviving prefix. userPosition / inclusive (default): entries strictly
    // BEFORE targetIdx. truncateAfter mode: entries up to AND INCLUDING target.
    const survivingUuids = new Set();
    const cutoffIdx = (typeof userPosition !== 'number' && truncateAfter) ? targetIdx + 1 : targetIdx;
    for (let i = 0; i < cutoffIdx; i++) survivingUuids.add(activeBranch[i].uuid);

    // Cascade-drop orphans: any surviving record whose parent is no longer in the
    // surviving set must also go. Without this, a leftover dead-branch entry can
    // out-timestamp the new tip when Claude does `--resume`. Iterate to fixed point.
    const allKeptInitially = new Set(survivingUuids);
    let changed = true;
    while (changed) {
      changed = false;
      for (const r of allRecords) {
        if (!r.entry?.uuid) continue;
        if (!allKeptInitially.has(r.entry.uuid)) continue;
        const parent = r.entry.logicalParentUuid || r.entry.parentUuid;
        if (parent && !allKeptInitially.has(parent)) {
          allKeptInitially.delete(r.entry.uuid);
          changed = true;
        }
      }
    }

    const removedCount = allRecords.filter(r => r.entry?.uuid && !allKeptInitially.has(r.entry.uuid)).length;

    // Write back: keep records in original file order (stable), drop unwanted ones.
    // Header records without UUIDs (permission-mode, ai-title) survive — they're
    // file-level metadata, not part of the conversation chain.
    const outputLines = [];
    for (const r of allRecords) {
      if (!r.entry) continue; // skip junk lines unconditionally
      if (!r.entry.uuid) {
        outputLines.push(r.raw); // metadata header
        continue;
      }
      if (allKeptInitially.has(r.entry.uuid)) outputLines.push(r.raw);
    }

    // Atomic write — temp file + rename so a crash mid-write can't corrupt JSONL.
    const tmpPath = filePath + '.tmp-' + Date.now();
    await fs.promises.writeFile(tmpPath, outputLines.join('\n') + '\n', 'utf-8');
    await fs.promises.rename(tmpPath, filePath);

    console.log('[ClaudeSDK] truncate-history removed=' + removedCount + ' kept=' + outputLines.length);
    return { success: true, removed: removedCount };
  } catch (err) {
    console.error('[ClaudeSDK] truncate-history failed:', err.message);
    return { success: false, error: String(err.message || err) };
  }
});

// Mobile chat history loader. We can't reuse `getSessionMessages` from the
// Anthropic SDK because it returns a DIFFERENT set than parseTimelineEntries
// — the uuids don't intersect, so GoTo (which uses timeline uuids as anchors)
// never finds a match in the rendered chat. This handler reads the JSONL,
// walks the active branch via parentUuid (same algorithm as Timeline), and
// returns the records in chain order — user-prompts, assistant replies,
// tool_use blocks, AND tool_result entries (the latter are needed so the
// reducer can resolve tool statuses). Anchors then line up perfectly.
ipcMain.handle('claude-sdk:active-branch-messages', async (event, { sessionId, cwd }) => {
  if (!sessionId) return { success: false, error: 'sessionId required', messages: [] };
  const t0 = Date.now();
  const sidShort = sessionId.slice(0, 8);
  try {
    const tFind0 = Date.now();
    const found = findSessionFile(sessionId, cwd);
    const findMs = Date.now() - tFind0;
    if (!found) {
      console.log(`[SDKHistory:Main] sid=${sidShort} NOT_FOUND findMs=${findMs}`);
      return { success: false, error: 'session file not found', messages: [] };
    }
    let fileSize = 0;
    try { fileSize = require('fs').statSync(found.filePath).size; } catch {}
    const tRead0 = Date.now();
    const content = require('fs').readFileSync(found.filePath, 'utf-8');
    const readMs = Date.now() - tRead0;
    const tParse0 = Date.now();
    const lines = content.trim().split('\n').filter(l => l.trim());
    const recordMap = new Map();
    let last = null;
    for (const line of lines) {
      try {
        const e = JSON.parse(line);
        if (e.uuid) { recordMap.set(e.uuid, e); last = e; }
      } catch {}
    }
    const parseMs = Date.now() - tParse0;
    if (!last) {
      console.log(`[SDKHistory:Main] sid=${sidShort} sizeKB=${(fileSize/1024).toFixed(0)} lines=${lines.length} EMPTY totalMs=${Date.now()-t0}`);
      return { success: true, messages: [] };
    }
    // Active branch = walk back from last via parentUuid, then reverse.
    const tWalk0 = Date.now();
    const branch = [];
    let cur = last.uuid;
    const seen = new Set();
    while (cur && !seen.has(cur)) {
      seen.add(cur);
      const rec = recordMap.get(cur);
      if (!rec) break;
      branch.unshift(rec);
      cur = rec.logicalParentUuid || rec.parentUuid;
    }
    const walkMs = Date.now() - tWalk0;
    const totalMs = Date.now() - t0;
    console.log(`[SDKHistory:Main] sid=${sidShort} sizeKB=${(fileSize/1024).toFixed(0)} lines=${lines.length} branchLen=${branch.length} findMs=${findMs} readMs=${readMs} parseMs=${parseMs} walkMs=${walkMs} totalMs=${totalMs}`);
    return { success: true, messages: branch };
  } catch (err) {
    console.error('[SDKHistory:Main] sid=' + sidShort + ' failed:', err.message);
    return { success: false, error: String(err.message || err), messages: [] };
  }
});

// Mobile-web Timeline view. Returns active-branch entries with previews,
// full text, color band, and tool calls. Wraps parseTimelineEntries —
// shared with the desktop Timeline (single source of truth for the JSONL
// backtrace algorithm).
ipcMain.handle('claude-sdk:timeline-entries', async (event, { sessionId, cwd }) => {
  if (!sessionId) return { success: false, error: 'sessionId required', entries: [] };
  try {
    const found = findSessionFile(sessionId, cwd);
    if (!found) return { success: false, error: 'session file not found', entries: [] };
    const entries = parseTimelineEntries(found.filePath);
    return { success: true, entries, sessionId, filePath: found.filePath };
  } catch (err) {
    console.error('[ClaudeSDK] timeline-entries failed:', err.message);
    return { success: false, error: String(err.message || err), entries: [] };
  }
});

// Fork an existing Claude session JSONL into a new sessionId WITHOUT spawning
// Claude. Used by mobile: long-press on a PTY claude tab → "Fork into SDK"
// makes a copy of the session and points a new SDK tab at it. The actual SDK
// run starts later when the user (or mobile) sends the first prompt — Claude
// CLI's --resume <newSessionId> picks up the copied JSONL on disk.
ipcMain.handle('claude-sdk:fork-from-session', async (event, { sessionId, cwd }) => {
  console.log('[ClaudeSDK] fork-from-session sid=' + sessionId?.slice(0, 8));
  if (!sessionId) return { success: false, error: 'sessionId required' };
  try {
    const claudeProjectsDir = path.join(os.homedir(), '.claude', 'projects');
    const projectSlug = (cwd || process.cwd()).replace(/\//g, '-');
    const primaryDir = path.join(claudeProjectsDir, projectSlug);
    const primaryPath = path.join(primaryDir, `${sessionId}.jsonl`);

    let sourcePath = null;
    if (fs.existsSync(primaryPath)) {
      sourcePath = primaryPath;
    } else if (fs.existsSync(claudeProjectsDir)) {
      // Search every project dir
      const dirs = fs.readdirSync(claudeProjectsDir, { withFileTypes: true })
        .filter(d => d.isDirectory()).map(d => d.name);
      for (const dir of dirs) {
        const p = path.join(claudeProjectsDir, dir, `${sessionId}.jsonl`);
        if (fs.existsSync(p)) { sourcePath = p; break; }
      }
    }
    if (!sourcePath) return { success: false, error: 'source JSONL not found for ' + sessionId };

    const newSessionId = crypto.randomUUID();
    if (!fs.existsSync(primaryDir)) fs.mkdirSync(primaryDir, { recursive: true });
    const destPath = path.join(primaryDir, `${newSessionId}.jsonl`);
    fs.copyFileSync(sourcePath, destPath);

    // Mark the fork in DB so Timeline can show the boundary in both sessions
    try {
      const entryUuids = parseTimelineUuids(sourcePath);
      projectManager.db.saveForkMarker(sessionId, newSessionId, entryUuids);
    } catch (e) { console.warn('[ClaudeSDK] fork marker save error:', e.message); }

    console.log('[ClaudeSDK] forked ' + sessionId.slice(0, 8) + ' → ' + newSessionId.slice(0, 8));
    return { success: true, newSessionId, cwd: cwd || process.cwd() };
  } catch (err) {
    console.error('[ClaudeSDK] fork-from-session failed:', err.message);
    return { success: false, error: String(err.message || err) };
  }
});
